INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 8, 14, E'And he put garrisons in Edom; throughout all Edom put he garrisons, and all they of Edom became Davidâ€™s servants. And the LORD preserved David whithersoever he went.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 8, 15, E'And David reigned over all Israel; and David executed judgment and justice unto all his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 8, 16, E'And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud was recorder;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 8, 17, E'And Zadok the son of Ahitub, and Ahimelech the son of Abiathar, were the priests; and Seraiah was the scribe;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 8, 18, E'And Benaiah the son of Jehoiada was over both the Cherethites and the Pelethites; and Davidâ€™s sons were chief rulers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 1, E'And David said, Is there yet any that is left of the house of Saul, that I may shew him kindness for Jonathanâ€™s sake?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 2, E'And there was of the house of Saul a servant whose name was Ziba. And when they had called him unto David, the king said unto him, Art thou Ziba? And he said, Thy servant is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 3, E'And the king said, Is there not yet any of the house of Saul, that I may shew the kindness of God unto him? And Ziba said unto the king, Jonathan hath yet a son, which is lame on his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 4, E'And the king said unto him, Where is he? And Ziba said unto the king, Behold, he is in the house of Machir, the son of Ammiel, in Lodebar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 5, E'Then king David sent, and fetched him out of the house of Machir, the son of Ammiel, from Lodebar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 6, E'Now when Mephibosheth, the son of Jonathan, the son of Saul, was come unto David, he fell on his face, and did reverence. And David said, Mephibosheth. And he answered, Behold thy servant!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 7, E'And David said unto him, Fear not: for I will surely shew thee kindness for Jonathan thy fatherâ€™s sake, and will restore thee all the land of Saul thy father; and thou shalt eat bread at my table continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 8, E'And he bowed himself, and said, What is thy servant, that thou shouldest look upon such a dead dog as I am?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 9, E'Then the king called to Ziba, Saulâ€™s servant, and said unto him, I have given unto thy masterâ€™s son all that pertained to Saul and to all his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 10, E'Thou therefore, and thy sons, and thy servants, shall till the land for him, and thou shalt bring in the fruits, that thy masterâ€™s son may have food to eat: but Mephibosheth thy masterâ€™s son shall eat bread alway at my table. Now Ziba had fifteen sons and twenty servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 11, E'Then said Ziba unto the king, According to all that my lord the king hath commanded his servant, so shall thy servant do. As for Mephibosheth, said the king, he shall eat at my table, as one of the kingâ€™s sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 12, E'And Mephibosheth had a young son, whose name was Micha. And all that dwelt in the house of Ziba were servants unto Mephibosheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 9, 13, E'So Mephibosheth dwelt in Jerusalem: for he did eat continually at the kingâ€™s table; and was lame on both his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 1, E'And it came to pass after this, that the king of the children of Ammon died, and Hanun his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 2, E'Then said David, I will shew kindness unto Hanun the son of Nahash, as his father shewed kindness unto me. And David sent to comfort him by the hand of his servants for his father. And Davidâ€™s servants came into the land of the children of Ammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 3, E'And the princes of the children of Ammon said unto Hanun their lord, Thinkest thou that David doth honour thy father, that he hath sent comforters unto thee? hath not David rather sent his servants unto thee, to search the city, and to spy it out, and to overthrow it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 4, E'Wherefore Hanun took Davidâ€™s servants, and shaved off the one half of their beards, and cut off their garments in the middle, even to their buttocks, and sent them away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 5, E'When they told it unto David, he sent to meet them, because the men were greatly ashamed: and the king said, Tarry at Jericho until your beards be grown, and then return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 6, E'And when the children of Ammon saw that they stank before David, the children of Ammon sent and hired the Syrians of Bethrehob, and the Syrians of Zoba, twenty thousand footmen, and of king Maacah a thousand men, and of Ishtob twelve thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 7, E'And when David heard of it, he sent Joab, and all the host of the mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 8, E'And the children of Ammon came out, and put the battle in array at the entering in of the gate: and the Syrians of Zoba, and of Rehob, and Ishtob, and Maacah, were by themselves in the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 9, E'When Joab saw that the front of the battle was against him before and behind, he chose of all the choice men of Israel, and put them in array against the Syrians:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 10, E'And the rest of the people he delivered into the hand of Abishai his brother, that he might put them in array against the children of Ammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 11, E'And he said, If the Syrians be too strong for me, then thou shalt help me: but if the children of Ammon be too strong for thee, then I will come and help thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 12, E'Be of good courage, and let us play the men for our people, and for the cities of our God: and the LORD do that which seemeth him good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 13, E'And Joab drew nigh, and the people that were with him, unto the battle against the Syrians: and they fled before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 14, E'And when the children of Ammon saw that the Syrians were fled, then fled they also before Abishai, and entered into the city. So Joab returned from the children of Ammon, and came to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 15, E'And when the Syrians saw that they were smitten before Israel, they gathered themselves together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 16, E'And Hadarezer sent, and brought out the Syrians that were beyond the river: and they came to Helam; and Shobach the captain of the host of Hadarezer went before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 17, E'And when it was told David, he gathered all Israel together, and passed over Jordan, and came to Helam. And the Syrians set themselves in array against David, and fought with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 18, E'And the Syrians fled before Israel; and David slew the men of seven hundred chariots of the Syrians, and forty thousand horsemen, and smote Shobach the captain of their host, who died there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 10, 19, E'And when all the kings that were servants to Hadarezer saw that they were smitten before Israel, they made peace with Israel, and served them. So the Syrians feared to help the children of Ammon any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 1, E'And it came to pass, after the year was expired, at the time when kings go forth to battle, that David sent Joab, and his servants with him, and all Israel; and they destroyed the children of Ammon, and besieged Rabbah. But David tarried still at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 2, E'And it came to pass in an eveningtide, that David arose from off his bed, and walked upon the roof of the kingâ€™s house: and from the roof he saw a woman washing herself; and the woman was very beautiful to look upon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 3, E'And David sent and enquired after the woman. And one said, Is not this Bathsheba, the daughter of Eliam, the wife of Uriah the Hittite?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 4, E'And David sent messengers, and took her; and she came in unto him, and he lay with her; for she was purified from her uncleanness: and she returned unto her house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 5, E'And the woman conceived, and sent and told David, and said, I am with child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 6, E'And David sent to Joab, saying, Send me Uriah the Hittite. And Joab sent Uriah to David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 7, E'And when Uriah was come unto him, David demanded of him how Joab did, and how the people did, and how the war prospered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 8, E'And David said to Uriah, Go down to thy house, and wash thy feet. And Uriah departed out of the kingâ€™s house, and there followed him a mess of meat from the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 9, E'But Uriah slept at the door of the kingâ€™s house with all the servants of his lord, and went not down to his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 10, E'And when they had told David, saying, Uriah went not down unto his house, David said unto Uriah, Camest thou not from thy journey? why then didst thou not go down unto thine house?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 11, E'And Uriah said unto David, The ark, and Israel, and Judah, abide in tents; and my lord Joab, and the servants of my lord, are encamped in the open fields; shall I then go into mine house, to eat and to drink, and to lie with my wife? as thou livest, and as thy soul liveth, I will not do this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 12, E'And David said to Uriah, Tarry here to day also, and to morrow I will let thee depart. So Uriah abode in Jerusalem that day, and the morrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 13, E'And when David had called him, he did eat and drink before him; and he made him drunk: and at even he went out to lie on his bed with the servants of his lord, but went not down to his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 14, E'And it came to pass in the morning, that David wrote a letter to Joab, and sent it by the hand of Uriah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 15, E'And he wrote in the letter, saying, Set ye Uriah in the forefront of the hottest battle, and retire ye from him, that he may be smitten, and die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 16, E'And it came to pass, when Joab observed the city, that he assigned Uriah unto a place where he knew that valiant men were.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 17, E'And the men of the city went out, and fought with Joab: and there fell some of the people of the servants of David; and Uriah the Hittite died also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 18, E'Then Joab sent and told David all the things concerning the war;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 19, E'And charged the messenger, saying, When thou hast made an end of telling the matters of the war unto the king,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 20, E'And if so be that the kingâ€™s wrath arise, and he say unto thee, Wherefore approached ye so nigh unto the city when ye did fight? knew ye not that they would shoot from the wall?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 21, E'Who smote Abimelech the son of Jerubbesheth? did not a woman cast a piece of a millstone upon him from the wall, that he died in Thebez? why went ye nigh the wall? then say thou, Thy servant Uriah the Hittite is dead also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 22, E'So the messenger went, and came and shewed David all that Joab had sent him for.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 23, E'And the messenger said unto David, Surely the men prevailed against us, and came out unto us into the field, and we were upon them even unto the entering of the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 24, E'And the shooters shot from off the wall upon thy servants; and some of the kingâ€™s servants be dead, and thy servant Uriah the Hittite is dead also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 25, E'Then David said unto the messenger, Thus shalt thou say unto Joab, Let not this thing displease thee, for the sword devoureth one as well as another: make thy battle more strong against the city, and overthrow it: and encourage thou him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 26, E'And when the wife of Uriah heard that Uriah her husband was dead, she mourned for her husband.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 11, 27, E'And when the mourning was past, David sent and fetched her to his house, and she became his wife, and bare him a son. But the thing that David had done displeased the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 1, E'And the LORD sent Nathan unto David. And he came unto him, and said unto him, There were two men in one city; the one rich, and the other poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 2, E'The rich man had exceeding many flocks and herds:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 3, E'But the poor man had nothing, save one little ewe lamb, which he had bought and nourished up: and it grew up together with him, and with his children; it did eat of his own meat, and drank of his own cup, and lay in his bosom, and was unto him as a daughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 4, E'And there came a traveller unto the rich man, and he spared to take of his own flock and of his own herd, to dress for the wayfaring man that was come unto him; but took the poor manâ€™s lamb, and dressed it for the man that was come to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 5, E'And Davidâ€™s anger was greatly kindled against the man; and he said to Nathan, As the LORD liveth, the man that hath done this thing shall surely die:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 6, E'And he shall restore the lamb fourfold, because he did this thing, and because he had no pity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 7, E'And Nathan said to David, Thou art the man. Thus saith the LORD God of Israel, I anointed thee king over Israel, and I delivered thee out of the hand of Saul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 8, E'And I gave thee thy masterâ€™s house, and thy masterâ€™s wives into thy bosom, and gave thee the house of Israel and of Judah; and if that had been too little, I would moreover have given unto thee such and such things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 9, E'Wherefore hast thou despised the commandment of the LORD, to do evil in his sight? thou hast killed Uriah the Hittite with the sword, and hast taken his wife to be thy wife, and hast slain him with the sword of the children of Ammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 10, E'Now therefore the sword shall never depart from thine house; because thou hast despised me, and hast taken the wife of Uriah the Hittite to be thy wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 11, E'Thus saith the LORD, Behold, I will raise up evil against thee out of thine own house, and I will take thy wives before thine eyes, and give them unto thy neighbour, and he shall lie with thy wives in the sight of this sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 12, E'For thou didst it secretly: but I will do this thing before all Israel, and before the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 13, E'And David said unto Nathan, I have sinned against the LORD. And Nathan said unto David, The LORD also hath put away thy sin; thou shalt not die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 14, E'Howbeit, because by this deed thou hast given great occasion to the enemies of the LORD to blaspheme, the child also that is born unto thee shall surely die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 15, E'And Nathan departed unto his house. And the LORD struck the child that Uriahâ€™s wife bare unto David, and it was very sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 16, E'David therefore besought God for the child; and David fasted, and went in, and lay all night upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 17, E'And the elders of his house arose, and went to him, to raise him up from the earth: but he would not, neither did he eat bread with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 18, E'And it came to pass on the seventh day, that the child died. And the servants of David feared to tell him that the child was dead: for they said, Behold, while the child was yet alive, we spake unto him, and he would not hearken unto our voice: how will he then vex himself, if we tell him that the child is dead?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 19, E'But when David saw that his servants whispered, David perceived that the child was dead: therefore David said unto his servants, Is the child dead? And they said, He is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 20, E'Then David arose from the earth, and washed, and anointed himself, and changed his apparel, and came into the house of the LORD, and worshipped: then he came to his own house; and when he required, they set bread before him, and he did eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 21, E'Then said his servants unto him, What thing is this that thou hast done? thou didst fast and weep for the child, while it was alive; but when the child was dead, thou didst rise and eat bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 22, E'And he said, While the child was yet alive, I fasted and wept: for I said, Who can tell whether GOD will be gracious to me, that the child may live?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 23, E'But now he is dead, wherefore should I fast? can I bring him back again? I shall go to him, but he shall not return to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 24, E'And David comforted Bathsheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 25, E'And he sent by the hand of Nathan the prophet; and he called his name Jedidiah, because of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 26, E'And Joab fought against Rabbah of the children of Ammon, and took the royal city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 27, E'And Joab sent messengers to David, and said, I have fought against Rabbah, and have taken the city of waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 28, E'Now therefore gather the rest of the people together, and encamp against the city, and take it: lest I take the city, and it be called after my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 29, E'And David gathered all the people together, and went to Rabbah, and fought against it, and took it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 30, E'And he took their kingâ€™s crown from off his head, the weight whereof was a talent of gold with the precious stones: and it was set on Davidâ€™s head. And he brought forth the spoil of the city in great abundance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 12, 31, E'And he brought forth the people that were therein, and put them under saws, and under harrows of iron, and under axes of iron, and made them pass through the brick-kiln: and thus did he unto all the cities of the children of Ammon. So David and all the people returned unto Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 1, E'And it came to pass after this, that Absalom the son of David had a fair sister, whose name was Tamar; and Amnon the son of David loved her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 2, E'And Amnon was so vexed, that he fell sick for his sister Tamar; for she was a virgin; and Amnon thought it hard for him to do anything to her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 3, E'But Amnon had a friend, whose name was Jonadab, the son of Shimeah Davidâ€™s brother: and Jonadab was a very subtil man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 4, E'And he said unto him, Why art thou, being the kingâ€™s son, lean from day to day? wilt thou not tell me? And Amnon said unto him, I love Tamar, my brother Absalomâ€™s sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 5, E'And Jonadab said unto him, Lay thee down on thy bed, and make thyself sick: and when thy father cometh to see thee, say unto him, I pray thee, let my sister Tamar come, and give me meat, and dress the meat in my sight, that I may see it, and eat it at her hand.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Samuel') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 6, E'So Amnon lay down, and made himself sick: and when the king was come to see him, Amnon said unto the king, I pray thee, let Tamar my sister come, and make me a couple of cakes in my sight, that I may eat at her hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 7, E'Then David sent home to Tamar, saying, Go now to thy brother Amnonâ€™s house, and dress him meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 8, E'So Tamar went to her brother Amnonâ€™s house; and he was laid down. And she took flour, and kneaded it, and made cakes in his sight, and did bake the cakes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 9, E'And she took a pan, and poured them out before him; but he refused to eat. And Amnon said, Have out all men from me. And they went out every man from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 10, E'And Amnon said unto Tamar, Bring the meat into the chamber, that I may eat of thine hand. And Tamar took the cakes which she had made, and brought them into the chamber to Amnon her brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 11, E'And when she had brought them unto him to eat, he took hold of her, and said unto her, Come lie with me, my sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 12, E'And she answered him, Nay, my brother, do not force me; for no such thing ought to be done in Israel: do not thou this folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 13, E'And I, whither shall I cause my shame to go? and as for thee, thou shalt be as one of the fools in Israel. Now therefore, I pray thee, speak unto the king; for he will not withhold me from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 14, E'Howbeit he would not hearken unto her voice: but, being stronger than she, forced her, and lay with her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 15, E'Then Amnon hated her exceedingly; so that the hatred wherewith he hated her was greater than the love wherewith he had loved her. And Amnon said unto her, Arise, be gone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 16, E'And she said unto him, There is no cause: this evil in sending me away is greater than the other that thou didst unto me. But he would not hearken unto her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 17, E'Then he called his servant that ministered unto him, and said, Put now this woman out from me, and bolt the door after her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 18, E'And she had a garment of divers colours upon her: for with such robes were the kingâ€™s daughters that were virgins apparelled. Then his servant brought her out, and bolted the door after her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 19, E'And Tamar put ashes on her head, and rent her garment of divers colours that was on her, and laid her hand on her head, and went on crying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 20, E'And Absalom her brother said unto her, Hath Amnon thy brother been with thee? but hold now thy peace, my sister: he is thy brother; regard not this thing. So Tamar remained desolate in her brother Absalomâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 21, E'But when king David heard of all these things, he was very wroth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 22, E'And Absalom spake unto his brother Amnon neither good nor bad: for Absalom hated Amnon, because he had forced his sister Tamar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 23, E'And it came to pass after two full years, that Absalom had sheepshearers in Baalhazor, which is beside Ephraim: and Absalom invited all the kingâ€™s sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 24, E'And Absalom came to the king, and said, Behold now, thy servant hath sheepshearers; let the king, I beseech thee, and his servants go with thy servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 25, E'And the king said to Absalom, Nay, my son, let us not all now go, lest we be chargeable unto thee. And he pressed him: howbeit he would not go, but blessed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 26, E'Then said Absalom, If not, I pray thee, let my brother Amnon go with us. And the king said unto him, Why should he go with thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 27, E'But Absalom pressed him, that he let Amnon and all the kingâ€™s sons go with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 28, E'Now Absalom had commanded his servants, saying, Mark ye now when Amnonâ€™s heart is merry with wine, and when I say unto you, Smite Amnon; then kill him, fear not: have not I commanded you? be courageous, and be valiant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 29, E'And the servants of Absalom did unto Amnon as Absalom had commanded. Then all the kingâ€™s sons arose, and every man gat him up upon his mule, and fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 30, E'And it came to pass, while they were in the way, that tidings came to David, saying, Absalom hath slain all the kingâ€™s sons, and there is not one of them left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 31, E'Then the king arose, and tare his garments, and lay on the earth; and all his servants stood by with their clothes rent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 32, E'And Jonadab, the son of Shimeah Davidâ€™s brother, answered and said, Let not my lord suppose that they have slain all the young men the kingâ€™s sons; for Amnon only is dead: for by the appointment of Absalom this hath been determined from the day that he forced his sister Tamar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 33, E'Now therefore let not my lord the king take the thing to his heart, to think that all the kingâ€™s sons are dead: for Amnon only is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 34, E'But Absalom fled. And the young man that kept the watch lifted up his eyes, and looked, and, behold, there came much people by the way of the hill side behind him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 35, E'And Jonadab said unto the king, Behold, the kingâ€™s sons come: as thy servant said, so it is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 36, E'And it came to pass, as soon as he had made an end of speaking, that, behold, the kingâ€™s sons came, and lifted up their voice and wept: and the king also and all his servants wept very sore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 37, E'But Absalom fled, and went to Talmai, the son of Ammihud, king of Geshur. And David mourned for his son every day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 38, E'So Absalom fled, and went to Geshur, and was there three years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 13, 39, E'And the soul of king David longed to go forth unto Absalom: for he was comforted concerning Amnon, seeing he was dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 1, E'Now Joab the son of Zeruiah perceived that the kingâ€™s heart was toward Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 2, E'And Joab sent to Tekoah, and fetched thence a wise woman, and said unto her, I pray thee, feign thyself to be a mourner, and put on now mourning apparel, and anoint not thyself with oil, but be as a woman that had a long time mourned for the dead:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 3, E'And come to the king, and speak on this manner unto him. So Joab put the words in her mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 4, E'And when the woman of Tekoah spake to the king, she fell on her face to the ground, and did obeisance, and said, Help, O king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 5, E'And the king said unto her, What aileth thee? And she answered, I am indeed a widow woman, and mine husband is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 6, E'And thy handmaid had two sons, and they two strove together in the field, and there was none to part them, but the one smote the other, and slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 7, E'And, behold, the whole family is risen against thine handmaid, and they said, Deliver him that smote his brother, that we may kill him, for the life of his brother whom he slew; and we will destroy the heir also: and so they shall quench my coal which is left, and shall not leave to my husband neither name nor remainder upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 8, E'And the king said unto the woman, Go to thine house, and I will give charge concerning thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 9, E'And the woman of Tekoah said unto the king, My lord, O king, the iniquity be on me, and on my fatherâ€™s house: and the king and his throne be guiltless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 10, E'And the king said, Whosoever saith ought unto thee, bring him to me, and he shall not touch thee any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 11, E'Then said she, I pray thee, let the king remember the LORD thy God, that thou wouldest not suffer the revengers of blood to destroy any more, lest they destroy my son. And he said, As the LORD liveth, there shall not one hair of thy son fall to the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 12, E'Then the woman said, Let thine handmaid, I pray thee, speak one word unto my lord the king. And he said, Say on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 13, E'And the woman said, Wherefore then hast thou thought such a thing against the people of God? for the king doth speak this thing as one which is faulty, in that the king doth not fetch home again his banished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 14, E'For we must needs die, and are as water spilt on the ground, which cannot be gathered up again; neither doth God respect any person: yet doth he devise means, that his banished be not expelled from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 15, E'Now therefore that I am come to speak of this thing unto my lord the king, it is because the people have made me afraid: and thy handmaid said, I will now speak unto the king; it may be that the king will perform the request of his handmaid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 16, E'For the king will hear, to deliver his handmaid out of the hand of the man that would destroy me and my son together out of the inheritance of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 17, E'Then thine handmaid said, The word of my lord the king shall now be comfortable: for as an angel of God, so is my lord the king to discern good and bad: therefore the LORD thy God will be with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 18, E'Then the king answered and said unto the woman, Hide not from me, I pray thee, the thing that I shall ask thee. And the woman said, Let my lord the king now speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 19, E'And the king said, Is not the hand of Joab with thee in all this? And the woman answered and said, As thy soul liveth, my lord the king, none can turn to the right hand or to the left from ought that my lord the king hath spoken: for thy servant Joab, he bade me, and he put all these words in the mouth of thine handmaid:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 20, E'To fetch about this form of speech hath thy servant Joab done this thing: and my lord is wise, according to the wisdom of an angel of God, to know all things that are in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 21, E'And the king said unto Joab, Behold now, I have done this thing: go therefore, bring the young man Absalom again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 22, E'And Joab fell to the ground on his face, and bowed himself, and thanked the king: and Joab said, To day thy servant knoweth that I have found grace in thy sight, my lord, O king, in that the king hath fulfilled the request of his servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 23, E'So Joab arose and went to Geshur, and brought Absalom to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 24, E'And the king said, Let him turn to his own house, and let him not see my face. So Absalom returned to his own house, and saw not the kingâ€™s face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 25, E'But in all Israel there was none to be so much praised as Absalom for his beauty: from the sole of his foot even to the crown of his head there was no blemish in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 26, E'And when he polled his head, (for it was at every yearâ€™s end that he polled it: because the hair was heavy on him, therefore he polled it:) he weighed the hair of his head at two hundred shekels after the kingâ€™s weight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 27, E'And unto Absalom there were born three sons, and one daughter, whose name was Tamar: she was a woman of a fair countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 28, E'So Absalom dwelt two full years in Jerusalem, and saw not the kingâ€™s face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 29, E'Therefore Absalom sent for Joab, to have sent him to the king; but he would not come to him: and when he sent again the second time, he would not come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 30, E'Therefore he said unto his servants, See, Joabâ€™s field is near mine, and he hath barley there; go and set it on fire. And Absalomâ€™s servants set the field on fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 31, E'Then Joab arose, and came to Absalom unto his house, and said unto him, Wherefore have thy servants set my field on fire?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 32, E'And Absalom answered Joab, Behold, I sent unto thee, saying, Come hither, that I may send thee to the king, to say, Wherefore am I come from Geshur? it had been good for me to have been there still: now therefore let me see the kingâ€™s face; and if there be any iniquity in me, let him kill me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 14, 33, E'So Joab came to the king, and told him: and when he had called for Absalom, he came to the king, and bowed himself on his face to the ground before the king: and the king kissed Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 1, E'And it came to pass after this, that Absalom prepared him chariots and horses, and fifty men to run before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 2, E'And Absalom rose up early, and stood beside the way of the gate: and it was so, that when any man that had a controversy came to the king for judgment, then Absalom called unto him, and said, Of what city art thou? And he said, Thy servant is of one of the tribes of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 3, E'And Absalom said unto him, See, thy matters are good and right; but there is no man deputed of the king to hear thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 4, E'Absalom said moreover, Oh that I were made judge in the land, that every man which hath any suit or cause might come unto me, and I would do him justice!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 5, E'And it was so, that when any man came nigh to him to do him obeisance, he put forth his hand, and took him, and kissed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 6, E'And on this manner did Absalom to all Israel that came to the king for judgment: so Absalom stole the hearts of the men of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 7, E'And it came to pass after forty years, that Absalom said unto the king, I pray thee, let me go and pay my vow, which I have vowed unto the LORD, in Hebron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 8, E'For thy servant vowed a vow while I abode at Geshur in Syria, saying, If the LORD shall bring me again indeed to Jerusalem, then I will serve the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 9, E'And the king said unto him, Go in peace. So he arose, and went to Hebron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 10, E'But Absalom sent spies throughout all the tribes of Israel, saying, As soon as ye hear the sound of the trumpet, then ye shall say, Absalom reigneth in Hebron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 11, E'And with Absalom went two hundred men out of Jerusalem, that were called; and they went in their simplicity, and they knew not any thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 12, E'And Absalom sent for Ahithophel the Gilonite, Davidâ€™s counsellor, from his city, even from Giloh, while he offered sacrifices. And the conspiracy was strong; for the people increased continually with Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 13, E'And there came a messenger to David, saying, The hearts of the men of Israel are after Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 14, E'And David said unto all his servants that were with him at Jerusalem, Arise, and let us flee; for we shall not else escape from Absalom: make speed to depart, lest he overtake us suddenly, and bring evil upon us, and smite the city with the edge of the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 15, E'And the kingâ€™s servants said unto the king, Behold, thy servants are ready to do whatsoever my lord the king shall appoint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 16, E'And the king went forth, and all his household after him. And the king left ten women, which were concubines, to keep the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 17, E'And the king went forth, and all the people after him, and tarried in a place that was far off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 18, E'And all his servants passed on beside him; and all the Cherethites, and all the Pelethites, and all the Gittites, six hundred men which came after him from Gath, passed on before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 19, E'Then said the king to Ittai the Gittite, Wherefore goest thou also with us? return to thy place, and abide with the king: for thou art a stranger, and also an exile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 20, E'Whereas thou camest but yesterday, should I this day make thee go up and down with us? seeing I go whither I may, return thou, and take back thy brethren: mercy and truth be with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 21, E'And Ittai answered the king, and said, As the LORD liveth, and as my lord the king liveth, surely in what place my lord the king shall be, whether in death or life, even there also will thy servant be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 22, E'And David said to Ittai, Go and pass over. And Ittai the Gittite passed over, and all his men, and all the little ones that were with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 23, E'And all the country wept with a loud voice, and all the people passed over: the king also himself passed over the brook Kidron, and all the people passed over, toward the way of the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 24, E'And lo Zadok also, and all the Levites were with him, bearing the ark of the covenant of God: and they set down the ark of God; and Abiathar went up, until all the people had done passing out of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 25, E'And the king said unto Zadok, Carry back the ark of God into the city: if I shall find favour in the eyes of the LORD, he will bring me again, and shew me both it, and his habitation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 26, E'But if he thus say, I have no delight in thee; behold, here am I, let him do to me as seemeth good unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 27, E'The king said also unto Zadok the priest, Art not thou a seer? return into the city in peace, and your two sons with you, Ahimaaz thy son, and Jonathan the son of Abiathar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 28, E'See, I will tarry in the plain of the wilderness, until there come word from you to certify me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 29, E'Zadok therefore and Abiathar carried the ark of God again to Jerusalem: and they tarried there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 30, E'And David went up by the ascent of mount Olivet, and wept as he went up, and had his head covered, and he went barefoot: and all the people that was with him covered every man his head, and they went up, weeping as they went up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 31, E'And one told David, saying, Ahithophel is among the conspirators with Absalom. And David said, O LORD, I pray thee, turn the counsel of Ahithophel into foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 32, E'And it came to pass, that when David was come to the top of the mount, where he worshipped God, behold, Hushai the Archite came to meet him with his coat rent, and earth upon his head:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 33, E'Unto whom David said, If thou passest on with me, then thou shalt be a burden unto me:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Samuel') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 34, E'But if thou return to the city, and say unto Absalom, I will be thy servant, O king; as I have been thy fatherâ€™s servant hitherto, so will I now also be thy servant: then mayest thou for me defeat the counsel of Ahithophel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 35, E'And hast thou not there with thee Zadok and Abiathar the priests? therefore it shall be, that what thing soever thou shalt hear out of the kingâ€™s house, thou shalt tell it to Zadok and Abiathar the priests.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 36, E'Behold, they have there with them their two sons, Ahimaaz Zadokâ€™s son, and Jonathan Abiatharâ€™s son; and by them ye shall send unto me every thing that ye can hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 15, 37, E'So Hushai Davidâ€™s friend came into the city, and Absalom came into Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 1, E'And when David was a little past the top of the hill, behold, Ziba the servant of Mephibosheth met him, with a couple of asses saddled, and upon them two hundred loaves of bread, and an hundred bunches of raisins, and an hundred of summer fruits, and a bottle of wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 2, E'And the king said unto Ziba, What meanest thou by these? And Ziba said, The asses be for the kingâ€™s household to ride on; and the bread and summer fruit for the young men to eat; and the wine, that such as be faint in the wilderness may drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 3, E'And the king said, And where is thy masterâ€™s son? And Ziba said unto the king, Behold, he abideth at Jerusalem: for he said, To day shall the house of Israel restore me the kingdom of my father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 4, E'Then said the king to Ziba, Behold, thine are all that pertained unto Mephibosheth. And Ziba said, I humbly beseech thee that I may find grace in thy sight, my lord, O king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 5, E'And when king David came to Bahurim, behold, thence came out a man of the family of the house of Saul, whose name was Shimei, the son of Gera: he came forth, and cursed still as he came.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 6, E'And he cast stones at David, and at all the servants of king David: and all the people and all the mighty men were on his right hand and on his left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 7, E'And thus said Shimei when he cursed, Come out, come out, thou bloody man, and thou man of Belial:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 8, E'The LORD hath returned upon thee all the blood of the house of Saul, in whose stead thou hast reigned; and the LORD hath delivered the kingdom into the hand of Absalom thy son: and, behold, thou art taken in thy mischief, because thou art a bloody man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 9, E'Then said Abishai the son of Zeruiah unto the king, Why should this dead dog curse my lord the king? let me go over, I pray thee, and take off his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 10, E'And the king said, What have I to do with you, ye sons of Zeruiah? so let him curse, because the LORD hath said unto him, Curse David. Who shall then say, Wherefore hast thou done so?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 11, E'And David said to Abishai, and to all his servants, Behold, my son, which came forth of my bowels, seeketh my life: how much more now may this Benjamite do it? let him alone, and let him curse; for the LORD hath bidden him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 12, E'It may be that the LORD will look on mine affliction, and that the LORD will requite me good for his cursing this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 13, E'And as David and his men went by the way, Shimei went along on the hillâ€™s side over against him, and cursed as he went, and threw stones at him, and cast dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 14, E'And the king, and all the people that were with him, came weary, and refreshed themselves there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 15, E'And Absalom, and all the people the men of Israel, came to Jerusalem, and Ahithophel with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 16, E'And it came to pass, when Hushai the Archite, Davidâ€™s friend, was come unto Absalom, that Hushai said unto Absalom, God save the king, God save the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 17, E'And Absalom said to Hushai, Is this thy kindness to thy friend? why wentest thou not with thy friend?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 18, E'And Hushai said unto Absalom, Nay; but whom the LORD, and this people, and all the men of Israel, choose, his will I be, and with him will I abide.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 19, E'And again, whom should I serve? should I not serve in the presence of his son? as I have served in thy fatherâ€™s presence, so will I be in thy presence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 20, E'Then said Absalom to Ahithophel, Give counsel among you what we shall do.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 21, E'And Ahithophel said unto Absalom, Go in unto thy fatherâ€™s concubines, which he hath left to keep the house; and all Israel shall hear that thou art abhorred of thy father: then shall the hands of all that are with thee be strong.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 22, E'So they spread Absalom a tent upon the top of the house; and Absalom went in unto his fatherâ€™s concubines in the sight of all Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 16, 23, E'And the counsel of Ahithophel, which he counselled in those days, was as if a man had enquired at the oracle of God: so was all the counsel of Ahithophel both with David and with Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 1, E'Moreover Ahithophel said unto Absalom, Let me now choose out twelve thousand men, and I will arise and pursue after David this night:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 2, E'And I will come upon him while he is weary and weak handed, and will make him afraid: and all the people that are with him shall flee; and I will smite the king only:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 3, E'And I will bring back all the people unto thee: the man whom thou seekest is as if all returned: so all the people shall be in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 4, E'And the saying pleased Absalom well, and all the elders of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 5, E'Then said Absalom, Call now Hushai the Archite also, and let us hear likewise what he saith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 6, E'And when Hushai was come to Absalom, Absalom spake unto him, saying, Ahithophel hath spoken after this manner: shall we do after his saying? if not; speak thou.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 7, E'And Hushai said unto Absalom, The counsel that Ahithophel hath given is not good at this time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 8, E'For, said Hushai, thou knowest thy father and his men, that they be mighty men, and they be chafed in their minds, as a bear robbed of her whelps in the field: and thy father is a man of war, and will not lodge with the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 9, E'Behold, he is hid now in some pit, or in some other place: and it will come to pass, when some of them be overthrown at the first, that whosoever heareth it will say, There is a slaughter among the people that follow Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 10, E'And he also that is valiant, whose heart is as the heart of a lion, shall utterly melt: for all Israel knoweth that thy father is a mighty man, and they which be with him are valiant men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 11, E'Therefore I counsel that all Israel be generally gathered unto thee, from Dan even to Beersheba, as the sand that is by the sea for multitude; and that thou go to battle in thine own person.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 12, E'So shall we come upon him in some place where he shall be found, and we will light upon him as the dew falleth on the ground: and of him and of all the men that are with him there shall not be left so much as one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 13, E'Moreover, if he be gotten into a city, then shall all Israel bring ropes to that city, and we will draw it into the river, until there be not one small stone found there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 14, E'And Absalom and all the men of Israel said, The counsel of Hushai the Archite is better than the counsel of Ahithophel. For the LORD had appointed to defeat the good counsel of Ahithophel, to the intent that the LORD might bring evil upon Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 15, E'Then said Hushai unto Zadok and to Abiathar the priests, Thus and thus did Ahithophel counsel Absalom and the elders of Israel; and thus and thus have I counselled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 16, E'Now therefore send quickly, and tell David, saying, Lodge not this night in the plains of the wilderness, but speedily pass over; lest the king be swallowed up, and all the people that are with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 17, E'Now Jonathan and Ahimaaz stayed by Enrogel; for they might not be seen to come into the city: and a wench went and told them; and they went and told king David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 18, E'Nevertheless a lad saw them, and told Absalom: but they went both of them away quickly, and came to a manâ€™s house in Bahurim, which had a well in his court; whither they went down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 19, E'And the woman took and spread a covering over the wellâ€™s mouth, and spread ground corn thereon; and the thing was not known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 20, E'And when Absalomâ€™s servants came to the woman to the house, they said, Where is Ahimaaz and Jonathan? And the woman said unto them, They be gone over the brook of water. And when they had sought and could not find them, they returned to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 21, E'And it came to pass, after they were departed, that they came up out of the well, and went and told king David, and said unto David, Arise, and pass quickly over the water: for thus hath Ahithophel counselled against you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 22, E'Then David arose, and all the people that were with him, and they passed over Jordan: by the morning light there lacked not one of them that was not gone over Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 23, E'And when Ahithophel saw that his counsel was not followed, he saddled his ass, and arose, and gat him home to his house, to his city, and put his household in order, and hanged himself, and died, and was buried in the sepulchre of his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 24, E'Then David came to Mahanaim. And Absalom passed over Jordan, he and all the men of Israel with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 25, E'And Absalom made Amasa captain of the host instead of Joab: which Amasa was a manâ€™s son, whose name was Ithra an Israelite, that went in to Abigail the daughter of Nahash, sister to Zeruiah Joabâ€™s mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 26, E'So Israel and Absalom pitched in the land of Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 27, E'And it came to pass, when David was come to Mahanaim, that Shobi the son of Nahash of Rabbah of the children of Ammon, and Machir the son of Ammiel of Lodebar, and Barzillai the Gileadite of Rogelim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 28, E'Brought beds, and basons, and earthen vessels, and wheat, and barley, and flour, and parched corn, and beans, and lentiles, and parched pulse,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 17, 29, E'And honey, and butter, and sheep, and cheese of kine, for David, and for the people that were with him, to eat: for they said, The people is hungry, and weary, and thirsty, in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 1, E'And David numbered the people that were with him, and set captains of thousands and captains of hundreds over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 2, E'And David sent forth a third part of the people under the hand of Joab, and a third part under the hand of Abishai the son of Zeruiah, Joabâ€™s brother, and a third part under the hand of Ittai the Gittite. And the king said unto the people, I will surely go forth with you myself also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 3, E'But the people answered, Thou shalt not go forth: for if we flee away, they will not care for us; neither if half of us die, will they care for us: but now thou art worth ten thousand of us: therefore now it is better that thou succour us out of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 4, E'And the king said unto them, What seemeth you best I will do. And the king stood by the gate side, and all the people came out by hundreds and by thousands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 5, E'And the king commanded Joab and Abishai and Ittai, saying, Deal gently for my sake with the young man, even with Absalom. And all the people heard when the king gave all the captains charge concerning Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 6, E'So the people went out into the field against Israel: and the battle was in the wood of Ephraim;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 7, E'Where the people of Israel were slain before the servants of David, and there was there a great slaughter that day of twenty thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 8, E'For the battle was there scattered over the face of all the country: and the wood devoured more people that day than the sword devoured.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 9, E'And Absalom met the servants of David. And Absalom rode upon a mule, and the mule went under the thick boughs of a great oak, and his head caught hold of the oak, and he was taken up between the heaven and the earth; and the mule that was under him went away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 10, E'And a certain man saw it, and told Joab, and said, Behold, I saw Absalom hanged in an oak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 11, E'And Joab said unto the man that told him, And, behold, thou sawest him, and why didst thou not smite him there to the ground? and I would have given thee ten shekels of silver, and a girdle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 12, E'And the man said unto Joab, Though I should receive a thousand shekels of silver in mine hand, yet would I not put forth mine hand against the kingâ€™s son: for in our hearing the king charged thee and Abishai and Ittai, saying, Beware that none touch the young man Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 13, E'Otherwise I should have wrought falsehood against mine own life: for there is no matter hid from the king, and thou thyself wouldest have set thyself against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 14, E'Then said Joab, I may not tarry thus with thee. And he took three darts in his hand, and thrust them through the heart of Absalom, while he was yet alive in the midst of the oak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 15, E'And ten young men that bare Joabâ€™s armour compassed about and smote Absalom, and slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 16, E'And Joab blew the trumpet, and the people returned from pursuing after Israel: for Joab held back the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 17, E'And they took Absalom, and cast him into a great pit in the wood, and laid a very great heap of stones upon him: and all Israel fled every one to his tent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 18, E'Now Absalom in his lifetime had taken and reared up for himself a pillar, which is in the kingâ€™s dale: for he said, I have no son to keep my name in remembrance: and he called the pillar after his own name: and it is called unto this day, Absalomâ€™s place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 19, E'Then said Ahimaaz the son of Zadok, Let me now run, and bear the king tidings, how that the LORD hath avenged him of his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 20, E'And Joab said unto him, Thou shalt not bear tidings this day, but thou shalt bear tidings another day: but this day thou shalt bear no tidings, because the kingâ€™s son is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 21, E'Then said Joab to Cushi, Go tell the king what thou hast seen. And Cushi bowed himself unto Joab, and ran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 22, E'Then said Ahimaaz the son of Zadok yet again to Joab, But howsoever, let me, I pray thee, also run after Cushi. And Joab said, Wherefore wilt thou run, my son, seeing that thou hast no tidings ready?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 23, E'But howsoever, said he, let me run. And he said unto him, Run. Then Ahimaaz ran by the way of the plain, and overran Cushi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 24, E'And David sat between the two gates: and the watchman went up to the roof over the gate unto the wall, and lifted up his eyes, and looked, and behold a man running alone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 25, E'And the watchman cried, and told the king. And the king said, If he be alone, there is tidings in his mouth. And he came apace, and drew near.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 26, E'And the watchman saw another man running: and the watchman called unto the porter, and said, Behold another man running alone. And the king said, He also bringeth tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 27, E'And the watchman said, Me thinketh the running of the foremost is like the running of Ahimaaz the son of Zadok. And the king said, He is a good man, and cometh with good tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 28, E'And Ahimaaz called, and said unto the king, All is well. And he fell down to the earth upon his face before the king, and said, Blessed be the LORD thy God, which hath delivered up the men that lifted up their hand against my lord the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 29, E'And the king said, Is the young man Absalom safe? And Ahimaaz answered, When Joab sent the kingâ€™s servant, and me thy servant, I saw a great tumult, but I knew not what it was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 30, E'And the king said unto him, Turn aside, and stand here. And he turned aside, and stood still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 31, E'And, behold, Cushi came; and Cushi said, Tidings, my lord the king: for the LORD hath avenged thee this day of all them that rose up against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 32, E'And the king said unto Cushi, Is the young man Absalom safe? And Cushi answered, The enemies of my lord the king, and all that rise against thee to do thee hurt, be as that young man is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 18, 33, E'And the king was much moved, and went up to the chamber over the gate, and wept: and as he went, thus he said, O my son Absalom, my son, my son Absalom! would God I had died for thee, O Absalom, my son, my son!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 1, E'And it was told Joab, Behold, the king weepeth and mourneth for Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 2, E'And the victory that day was turned into mourning unto all the people: for the people heard say that day how the king was grieved for his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 3, E'And the people gat them by stealth that day into the city, as people being ashamed steal away when they flee in battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 4, E'But the king covered his face, and the king cried with a loud voice, O my son Absalom, O Absalom, my son, my son!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 5, E'And Joab came into the house to the king, and said, Thou hast shamed this day the faces of all thy servants, which this day have saved thy life, and the lives of thy sons and of thy daughters, and the lives of thy wives, and the lives of thy concubines;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 6, E'In that thou lovest thine enemies, and hatest thy friends. For thou hast declared this day, that thou regardest neither princes nor servants: for this day I perceive, that if Absalom had lived, and all we had died this day, then it had pleased thee well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 7, E'Now therefore arise, go forth, and speak comfortably unto thy servants: for I swear by the LORD, if thou go not forth, there will not tarry one with thee this night: and that will be worse unto thee than all the evil that befell thee from thy youth until now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 8, E'Then the king arose, and sat in the gate. And they told unto all the people, saying, Behold, the king doth sit in the gate. And all the people came before the king: for Israel had fled every man to his tent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 9, E'And all the people were at strife throughout all the tribes of Israel, saying, The king saved us out of the hand of our enemies, and he delivered us out of the hand of the Philistines; and now he is fled out of the land for Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 10, E'And Absalom, whom we anointed over us, is dead in battle. Now therefore why speak ye not a word of bringing the king back?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 11, E'And king David sent to Zadok and to Abiathar the priests, saying, Speak unto the elders of Judah, saying, Why are ye the last to bring the king back to his house? seeing the speech of all Israel is come to the king, even to his house.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Samuel') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 12, E'Ye are my brethren, ye are my bones and my flesh: wherefore then are ye the last to bring back the king?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 13, E'And say ye to Amasa, Art thou not of my bone, and of my flesh? God do so to me, and more also, if thou be not captain of the host before me continually in the room of Joab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 14, E'And he bowed the heart of all the men of Judah, even as the heart of one man; so that they sent this word unto the king, Return thou, and all thy servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 15, E'So the king returned, and came to Jordan. And Judah came to Gilgal, to go to meet the king, to conduct the king over Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 16, E'And Shimei the son of Gera, a Benjamite, which was of Bahurim, hasted and came down with the men of Judah to meet king David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 17, E'And there were a thousand men of Benjamin with him, and Ziba the servant of the house of Saul, and his fifteen sons and his twenty servants with him; and they went over Jordan before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 18, E'And there went over a ferry boat to carry over the kingâ€™s household, and to do what he thought good. And Shimei the son of Gera fell down before the king, as he was come over Jordan;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 19, E'And said unto the king, Let not my lord impute iniquity unto me, neither do thou remember that which thy servant did perversely the day that my lord the king went out of Jerusalem, that the king should take it to his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 20, E'For thy servant doth know that I have sinned: therefore, behold, I am come the first this day of all the house of Joseph to go down to meet my lord the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 21, E'But Abishai the son of Zeruiah answered and said, Shall not Shimei be put to death for this, because he cursed the LORDâ€™s anointed?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 22, E'And David said, What have I to do with you, ye sons of Zeruiah, that ye should this day be adversaries unto me? shall there any man be put to death this day in Israel? for do not I know that I am this day king over Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 23, E'Therefore the king said unto Shimei, Thou shalt not die. And the king sware unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 24, E'And Mephibosheth the son of Saul came down to meet the king, and had neither dressed his feet, nor trimmed his beard, nor washed his clothes, from the day the king departed until the day he came again in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 25, E'And it came to pass, when he was come to Jerusalem to meet the king, that the king said unto him, Wherefore wentest not thou with me, Mephibosheth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 26, E'And he answered, My lord, O king, my servant deceived me: for thy servant said, I will saddle me an ass, that I may ride thereon, and go to the king; because thy servant is lame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 27, E'And he hath slandered thy servant unto my lord the king; but my lord the king is as an angel of God: do therefore what is good in thine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 28, E'For all of my fatherâ€™s house were but dead men before my lord the king: yet didst thou set thy servant among them that did eat at thine own table. What right therefore have I yet to cry any more unto the king?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 29, E'And the king said unto him, Why speakest thou any more of thy matters? I have said, Thou and Ziba divide the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 30, E'And Mephibosheth said unto the king, Yea, let him take all, forasmuch as my lord the king is come again in peace unto his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 31, E'And Barzillai the Gileadite came down from Rogelim, and went over Jordan with the king, to conduct him over Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 32, E'Now Barzillai was a very aged man, even fourscore years old: and he had provided the king of sustenance while he lay at Mahanaim; for he was a very great man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 33, E'And the king said unto Barzillai, Come thou over with me, and I will feed thee with me in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 34, E'And Barzillai said unto the king, How long have I to live, that I should go up with the king unto Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 35, E'I am this day fourscore years old: and can I discern between good and evil? can thy servant taste what I eat or what I drink? can I hear any more the voice of singing men and singing women? wherefore then should thy servant be yet a burden unto my lord the king?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 36, E'Thy servant will go a little way over Jordan with the king: and why should the king recompense it me with such a reward?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 37, E'Let thy servant, I pray thee, turn back again, that I may die in mine own city, and be buried by the grave of my father and of my mother. But behold thy servant Chimham; let him go over with my lord the king; and do to him what shall seem good unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 38, E'And the king answered, Chimham shall go over with me, and I will do to him that which shall seem good unto thee: and whatsoever thou shalt require of me, that will I do for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 39, E'And all the people went over Jordan. And when the king was come over, the king kissed Barzillai, and blessed him; and he returned unto his own place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 40, E'Then the king went on to Gilgal, and Chimham went on with him: and all the people of Judah conducted the king, and also half the people of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 41, E'And, behold, all the men of Israel came to the king, and said unto the king, Why have our brethren the men of Judah stolen thee away, and have brought the king, and his household, and all Davidâ€™s men with him, over Jordan?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 42, E'And all the men of Judah answered the men of Israel, Because the king is near of kin to us: wherefore then be ye angry for this matter? have we eaten at all of the kingâ€™s cost? or hath he given us any gift?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 19, 43, E'And the men of Israel answered the men of Judah, and said, We have ten parts in the king, and we have also more right in David than ye: why then did ye despise us, that our advice should not be first had in bringing back our king? And the words of the men of Judah were fiercer than the words of the men of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 1, E'And there happened to be there a man of Belial, whose name was Sheba, the son of Bichri, a Benjamite: and he blew a trumpet, and said, We have no part in David, neither have we inheritance in the son of Jesse: every man to his tents, O Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 2, E'So every man of Israel went up from after David, and followed Sheba the son of Bichri: but the men of Judah clave unto their king, from Jordan even to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 3, E'And David came to his house at Jerusalem; and the king took the ten women his concubines, whom he had left to keep the house, and put them in ward, and fed them, but went not in unto them. So they were shut up unto the day of their death, living in widowhood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 4, E'Then said the king to Amasa, Assemble me the men of Judah within three days, and be thou here present.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 5, E'So Amasa went to assemble the men of Judah: but he tarried longer than the set time which he had appointed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 6, E'And David said to Abishai, Now shall Sheba the son of Bichri do us more harm than did Absalom: take thou thy lordâ€™s servants, and pursue after him, lest he get him fenced cities, and escape us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 7, E'And there went out after him Joabâ€™s men, and the Cherethites, and the Pelethites, and all the mighty men: and they went out of Jerusalem, to pursue after Sheba the son of Bichri.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 8, E'When they were at the great stone which is in Gibeon, Amasa went before them. And Joabâ€™s garment that he had put on was girded unto him, and upon it a girdle with a sword fastened upon his loins in the sheath thereof; and as he went forth it fell out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 9, E'And Joab said to Amasa, Art thou in health, my brother? And Joab took Amasa by the beard with the right hand to kiss him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 10, E'But Amasa took no heed to the sword that was in Joabâ€™s hand: so he smote him therewith in the fifth rib, and shed out his bowels to the ground, and struck him not again; and he died. So Joab and Abishai his brother pursued after Sheba the son of Bichri.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 11, E'And one of Joabâ€™s men stood by him, and said, He that favoureth Joab, and he that is for David, let him go after Joab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 12, E'And Amasa wallowed in blood in the midst of the highway. And when the man saw that all the people stood still, he removed Amasa out of the highway into the field, and cast a cloth upon him, when he saw that every one that came by him stood still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 13, E'When he was removed out of the highway, all the people went on after Joab, to pursue after Sheba the son of Bichri.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 14, E'And he went through all the tribes of Israel unto Abel, and to Bethmaachah, and all the Berites: and they were gathered together, and went also after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 15, E'And they came and besieged him in Abel of Bethmaachah, and they cast up a bank against the city, and it stood in the trench: and all the people that were with Joab battered the wall, to throw it down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 16, E'Then cried a wise woman out of the city, Hear, hear; say, I pray you, unto Joab, Come near hither, that I may speak with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 17, E'And when he was come near unto her, the woman said, Art thou Joab? And he answered, I am he. Then she said unto him, Hear the words of thine handmaid. And he answered, I do hear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 18, E'Then she spake, saying, They were wont to speak in old time, saying, They shall surely ask counsel at Abel: and so they ended the matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 19, E'I am one of them that are peaceable and faithful in Israel: thou seekest to destroy a city and a mother in Israel: why wilt thou swallow up the inheritance of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 20, E'And Joab answered and said, Far be it, far be it from me, that I should swallow up or destroy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 21, E'The matter is not so: but a man of mount Ephraim, Sheba the son of Bichri by name, hath lifted up his hand against the king, even against David: deliver him only, and I will depart from the city. And the woman said unto Joab, Behold, his head shall be thrown to thee over the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 22, E'Then the woman went unto all the people in her wisdom. And they cut off the head of Sheba the son of Bichri, and cast it out to Joab. And he blew a trumpet, and they retired from the city, every man to his tent. And Joab returned to Jerusalem unto the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 23, E'Now Joab was over all the host of Israel: and Benaiah the son of Jehoiada was over the Cherethites and over the Pelethites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 24, E'And Adoram was over the tribute: and Jehoshaphat the son of Ahilud was recorder:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 25, E'And Sheva was scribe: and Zadok and Abiathar were the priests:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 20, 26, E'And Ira also the Jairite was a chief ruler about David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 1, E'Then there was a famine in the days of David three years, year after year; and David enquired of the LORD. And the LORD answered, It is for Saul, and for his bloody house, because he slew the Gibeonites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 2, E'And the king called the Gibeonites, and said unto them; (now the Gibeonites were not of the children of Israel, but of the remnant of the Amorites; and the children of Israel had sworn unto them: and Saul sought to slay them in his zeal to the children of Israel and Judah.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 3, E'Wherefore David said unto the Gibeonites, What shall I do for you? and wherewith shall I make the atonement, that ye may bless the inheritance of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 4, E'And the Gibeonites said unto him, We will have no silver nor gold of Saul, nor of his house; neither for us shalt thou kill any man in Israel. And he said, What ye shall say, that will I do for you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 5, E'And they answered the king, The man that consumed us, and that devised against us that we should be destroyed from remaining in any of the coasts of Israel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 6, E'Let seven men of his sons be delivered unto us, and we will hang them up unto the LORD in Gibeah of Saul, whom the LORD did choose. And the king said, I will give them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 7, E'But the king spared Mephibosheth, the son of Jonathan the son of Saul, because of the LORDâ€™s oath that was between them, between David and Jonathan the son of Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 8, E'But the king took the two sons of Rizpah the daughter of Aiah, whom she bare unto Saul, Armoni and Mephibosheth; and the five sons of Michal the daughter of Saul, whom she brought up for Adriel the son of Barzillai the Meholathite:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 9, E'And he delivered them into the hands of the Gibeonites, and they hanged them in the hill before the LORD: and they fell all seven together, and were put to death in the days of harvest, in the first days, in the beginning of barley harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 10, E'And Rizpah the daughter of Aiah took sackcloth, and spread it for her upon the rock, from the beginning of harvest until water dropped upon them out of heaven, and suffered neither the birds of the air to rest on them by day, nor the beasts of the field by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 11, E'And it was told David what Rizpah the daughter of Aiah, the concubine of Saul, had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 12, E'And David went and took the bones of Saul and the bones of Jonathan his son from the men of Jabeshgilead, which had stolen them from the street of Bethshan, where the Philistines had hanged them, when the Philistines had slain Saul in Gilboa:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 13, E'And he brought up from thence the bones of Saul and the bones of Jonathan his son; and they gathered the bones of them that were hanged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 14, E'And the bones of Saul and Jonathan his son buried they in the country of Benjamin in Zelah, in the sepulchre of Kish his father: and they performed all that the king commanded. And after that God was intreated for the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 15, E'Moreover the Philistines had yet war again with Israel; and David went down, and his servants with him, and fought against the Philistines: and David waxed faint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 16, E'And Ishbibenob, which was of the sons of the giant, the weight of whose spear weighed three hundred shekels of brass in weight, he being girded with a new sword, thought to have slain David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 17, E'But Abishai the son of Zeruiah succoured him, and smote the Philistine, and killed him. Then the men of David sware unto him, saying, Thou shalt go no more out with us to battle, that thou quench not the light of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 18, E'And it came to pass after this, that there was again a battle with the Philistines at Gob: then Sibbechai the Hushathite slew Saph, which was of the sons of the giant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 19, E'And there was again a battle in Gob with the Philistines, where Elhanan the son of Jaareoregim, a Bethlehemite, slew the brother of Goliath the Gittite, the staff of whose spear was like a weaverâ€™s beam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 20, E'And there was yet a battle in Gath, where was a man of great stature, that had on every hand six fingers, and on every foot six toes, four and twenty in number; and he also was born to the giant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 21, E'And when he defied Israel, Jonathan the son of Shimeah the brother of David slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 21, 22, E'These four were born to the giant in Gath, and fell by the hand of David, and by the hand of his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 1, E'And David spake unto the LORD the words of this song in the day that the LORD had delivered him out of the hand of all his enemies, and out of the hand of Saul:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 2, E'And he said, The LORD is my rock, and my fortress, and my deliverer;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 3, E'The God of my rock; in him will I trust: he is my shield, and the horn of my salvation, my high tower, and my refuge, my saviour; thou savest me from violence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 4, E'I will call on the LORD, who is worthy to be praised: so shall I be saved from mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 5, E'When the waves of death compassed me, the floods of ungodly men made me afraid;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 6, E'The sorrows of hell compassed me about; the snares of death prevented me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 7, E'In my distress I called upon the LORD, and cried to my God: and he did hear my voice out of his temple, and my cry did enter into his ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 8, E'Then the earth shook and trembled; the foundations of heaven moved and shook, because he was wroth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 9, E'There went up a smoke out of his nostrils, and fire out of his mouth devoured: coals were kindled by it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 10, E'He bowed the heavens also, and came down; and darkness was under his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 11, E'And he rode upon a cherub, and did fly: and he was seen upon the wings of the wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 12, E'And he made darkness pavilions round about him, dark waters, and thick clouds of the skies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 13, E'Through the brightness before him were coals of fire kindled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 14, E'The LORD thundered from heaven, and the most High uttered his voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 15, E'And he sent out arrows, and scattered them; lightning, and discomfited them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 16, E'And the channels of the sea appeared, the foundations of the world were discovered, at the rebuking of the LORD, at the blast of the breath of his nostrils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 17, E'He sent from above, he took me; he drew me out of many waters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 18, E'He delivered me from my strong enemy, and from them that hated me: for they were too strong for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 19, E'They prevented me in the day of my calamity: but the LORD was my stay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 20, E'He brought me forth also into a large place: he delivered me, because he delighted in me.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Samuel') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 21, E'The LORD rewarded me according to my righteousness: according to the cleanness of my hands hath he recompensed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 22, E'For I have kept the ways of the LORD, and have not wickedly departed from my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 23, E'For all his judgments were before me: and as for his statutes, I did not depart from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 24, E'I was also upright before him, and have kept myself from mine iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 25, E'Therefore the LORD hath recompensed me according to my righteousness; according to my cleanness in his eye sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 26, E'With the merciful thou wilt shew thyself merciful, and with the upright man thou wilt shew thyself upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 27, E'With the pure thou wilt shew thyself pure; and with the froward thou wilt shew thyself unsavoury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 28, E'And the afflicted people thou wilt save: but thine eyes are upon the haughty, that thou mayest bring them down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 29, E'For thou art my lamp, O LORD: and the LORD will lighten my darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 30, E'For by thee I have run through a troop: by my God have I leaped over a wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 31, E'As for God, his way is perfect; the word of the LORD is tried: he is a buckler to all them that trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 32, E'For who is God, save the LORD? and who is a rock, save our God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 33, E'God is my strength and power: and he maketh my way perfect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 34, E'He maketh my feet like hindsâ€™ feet: and setteth me upon my high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 35, E'He teacheth my hands to war; so that a bow of steel is broken by mine arms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 36, E'Thou hast also given me the shield of thy salvation: and thy gentleness hath made me great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 37, E'Thou hast enlarged my steps under me; so that my feet did not slip.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 38, E'I have pursued mine enemies, and destroyed them; and turned not again until I had consumed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 39, E'And I have consumed them, and wounded them, that they could not arise: yea, they are fallen under my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 40, E'For thou hast girded me with strength to battle: them that rose up against me hast thou subdued under me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 41, E'Thou hast also given me the necks of mine enemies, that I might destroy them that hate me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 42, E'They looked, but there was none to save; even unto the LORD, but he answered them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 43, E'Then did I beat them as small as the dust of the earth, I did stamp them as the mire of the street, and did spread them abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 44, E'Thou also hast delivered me from the strivings of my people, thou hast kept me to be head of the heathen: a people which I knew not shall serve me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 45, E'Strangers shall submit themselves unto me: as soon as they hear, they shall be obedient unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 46, E'Strangers shall fade away, and they shall be afraid out of their close places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 47, E'The LORD liveth; and blessed be my rock; and exalted be the God of the rock of my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 48, E'It is God that avengeth me, and that bringeth down the people under me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 49, E'And that bringeth me forth from mine enemies: thou also hast lifted me up on high above them that rose up against me: thou hast delivered me from the violent man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 50, E'Therefore I will give thanks unto thee, O LORD, among the heathen, and I will sing praises unto thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 22, 51, E'He is the tower of salvation for his king: and sheweth mercy to his anointed, unto David, and to his seed for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 1, E'Now these be the last words of David. David the son of Jesse said, and the man who was raised up on high, the anointed of the God of Jacob, and the sweet psalmist of Israel, said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 2, E'The Spirit of the LORD spake by me, and his word was in my tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 3, E'The God of Israel said, the Rock of Israel spake to me, He that ruleth over men must be just, ruling in the fear of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 4, E'And he shall be as the light of the morning, when the sun riseth, even a morning without clouds; as the tender grass springing out of the earth by clear shining after rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 5, E'Although my house be not so with God; yet he hath made with me an everlasting covenant, ordered in all things, and sure: for this is all my salvation, and all my desire, although he make it not to grow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 6, E'But the sons of Belial shall be all of them as thorns thrust away, because they cannot be taken with hands:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 7, E'But the man that shall touch them must be fenced with iron and the staff of a spear; and they shall be utterly burned with fire in the same place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 8, E'These be the names of the mighty men whom David had: The Tachmonite that sat in the seat, chief among the captains; the same was Adino the Eznite: he lift up his spear against eight hundred, whom he slew at one time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 9, E'And after him was Eleazar the son of Dodo the Ahohite, one of the three mighty men with David, when they defied the Philistines that were there gathered together to battle, and the men of Israel were gone away:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 10, E'He arose, and smote the Philistines until his hand was weary, and his hand clave unto the sword: and the LORD wrought a great victory that day; and the people returned after him only to spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 11, E'And after him was Shammah the son of Agee the Hararite. And the Philistines were gathered together into a troop, where was a piece of ground full of lentiles: and the people fled from the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 12, E'But he stood in the midst of the ground, and defended it, and slew the Philistines: and the LORD wrought a great victory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 13, E'And three of the thirty chief went down, and came to David in the harvest time unto the cave of Adullam: and the troop of the Philistines pitched in the valley of Rephaim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 14, E'And David was then in an hold, and the garrison of the Philistines was then in Bethlehem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 15, E'And David longed, and said, Oh that one would give me drink of the water of the well of Bethlehem, which is by the gate!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 16, E'And the three mighty men brake through the host of the Philistines, and drew water out of the well of Bethlehem, that was by the gate, and took it, and brought it to David: nevertheless he would not drink thereof, but poured it out unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 17, E'And he said, Be it far from me, O LORD, that I should do this: is not this the blood of the men that went in jeopardy of their lives? therefore he would not drink it. These things did these three mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 18, E'And Abishai, the brother of Joab, the son of Zeruiah, was chief among three. And he lifted up his spear against three hundred, and slew them, and had the name among three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 19, E'Was he not most honourable of three? therefore he was their captain: howbeit he attained not unto the first three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 20, E'And Benaiah the son of Jehoiada, the son of a valiant man, of Kabzeel, who had done many acts, he slew two lionlike men of Moab: he went down also and slew a lion in the midst of a pit in time of snow:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 21, E'And he slew an Egyptian, a goodly man: and the Egyptian had a spear in his hand; but he went down to him with a staff, and plucked the spear out of the Egyptianâ€™s hand, and slew him with his own spear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 22, E'These things did Benaiah the son of Jehoiada, and had the name among three mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 23, E'He was more honourable than the thirty, but he attained not to the first three. And David set him over his guard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 24, E'Asahel the brother of Joab was one of the thirty; Elhanan the son of Dodo of Bethlehem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 25, E'Shammah the Harodite, Elika the Harodite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 26, E'Helez the Paltite, Ira the son of Ikkesh the Tekoite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 27, E'Abiezer the Anethothite, Mebunnai the Hushathite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 28, E'Zalmon the Ahohite, Maharai the Netophathite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 29, E'Heleb the son of Baanah, a Netophathite, Ittai the son of Ribai out of Gibeah of the children of Benjamin,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 30, E'Benaiah the Pirathonite, Hiddai of the brooks of Gaash,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 31, E'Abialbon the Arbathite, Azmaveth the Barhumite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 32, E'Eliahba the Shaalbonite, of the sons of Jashen, Jonathan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 33, E'Shammah the Hararite, Ahiam the son of Sharar the Hararite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 34, E'Eliphelet the son of Ahasbai, the son of the Maachathite, Eliam the son of Ahithophel the Gilonite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 35, E'Hezrai the Carmelite, Paarai the Arbite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 36, E'Igal the son of Nathan of Zobah, Bani the Gadite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 37, E'Zelek the Ammonite, Nahari the Beerothite, armourbearer to Joab the son of Zeruiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 38, E'Ira an Ithrite, Gareb an Ithrite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 23, 39, E'Uriah the Hittite: thirty and seven in all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 1, E'And again the anger of the LORD was kindled against Israel, and he moved David against them to say, Go, number Israel and Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 2, E'For the king said to Joab the captain of the host, which was with him, Go now through all the tribes of Israel, from Dan even to Beersheba, and number ye the people, that I may know the number of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 3, E'And Joab said unto the king, Now the LORD thy God add unto the people, how many soever they be, an hundredfold, and that the eyes of my lord the king may see it: but why doth my lord the king delight in this thing?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 4, E'Notwithstanding the kingâ€™s word prevailed against Joab, and against the captains of the host. And Joab and the captains of the host went out from the presence of the king, to number the people of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 5, E'And they passed over Jordan, and pitched in Aroer, on the right side of the city that lieth in the midst of the river of Gad, and toward Jazer:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 6, E'Then they came to Gilead, and to the land of Tahtimhodshi; and they came to Danjaan, and about to Zidon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 7, E'And came to the strong hold of Tyre, and to all the cities of the Hivites, and of the Canaanites: and they went out to the south of Judah, even to Beersheba.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 8, E'So when they had gone through all the land, they came to Jerusalem at the end of nine months and twenty days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 9, E'And Joab gave up the sum of the number of the people unto the king: and there were in Israel eight hundred thousand valiant men that drew the sword; and the men of Judah were five hundred thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 10, E'And Davidâ€™s heart smote him after that he had numbered the people. And David said unto the LORD, I have sinned greatly in that I have done: and now, I beseech thee, O LORD, take away the iniquity of thy servant; for I have done very foolishly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 11, E'For when David was up in the morning, the word of the LORD came unto the prophet Gad, Davidâ€™s seer, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 12, E'Go and say unto David, Thus saith the LORD, I offer thee three things; choose thee one of them, that I may do it unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 13, E'So Gad came to David, and told him, and said unto him, Shall seven years of famine come unto thee in thy land? or wilt thou flee three months before thine enemies, while they pursue thee? or that there be three daysâ€™ pestilence in thy land? now advise, and see what answer I shall return to him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 14, E'And David said unto Gad, I am in a great strait: let us fall now into the hand of the LORD; for his mercies are great: and let me not fall into the hand of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 15, E'So the LORD sent a pestilence upon Israel from the morning even to the time appointed: and there died of the people from Dan even to Beersheba seventy thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 16, E'And when the angel stretched out his hand upon Jerusalem to destroy it, the LORD repented him of the evil, and said to the angel that destroyed the people, It is enough: stay now thine hand. And the angel of the LORD was by the threshingplace of Araunah the Jebusite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 17, E'And David spake unto the LORD when he saw the angel that smote the people, and said, Lo, I have sinned, and I have done wickedly: but these sheep, what have they done? let thine hand, I pray thee, be against me, and against my fatherâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 18, E'And Gad came that day to David, and said unto him, Go up, rear an altar unto the LORD in the threshingfloor of Araunah the Jebusite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 19, E'And David, according to the saying of Gad, went up as the LORD commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 20, E'And Araunah looked, and saw the king and his servants coming on toward him: and Araunah went out, and bowed himself before the king on his face upon the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 21, E'And Araunah said, Wherefore is my lord the king come to his servant? And David said, To buy the threshingfloor of thee, to build an altar unto the LORD, that the plague may be stayed from the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 22, E'And Araunah said unto David, Let my lord the king take and offer up what seemeth good unto him: behold, here be oxen for burnt sacrifice, and threshing instruments and other instruments of the oxen for wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 23, E'All these things did Araunah, as a king, give unto the king. And Araunah said unto the king, The LORD thy God accept thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 24, E'And the king said unto Araunah, Nay; but I will surely buy it of thee at a price: neither will I offer burnt offerings unto the LORD my God of that which doth cost me nothing. So David bought the threshingfloor and the oxen for fifty shekels of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '850e4fdf-fe01-40e8-84a5-c67cb905630c', 24, 25, E'And David built there an altar unto the LORD, and offered burnt offerings and peace offerings. So the LORD was intreated for the land, and the plague was stayed from Israel.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Samuel') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 1, E'Now king David was old and stricken in years; and they covered him with clothes, but he gat no heat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 2, E'Wherefore his servants said unto him, Let there be sought for my lord the king a young virgin: and let her stand before the king, and let her cherish him, and let her lie in thy bosom, that my lord the king may get heat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 3, E'So they sought for a fair damsel throughout all the coasts of Israel, and found Abishag a Shunammite, and brought her to the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 4, E'And the damsel was very fair, and cherished the king, and ministered to him: but the king knew her not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 5, E'Then Adonijah the son of Haggith exalted himself, saying, I will be king: and he prepared him chariots and horsemen, and fifty men to run before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 6, E'And his father had not displeased him at any time in saying, Why hast thou done so? and he also was a very goodly man; and his mother bare him after Absalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 7, E'And he conferred with Joab the son of Zeruiah, and with Abiathar the priest: and they following Adonijah helped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 8, E'But Zadok the priest, and Benaiah the son of Jehoiada, and Nathan the prophet, and Shimei, and Rei, and the mighty men which belonged to David, were not with Adonijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 9, E'And Adonijah slew sheep and oxen and fat cattle by the stone of Zoheleth, which is by Enrogel, and called all his brethren the kingâ€™s sons, and all the men of Judah the kingâ€™s servants:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 10, E'But Nathan the prophet, and Benaiah, and the mighty men, and Solomon his brother, he called not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 11, E'Wherefore Nathan spake unto Bathsheba the mother of Solomon, saying, Hast thou not heard that Adonijah the son of Haggith doth reign, and David our lord knoweth it not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 12, E'Now therefore come, let me, I pray thee, give thee counsel, that thou mayest save thine own life, and the life of thy son Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 13, E'Go and get thee in unto king David, and say unto him, Didst not thou, my lord, O king, swear unto thine handmaid, saying, Assuredly Solomon thy son shall reign after me, and he shall sit upon my throne? why then doth Adonijah reign?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 14, E'Behold, while thou yet talkest there with the king, I also will come in after thee, and confirm thy words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 15, E'And Bathsheba went in unto the king into the chamber: and the king was very old; and Abishag the Shunammite ministered unto the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 16, E'And Bathsheba bowed, and did obeisance unto the king. And the king said, What wouldest thou?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 17, E'And she said unto him, My lord, thou swarest by the LORD thy God unto thine handmaid, saying, Assuredly Solomon thy son shall reign after me, and he shall sit upon my throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 18, E'And now, behold, Adonijah reigneth; and now, my lord the king, thou knowest it not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 19, E'And he hath slain oxen and fat cattle and sheep in abundance, and hath called all the sons of the king, and Abiathar the priest, and Joab the captain of the host: but Solomon thy servant hath he not called.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 20, E'And thou, my lord, O king, the eyes of all Israel are upon thee, that thou shouldest tell them who shall sit on the throne of my lord the king after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 21, E'Otherwise it shall come to pass, when my lord the king shall sleep with his fathers, that I and my son Solomon shall be counted offenders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 22, E'And, lo, while she yet talked with the king, Nathan the prophet also came in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 23, E'And they told the king, saying, Behold Nathan the prophet. And when he was come in before the king, he bowed himself before the king with his face to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 24, E'And Nathan said, My lord, O king, hast thou said, Adonijah shall reign after me, and he shall sit upon my throne?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 25, E'For he is gone down this day, and hath slain oxen and fat cattle and sheep in abundance, and hath called all the kingâ€™s sons, and the captains of the host, and Abiathar the priest; and, behold, they eat and drink before him, and say, God save king Adonijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 26, E'But me, even me thy servant, and Zadok the priest, and Benaiah the son of Jehoiada, and thy servant Solomon, hath he not called.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 27, E'Is this thing done by my lord the king, and thou hast not shewed it unto thy servant, who should sit on the throne of my lord the king after him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 28, E'Then king David answered and said, Call me Bathsheba. And she came into the kingâ€™s presence, and stood before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 29, E'And the king sware, and said, As the LORD liveth, that hath redeemed my soul out of all distress,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 30, E'Even as I sware unto thee by the LORD God of Israel, saying, Assuredly Solomon thy son shall reign after me, and he shall sit upon my throne in my stead; even so will I certainly do this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 31, E'Then Bathsheba bowed with her face to the earth, and did reverence to the king, and said, Let my lord king David live for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 32, E'And king David said, Call me Zadok the priest, and Nathan the prophet, and Benaiah the son of Jehoiada. And they came before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 33, E'The king also said unto them, Take with you the servants of your lord, and cause Solomon my son to ride upon mine own mule, and bring him down to Gihon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 34, E'And let Zadok the priest and Nathan the prophet anoint him there king over Israel: and blow ye with the trumpet, and say, God save king Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 35, E'Then ye shall come up after him, that he may come and sit upon my throne; for he shall be king in my stead: and I have appointed him to be ruler over Israel and over Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 36, E'And Benaiah the son of Jehoiada answered the king, and said, Amen: the LORD God of my lord the king say so too.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 37, E'As the LORD hath been with my lord the king, even so be he with Solomon, and make his throne greater than the throne of my lord king David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 38, E'So Zadok the priest, and Nathan the prophet, and Benaiah the son of Jehoiada, and the Cherethites, and the Pelethites, went down, and caused Solomon to ride upon king Davidâ€™s mule, and brought him to Gihon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 39, E'And Zadok the priest took an horn of oil out of the tabernacle, and anointed Solomon. And they blew the trumpet; and all the people said, God save king Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 40, E'And all the people came up after him, and the people piped with pipes, and rejoiced with great joy, so that the earth rent with the sound of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 41, E'And Adonijah and all the guests that were with him heard it as they had made an end of eating. And when Joab heard the sound of the trumpet, he said, Wherefore is this noise of the city being in an uproar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 42, E'And while he yet spake, behold, Jonathan the son of Abiathar the priest came; and Adonijah said unto him, Come in; for thou art a valiant man, and bringest good tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 43, E'And Jonathan answered and said to Adonijah, Verily our lord king David hath made Solomon king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 44, E'And the king hath sent with him Zadok the priest, and Nathan the prophet, and Benaiah the son of Jehoiada, and the Cherethites, and the Pelethites, and they have caused him to ride upon the kingâ€™s mule:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 45, E'And Zadok the priest and Nathan the prophet have anointed him king in Gihon: and they are come up from thence rejoicing, so that the city rang again. This is the noise that ye have heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 46, E'And also Solomon sitteth on the throne of the kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 47, E'And moreover the kingâ€™s servants came to bless our lord king David, saying, God make the name of Solomon better than thy name, and make his throne greater than thy throne. And the king bowed himself upon the bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 48, E'And also thus said the king, Blessed be the LORD God of Israel, which hath given one to sit on my throne this day, mine eyes even seeing it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 49, E'And all the guests that were with Adonijah were afraid, and rose up, and went every man his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 50, E'And Adonijah feared because of Solomon, and arose, and went, and caught hold on the horns of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 51, E'And it was told Solomon, saying, Behold, Adonijah feareth king Solomon: for, lo, he hath caught hold on the horns of the altar, saying, Let king Solomon swear unto me today that he will not slay his servant with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 52, E'And Solomon said, If he will shew himself a worthy man, there shall not an hair of him fall to the earth: but if wickedness shall be found in him, he shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 1, 53, E'So king Solomon sent, and they brought him down from the altar. And he came and bowed himself to king Solomon: and Solomon said unto him, Go to thine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 1, E'Now the days of David drew nigh that he should die; and he charged Solomon his son, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 2, E'I go the way of all the earth: be thou strong therefore, and shew thyself a man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 3, E'And keep the charge of the LORD thy God, to walk in his ways, to keep his statutes, and his commandments, and his judgments, and his testimonies, as it is written in the law of Moses, that thou mayest prosper in all that thou doest, and whithersoever thou turnest thyself:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 4, E'That the LORD may continue his word which he spake concerning me, saying, If thy children take heed to their way, to walk before me in truth with all their heart and with all their soul, there shall not fail thee (said he) a man on the throne of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 5, E'Moreover thou knowest also what Joab the son of Zeruiah did to me, and what he did to the two captains of the hosts of Israel, unto Abner the son of Ner, and unto Amasa the son of Jether, whom he slew, and shed the blood of war in peace, and put the blood of war upon his girdle that was about his loins, and in his shoes that were on his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 6, E'Do therefore according to thy wisdom, and let not his hoar head go down to the grave in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 7, E'But shew kindness unto the sons of Barzillai the Gileadite, and let them be of those that eat at thy table: for so they came to me when I fled because of Absalom thy brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 8, E'And, behold, thou hast with thee Shimei the son of Gera, a Benjamite of Bahurim, which cursed me with a grievous curse in the day when I went to Mahanaim: but he came down to meet me at Jordan, and I sware to him by the LORD, saying, I will not put thee to death with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 9, E'Now therefore hold him not guiltless: for thou art a wise man, and knowest what thou oughtest to do unto him; but his hoar head bring thou down to the grave with blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 10, E'So David slept with his fathers, and was buried in the city of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 11, E'And the days that David reigned over Israel were forty years: seven years reigned he in Hebron, and thirty and three years reigned he in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 12, E'Then sat Solomon upon the throne of David his father; and his kingdom was established greatly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 13, E'And Adonijah the son of Haggith came to Bathsheba the mother of Solomon. And she said, Comest thou peaceably? And he said, Peaceably.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 14, E'He said moreover, I have somewhat to say unto thee. And she said, Say on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 15, E'And he said, Thou knowest that the kingdom was mine, and that all Israel set their faces on me, that I should reign: howbeit the kingdom is turned about, and is become my brotherâ€™s: for it was his from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 16, E'And now I ask one petition of thee, deny me not. And she said unto him, Say on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 17, E'And he said, Speak, I pray thee, unto Solomon the king, (for he will not say thee nay,) that he give me Abishag the Shunammite to wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 18, E'And Bathsheba said, Well; I will speak for thee unto the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 19, E'Bathsheba therefore went unto king Solomon, to speak unto him for Adonijah. And the king rose up to meet her, and bowed himself unto her, and sat down on his throne, and caused a seat to be set for the kingâ€™s mother; and she sat on his right hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 20, E'Then she said, I desire one small petition of thee; I pray thee, say me not nay. And the king said unto her, Ask on, my mother: for I will not say thee nay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 21, E'And she said, Let Abishag the Shunammite be given to Adonijah thy brother to wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 22, E'And king Solomon answered and said unto his mother, And why dost thou ask Abishag the Shunammite for Adonijah? ask for him the kingdom also; for he is mine elder brother; even for him, and for Abiathar the priest, and for Joab the son of Zeruiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 23, E'Then king Solomon sware by the LORD, saying, God do so to me, and more also, if Adonijah have not spoken this word against his own life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 24, E'Now therefore, as the LORD liveth, which hath established me, and set me on the throne of David my father, and who hath made me an house, as he promised, Adonijah shall be put to death this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 25, E'And king Solomon sent by the hand of Benaiah the son of Jehoiada; and he fell upon him that he died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 26, E'And unto Abiathar the priest said the king, Get thee to Anathoth, unto thine own fields; for thou art worthy of death: but I will not at this time put thee to death, because thou barest the ark of the LORD God before David my father, and because thou hast been afflicted in all wherein my father was afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 27, E'So Solomon thrust out Abiathar from being priest unto the LORD; that he might fulfil the word of the LORD, which he spake concerning the house of Eli in Shiloh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 28, E'Then tidings came to Joab: for Joab had turned after Adonijah, though he turned not after Absalom. And Joab fled unto the tabernacle of the LORD, and caught hold on the horns of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 29, E'And it was told king Solomon that Joab was fled unto the tabernacle of the LORD; and, behold, he is by the altar. Then Solomon sent Benaiah the son of Jehoiada, saying, Go, fall upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 30, E'And Benaiah came to the tabernacle of the LORD, and said unto him, Thus saith the king, Come forth. And he said, Nay; but I will die here. And Benaiah brought the king word again, saying, Thus said Joab, and thus he answered me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 31, E'And the king said unto him, Do as he hath said, and fall upon him, and bury him; that thou mayest take away the innocent blood, which Joab shed, from me, and from the house of my father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 32, E'And the LORD shall return his blood upon his own head, who fell upon two men more righteous and better than he, and slew them with the sword, my father David not knowing thereof, to wit, Abner the son of Ner, captain of the host of Israel, and Amasa the son of Jether, captain of the host of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 33, E'Their blood shall therefore return upon the head of Joab, and upon the head of his seed for ever: but upon David, and upon his seed, and upon his house, and upon his throne, shall there be peace for ever from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 34, E'So Benaiah the son of Jehoiada went up, and fell upon him, and slew him: and he was buried in his own house in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 35, E'And the king put Benaiah the son of Jehoiada in his room over the host: and Zadok the priest did the king put in the room of Abiathar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 36, E'And the king sent and called for Shimei, and said unto him, Build thee an house in Jerusalem, and dwell there, and go not forth thence any whither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 37, E'For it shall be, that on the day thou goest out, and passest over the brook Kidron, thou shalt know for certain that thou shalt surely die: thy blood shall be upon thine own head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 38, E'And Shimei said unto the king, The saying is good: as my lord the king hath said, so will thy servant do. And Shimei dwelt in Jerusalem many days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 39, E'And it came to pass at the end of three years, that two of the servants of Shimei ran away unto Achish son of Maachah king of Gath. And they told Shimei, saying, Behold, thy servants be in Gath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 40, E'And Shimei arose, and saddled his ass, and went to Gath to Achish to seek his servants: and Shimei went, and brought his servants from Gath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 41, E'And it was told Solomon that Shimei had gone from Jerusalem to Gath, and was come again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 42, E'And the king sent and called for Shimei, and said unto him, Did I not make thee to swear by the LORD, and protested unto thee, saying, Know for a certain, on the day thou goest out, and walkest abroad any whither, that thou shalt surely die? and thou saidst unto me, The word that I have heard is good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 43, E'Why then hast thou not kept the oath of the LORD, and the commandment that I have charged thee with?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 44, E'The king said moreover to Shimei, Thou knowest all the wickedness which thine heart is privy to, that thou didst to David my father: therefore the LORD shall return thy wickedness upon thine own head;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 45, E'And king Solomon shall be blessed, and the throne of David shall be established before the LORD for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 2, 46, E'So the king commanded Benaiah the son of Jehoiada; which went out, and fell upon him, that he died. And the kingdom was established in the hand of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 1, E'And Solomon made affinity with Pharaoh king of Egypt, and took Pharaohâ€™s daughter, and brought her into the city of David, until he had made an end of building his own house, and the house of the LORD, and the wall of Jerusalem round about.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 2, E'Only the people sacrificed in high places, because there was no house built unto the name of the LORD, until those days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 3, E'And Solomon loved the LORD, walking in the statutes of David his father: only he sacrificed and burnt incense in high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 4, E'And the king went to Gibeon to sacrifice there; for that was the great high place: a thousand burnt offerings did Solomon offer upon that altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 5, E'In Gibeon the LORD appeared to Solomon in a dream by night: and God said, Ask what I shall give thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 6, E'And Solomon said, Thou hast shewed unto thy servant David my father great mercy, according as he walked before thee in truth, and in righteousness, and in uprightness of heart with thee; and thou hast kept for him this great kindness, that thou hast given him a son to sit on his throne, as it is this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 7, E'And now, O LORD my God, thou hast made thy servant king instead of David my father: and I am but a little child: I know not how to go out or come in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 8, E'And thy servant is in the midst of thy people which thou hast chosen, a great people, that cannot be numbered nor counted for multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 9, E'Give therefore thy servant an understanding heart to judge thy people, that I may discern between good and bad: for who is able to judge this thy so great a people?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 10, E'And the speech pleased the LORD, that Solomon had asked this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 11, E'And God said unto him, Because thou hast asked this thing, and hast not asked for thyself long life; neither hast asked riches for thyself, nor hast asked the life of thine enemies; but hast asked for thyself understanding to discern judgment;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 12, E'Behold, I have done according to thy words: lo, I have given thee a wise and an understanding heart; so that there was none like thee before thee, neither after thee shall any arise like unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 13, E'And I have also given thee that which thou hast not asked, both riches, and honour: so that there shall not be any among the kings like unto thee all thy days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 14, E'And if thou wilt walk in my ways, to keep my statutes and my commandments, as thy father David did walk, then I will lengthen thy days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 15, E'And Solomon awoke; and, behold, it was a dream. And he came to Jerusalem, and stood before the ark of the covenant of the LORD, and offered up burnt offerings, and offered peace offerings, and made a feast to all his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 16, E'Then came there two women, that were harlots, unto the king, and stood before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 17, E'And the one woman said, O my lord, I and this woman dwell in one house; and I was delivered of a child with her in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 18, E'And it came to pass the third day after that I was delivered, that this woman was delivered also: and we were together; there was no stranger with us in the house, save we two in the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 19, E'And this womanâ€™s child died in the night; because she overlaid it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 20, E'And she arose at midnight, and took my son from beside me, while thine handmaid slept, and laid it in her bosom, and laid her dead child in my bosom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 21, E'And when I rose in the morning to give my child suck, behold, it was dead: but when I had considered it in the morning, behold, it was not my son, which I did bear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 22, E'And the other woman said, Nay; but the living is my son, and the dead is thy son. And this said, No; but the dead is thy son, and the living is my son. Thus they spake before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 23, E'Then said the king, The one saith, This is my son that liveth, and thy son is the dead: and the other saith, Nay; but thy son is the dead, and my son is the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 24, E'And the king said, Bring me a sword. And they brought a sword before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 25, E'And the king said, Divide the living child in two, and give half to the one, and half to the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 26, E'Then spake the woman whose the living child was unto the king, for her bowels yearned upon her son, and she said, O my lord, give her the living child, and in no wise slay it. But the other said, Let it be neither mine nor thine, but divide it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 27, E'Then the king answered and said, Give her the living child, and in no wise slay it: she is the mother thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 3, 28, E'And all Israel heard of the judgment which the king had judged; and they feared the king: for they saw that the wisdom of God was in him, to do judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 1, E'So king Solomon was king over all Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 2, E'And these were the princes which he had; Azariah the son of Zadok the priest,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 3, E'Elihoreph and Ahiah, the sons of Shisha, scribes; Jehoshaphat the son of Ahilud, the recorder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 4, E'And Benaiah the son of Jehoiada was over the host: and Zadok and Abiathar were the priests:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 5, E'And Azariah the son of Nathan was over the officers: and Zabud the son of Nathan was principal officer, and the kingâ€™s friend:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 6, E'And Ahishar was over the household: and Adoniram the son of Abda was over the tribute.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 7, E'And Solomon had twelve officers over all Israel, which provided victuals for the king and his household: each man his month in a year made provision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 8, E'And these are their names: The son of Hur, in mount Ephraim:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 9, E'The son of Dekar, in Makaz, and in Shaalbim, and Bethshemesh, and Elonbethhanan:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 10, E'The son of Hesed, in Aruboth; to him pertained Sochoh, and all the land of Hepher:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 11, E'The son of Abinadab, in all the region of Dor; which had Taphath the daughter of Solomon to wife:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 12, E'Baana the son of Ahilud; to him pertained Taanach and Megiddo, and all Bethshean, which is by Zartanah beneath Jezreel, from Bethshean to Abelmeholah, even unto the place that is beyond Jokneam:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 13, E'The son of Geber, in Ramothgilead; to him pertained the towns of Jair the son of Manasseh, which are in Gilead; to him also pertained the region of Argob, which is in Bashan, threescore great cities with walls and brasen bars:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 14, E'Ahinadab the son of Iddo had Mahanaim:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 15, E'Ahimaaz was in Naphtali; he also took Basmath the daughter of Solomon to wife:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 16, E'Baanah the son of Hushai was in Asher and in Aloth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 17, E'Jehoshaphat the son of Paruah, in Issachar:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 18, E'Shimei the son of Elah, in Benjamin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 19, E'Geber the son of Uri was in the country of Gilead, in the country of Sihon king of the Amorites, and of Og king of Bashan; and he was the only officer which was in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 20, E'Judah and Israel were many, as the sand which is by the sea in multitude, eating and drinking, and making merry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 21, E'And Solomon reigned over all kingdoms from the river unto the land of the Philistines, and unto the border of Egypt: they brought presents, and served Solomon all the days of his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 22, E'And Solomonâ€™s provision for one day was thirty measures of fine flour, and threescore measures of meal,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 23, E'Ten fat oxen, and twenty oxen out of the pastures, and an hundred sheep, beside harts, and roebucks, and fallowdeer, and fatted fowl.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 24, E'For he had dominion over all the region on this side the river, from Tiphsah even to Azzah, over all the kings on this side the river: and he had peace on all sides round about him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 25, E'And Judah and Israel dwelt safely, every man under his vine and under his fig tree, from Dan even to Beersheba, all the days of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 26, E'And Solomon had forty thousand stalls of horses for his chariots, and twelve thousand horsemen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 27, E'And those officers provided victual for king Solomon, and for all that came unto king Solomonâ€™s table, every man in his month: they lacked nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 28, E'Barley also and straw for the horses and dromedaries brought they unto the place where the officers were, every man according to his charge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 29, E'And God gave Solomon wisdom and understanding exceeding much, and largeness of heart, even as the sand that is on the sea shore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 30, E'And Solomonâ€™s wisdom excelled the wisdom of all the children of the east country, and all the wisdom of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 31, E'For he was wiser than all men; than Ethan the Ezrahite, and Heman, and Chalcol, and Darda, the sons of Mahol: and his fame was in all nations round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 32, E'And he spake three thousand proverbs: and his songs were a thousand and five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 33, E'And he spake of trees, from the cedar tree that is in Lebanon even unto the hyssop that springeth out of the wall: he spake also of beasts, and of fowl, and of creeping things, and of fishes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 4, 34, E'And there came of all people to hear the wisdom of Solomon, from all kings of the earth, which had heard of his wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 1, E'And Hiram king of Tyre sent his servants unto Solomon; for he had heard that they had anointed him king in the room of his father: for Hiram was ever a lover of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 2, E'And Solomon sent to Hiram, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 3, E'Thou knowest how that David my father could not build an house unto the name of the LORD his God for the wars which were about him on every side, until the LORD put them under the soles of his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 4, E'But now the LORD my God hath given me rest on every side, so that there is neither adversary nor evil occurrent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 5, E'And, behold, I purpose to build an house unto the name of the LORD my God, as the LORD spake unto David my father, saying, Thy son, whom I will set upon thy throne in thy room, he shall build an house unto my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 6, E'Now therefore command thou that they hew me cedar trees out of Lebanon; and my servants shall be with thy servants: and unto thee will I give hire for thy servants according to all that thou shalt appoint: for thou knowest that there is not among us any that can skill to hew timber like unto the Sidonians.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 7, E'And it came to pass, when Hiram heard the words of Solomon, that he rejoiced greatly, and said, Blessed be the LORD this day, which hath given unto David a wise son over this great people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 8, E'And Hiram sent to Solomon, saying, I have considered the things which thou sentest to me for: and I will do all thy desire concerning timber of cedar, and concerning timber of fir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 9, E'My servants shall bring them down from Lebanon unto the sea: and I will convey them by sea in floats unto the place that thou shalt appoint me, and will cause them to be discharged there, and thou shalt receive them: and thou shalt accomplish my desire, in giving food for my household.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 10, E'So Hiram gave Solomon cedar trees and fir trees according to all his desire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 11, E'And Solomon gave Hiram twenty thousand measures of wheat for food to his household, and twenty measures of pure oil: thus gave Solomon to Hiram year by year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 12, E'And the LORD gave Solomon wisdom, as he promised him: and there was peace between Hiram and Solomon; and they two made a league together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 13, E'And king Solomon raised a levy out of all Israel; and the levy was thirty thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 14, E'And he sent them to Lebanon, ten thousand a month by courses: a month they were in Lebanon, and two months at home: and Adoniram was over the levy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 15, E'And Solomon had threescore and ten thousand that bare burdens, and fourscore thousand hewers in the mountains;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 16, E'Beside the chief of Solomonâ€™s officers which were over the work, three thousand and three hundred, which ruled over the people that wrought in the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 17, E'And the king commanded, and they brought great stones, costly stones, and hewed stones, to lay the foundation of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 5, 18, E'And Solomonâ€™s builders and Hiramâ€™s builders did hew them, and the stonesquarers: so they prepared timber and stones to build the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 1, E'And it came to pass in the four hundred and eightieth year after the children of Israel were come out of the land of Egypt, in the fourth year of Solomonâ€™s reign over Israel, in the month Zif, which is the second month, that he began to build the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 2, E'And the house which king Solomon built for the LORD, the length thereof was threescore cubits, and the breadth thereof twenty cubits, and the height thereof thirty cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 3, E'And the porch before the temple of the house, twenty cubits was the length thereof, according to the breadth of the house; and ten cubits was the breadth thereof before the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 4, E'And for the house he made windows of narrow lights.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 5, E'And against the wall of the house he built chambers round about, against the walls of the house round about, both of the temple and of the oracle: and he made chambers round about:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 6, E'The nethermost chamber was five cubits broad, and the middle was six cubits broad, and the third was seven cubits broad: for without in the wall of the house he made narrowed rests round about, that the beams should not be fastened in the walls of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 7, E'And the house, when it was in building, was built of stone made ready before it was brought thither: so that there was neither hammer nor axe nor any tool of iron heard in the house, while it was in building.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 8, E'The door for the middle chamber was in the right side of the house: and they went up with winding stairs into the middle chamber, and out of the middle into the third.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 9, E'So he built the house, and finished it; and covered the house with beams and boards of cedar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 10, E'And then he built chambers against all the house, five cubits high: and they rested on the house with timber of cedar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 11, E'And the word of the LORD came to Solomon, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 12, E'Concerning this house which thou art in building, if thou wilt walk in my statutes, and execute my judgments, and keep all my commandments to walk in them; then will I perform my word with thee, which I spake unto David thy father:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 13, E'And I will dwell among the children of Israel, and will not forsake my people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 14, E'So Solomon built the house, and finished it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 15, E'And he built the walls of the house within with boards of cedar, both the floor of the house, and the walls of the ceiling: and he covered them on the inside with wood, and covered the floor of the house with planks of fir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 16, E'And he built twenty cubits on the sides of the house, both the floor and the walls with boards of cedar: he even built them for it within, even for the oracle, even for the most holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 17, E'And the house, that is, the temple before it, was forty cubits long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 18, E'And the cedar of the house within was carved with knops and open flowers: all was cedar; there was no stone seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 19, E'And the oracle he prepared in the house within, to set there the ark of the covenant of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 20, E'And the oracle in the forepart was twenty cubits in length, and twenty cubits in breadth, and twenty cubits in the height thereof: and he overlaid it with pure gold; and so covered the altar which was of cedar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 21, E'So Solomon overlaid the house within with pure gold: and he made a partition by the chains of gold before the oracle; and he overlaid it with gold.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 22, E'And the whole house he overlaid with gold, until he had finished all the house: also the whole altar that was by the oracle he overlaid with gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 23, E'And within the oracle he made two cherubims of olive tree, each ten cubits high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 24, E'And five cubits was the one wing of the cherub, and five cubits the other wing of the cherub: from the uttermost part of the one wing unto the uttermost part of the other were ten cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 25, E'And the other cherub was ten cubits: both the cherubims were of one measure and one size.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 26, E'The height of the one cherub was ten cubits, and so was it of the other cherub.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 27, E'And he set the cherubims within the inner house: and they stretched forth the wings of the cherubims, so that the wing of the one touched the one wall, and the wing of the other cherub touched the other wall; and their wings touched one another in the midst of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 28, E'And he overlaid the cherubims with gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 29, E'And he carved all the walls of the house round about with carved figures of cherubims and palm trees and open flowers, within and without.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 30, E'And the floor of the house he overlaid with gold, within and without.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 31, E'And for the entering of the oracle he made doors of olive tree: the lintel and side posts were a fifth part of the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 32, E'The two doors also were of olive tree; and he carved upon them carvings of cherubims and palm trees and open flowers, and overlaid them with gold, and spread gold upon the cherubims, and upon the palm trees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 33, E'So also made he for the door of the temple posts of olive tree, a fourth part of the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 34, E'And the two doors were of fir tree: the two leaves of the one door were folding, and the two leaves of the other door were folding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 35, E'And he carved thereon cherubims and palm trees and open flowers: and covered them with gold fitted upon the carved work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 36, E'And he built the inner court with three rows of hewed stone, and a row of cedar beams.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 37, E'In the fourth year was the foundation of the house of the LORD laid, in the month Zif:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 6, 38, E'And in the eleventh year, in the month Bul, which is the eighth month, was the house finished throughout all the parts thereof, and according to all the fashion of it. So was he seven years in building it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 1, E'But Solomon was building his own house thirteen years, and he finished all his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 2, E'He built also the house of the forest of Lebanon; the length thereof was an hundred cubits, and the breadth thereof fifty cubits, and the height thereof thirty cubits, upon four rows of cedar pillars, with cedar beams upon the pillars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 3, E'And it was covered with cedar above upon the beams, that lay on forty five pillars, fifteen in a row.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 4, E'And there were windows in three rows, and light was against light in three ranks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 5, E'And all the doors and posts were square, with the windows: and light was against light in three ranks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 6, E'And he made a porch of pillars; the length thereof was fifty cubits, and the breadth thereof thirty cubits: and the porch was before them: and the other pillars and the thick beam were before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 7, E'Then he made a porch for the throne where he might judge, even the porch of judgment: and it was covered with cedar from one side of the floor to the other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 8, E'And his house where he dwelt had another court within the porch, which was of the like work. Solomon made also an house for Pharaohâ€™s daughter, whom he had taken to wife, like unto this porch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 9, E'All these were of costly stones, according to the measures of hewed stones, sawed with saws, within and without, even from the foundation unto the coping, and so on the outside toward the great court.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 10, E'And the foundation was of costly stones, even great stones, stones of ten cubits, and stones of eight cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 11, E'And above were costly stones, after the measures of hewed stones, and cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 12, E'And the great court round about was with three rows of hewed stones, and a row of cedar beams, both for the inner court of the house of the LORD, and for the porch of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 13, E'And king Solomon sent and fetched Hiram out of Tyre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 14, E'He was a widowâ€™s son of the tribe of Naphtali, and his father was a man of Tyre, a worker in brass: and he was filled with wisdom, and understanding, and cunning to work all works in brass. And he came to king Solomon, and wrought all his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 15, E'For he cast two pillars of brass, of eighteen cubits high apiece: and a line of twelve cubits did compass either of them about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 16, E'And he made two chapiters of molten brass, to set upon the tops of the pillars: the height of the one chapiter was five cubits, and the height of the other chapiter was five cubits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 17, E'And nets of checker work, and wreaths of chain work, for the chapiters which were upon the top of the pillars; seven for the one chapiter, and seven for the other chapiter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 18, E'And he made the pillars, and two rows round about upon the one network, to cover the chapiters that were upon the top, with pomegranates: and so did he for the other chapiter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 19, E'And the chapiters that were upon the top of the pillars were of lily work in the porch, four cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 20, E'And the chapiters upon the two pillars had pomegranates also above, over against the belly which was by the network: and the pomegranates were two hundred in rows round about upon the other chapiter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 21, E'And he set up the pillars in the porch of the temple: and he set up the right pillar, and called the name thereof Jachin: and he set up the left pillar, and called the name thereof Boaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 22, E'And upon the top of the pillars was lily work: so was the work of the pillars finished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 23, E'And he made a molten sea, ten cubits from the one brim to the other: it was round all about, and his height was five cubits: and a line of thirty cubits did compass it round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 24, E'And under the brim of it round about there were knops compassing it, ten in a cubit, compassing the sea round about: the knops were cast in two rows, when it was cast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 25, E'It stood upon twelve oxen, three looking toward the north, and three looking toward the west, and three looking toward the south, and three looking toward the east: and the sea was set above upon them, and all their hinder parts were inward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 26, E'And it was an hand breadth thick, and the brim thereof was wrought like the brim of a cup, with flowers of lilies: it contained two thousand baths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 27, E'And he made ten bases of brass; four cubits was the length of one base, and four cubits the breadth thereof, and three cubits the height of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 28, E'And the work of the bases was on this manner: they had borders, and the borders were between the ledges:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 29, E'And on the borders that were between the ledges were lions, oxen, and cherubims: and upon the ledges there was a base above: and beneath the lions and oxen were certain additions made of thin work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 30, E'And every base had four brasen wheels, and plates of brass: and the four corners thereof had undersetters: under the laver were undersetters molten, at the side of every addition.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 31, E'And the mouth of it within the chapiter and above was a cubit: but the mouth thereof was round after the work of the base, a cubit and an half: and also upon the mouth of it were gravings with their borders, foursquare, not round.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 32, E'And under the borders were four wheels; and the axletrees of the wheels were joined to the base: and the height of a wheel was a cubit and half a cubit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 33, E'And the work of the wheels was like the work of a chariot wheel: their axletrees, and their naves, and their felloes, and their spokes, were all molten.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 34, E'And there were four undersetters to the four corners of one base: and the undersetters were of the very base itself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 35, E'And in the top of the base was there a round compass of half a cubit high: and on the top of the base the ledges thereof and the borders thereof were of the same.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 36, E'For on the plates of the ledges thereof, and on the borders thereof, he graved cherubims, lions, and palm trees, according to the proportion of every one, and additions round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 37, E'After this manner he made the ten bases: all of them had one casting, one measure, and one size.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 38, E'Then made he ten lavers of brass: one laver contained forty baths: and every laver was four cubits: and upon every one of the ten bases one laver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 39, E'And he put five bases on the right side of the house, and five on the left side of the house: and he set the sea on the right side of the house eastward over against the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 40, E'And Hiram made the lavers, and the shovels, and the basons. So Hiram made an end of doing all the work that he made king Solomon for the house of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 41, E'The two pillars, and the two bowls of the chapiters that were on the top of the two pillars; and the two networks, to cover the two bowls of the chapiters which were upon the top of the pillars;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 42, E'And four hundred pomegranates for the two networks, even two rows of pomegranates for one network, to cover the two bowls of the chapiters that were upon the pillars;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 43, E'And the ten bases, and ten lavers on the bases;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 44, E'And one sea, and twelve oxen under the sea;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 45, E'And the pots, and the shovels, and the basons: and all these vessels, which Hiram made to king Solomon for the house of the LORD, were of bright brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 46, E'In the plain of Jordan did the king cast them, in the clay ground between Succoth and Zarthan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 47, E'And Solomon left all the vessels unweighed, because they were exceeding many: neither was the weight of the brass found out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 48, E'And Solomon made all the vessels that pertained unto the house of the LORD: the altar of gold, and the table of gold, whereupon the shewbread was,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 49, E'And the candlesticks of pure gold, five on the right side, and five on the left, before the oracle, with the flowers, and the lamps, and the tongs of gold,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 50, E'And the bowls, and the snuffers, and the basons, and the spoons, and the censers of pure gold; and the hinges of gold, both for the doors of the inner house, the most holy place, and for the doors of the house, to wit, of the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 7, 51, E'So was ended all the work that king Solomon made for the house of the LORD. And Solomon brought in the things which David his father had dedicated; even the silver, and the gold, and the vessels, did he put among the treasures of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 1, E'Then Solomon assembled the elders of Israel, and all the heads of the tribes, the chief of the fathers of the children of Israel, unto king Solomon in Jerusalem, that they might bring up the ark of the covenant of the LORD out of the city of David, which is Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 2, E'And all the men of Israel assembled themselves unto king Solomon at the feast in the month Ethanim, which is the seventh month.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 3, E'And all the elders of Israel came, and the priests took up the ark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 4, E'And they brought up the ark of the LORD, and the tabernacle of the congregation, and all the holy vessels that were in the tabernacle, even those did the priests and the Levites bring up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 5, E'And king Solomon, and all the congregation of Israel, that were assembled unto him, were with him before the ark, sacrificing sheep and oxen, that could not be told nor numbered for multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 6, E'And the priests brought in the ark of the covenant of the LORD unto his place, into the oracle of the house, to the most holy place, even under the wings of the cherubims.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 7, E'For the cherubims spread forth their two wings over the place of the ark, and the cherubims covered the ark and the staves thereof above.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 8, E'And they drew out the staves, that the ends of the staves were seen out in the holy place before the oracle, and they were not seen without: and there they are unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 9, E'There was nothing in the ark save the two tables of stone, which Moses put there at Horeb, when the LORD made a covenant with the children of Israel, when they came out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 10, E'And it came to pass, when the priests were come out of the holy place, that the cloud filled the house of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 11, E'So that the priests could not stand to minister because of the cloud: for the glory of the LORD had filled the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 12, E'Then spake Solomon, The LORD said that he would dwell in the thick darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 13, E'I have surely built thee an house to dwell in, a settled place for thee to abide in for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 14, E'And the king turned his face about, and blessed all the congregation of Israel: (and all the congregation of Israel stood;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 15, E'And he said, Blessed be the LORD God of Israel, which spake with his mouth unto David my father, and hath with his hand fulfilled it, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 16, E'Since the day that I brought forth my people Israel out of Egypt, I chose no city out of all the tribes of Israel to build an house, that my name might be therein; but I chose David to be over my people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 17, E'And it was in the heart of David my father to build an house for the name of the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 18, E'And the LORD said unto David my father, Whereas it was in thine heart to build an house unto my name, thou didst well that it was in thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 19, E'Nevertheless thou shalt not build the house; but thy son that shall come forth out of thy loins, he shall build the house unto my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 20, E'And the LORD hath performed his word that he spake, and I am risen up in the room of David my father, and sit on the throne of Israel, as the LORD promised, and have built an house for the name of the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 21, E'And I have set there a place for the ark, wherein is the covenant of the LORD, which he made with our fathers, when he brought them out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 22, E'And Solomon stood before the altar of the LORD in the presence of all the congregation of Israel, and spread forth his hands toward heaven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 23, E'And he said, LORD God of Israel, there is no God like thee, in heaven above, or on earth beneath, who keepest covenant and mercy with thy servants that walk before thee with all their heart:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 24, E'Who hast kept with thy servant David my father that thou promisedst him: thou spakest also with thy mouth, and hast fulfilled it with thine hand, as it is this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 25, E'Therefore now, LORD God of Israel, keep with thy servant David my father that thou promisedst him, saying, There shall not fail thee a man in my sight to sit on the throne of Israel; so that thy children take heed to their way, that they walk before me as thou hast walked before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 26, E'And now, O God of Israel, let thy word, I pray thee, be verified, which thou spakest unto thy servant David my father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 27, E'But will God indeed dwell on the earth? behold, the heaven and heaven of heavens cannot contain thee; how much less this house that I have builded?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 28, E'Yet have thou respect unto the prayer of thy servant, and to his supplication, O LORD my God, to hearken unto the cry and to the prayer, which thy servant prayeth before thee to day:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 29, E'That thine eyes may be open toward this house night and day, even toward the place of which thou hast said, My name shall be there: that thou mayest hearken unto the prayer which thy servant shall make toward this place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 30, E'And hearken thou to the supplication of thy servant, and of thy people Israel, when they shall pray toward this place: and hear thou in heaven thy dwelling place: and when thou hearest, forgive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 31, E'If any man trespass against his neighbour, and an oath be laid upon him to cause him to swear, and the oath come before thine altar in this house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 32, E'Then hear thou in heaven, and do, and judge thy servants, condemning the wicked, to bring his way upon his head; and justifying the righteous, to give him according to his righteousness.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 33, E'When thy people Israel be smitten down before the enemy, because they have sinned against thee, and shall turn again to thee, and confess thy name, and pray, and make supplication unto thee in this house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 34, E'Then hear thou in heaven, and forgive the sin of thy people Israel, and bring them again unto the land which thou gavest unto their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 35, E'When heaven is shut up, and there is no rain, because they have sinned against thee; if they pray toward this place, and confess thy name, and turn from their sin, when thou afflictest them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 36, E'Then hear thou in heaven, and forgive the sin of thy servants, and of thy people Israel, that thou teach them the good way wherein they should walk, and give rain upon thy land, which thou hast given to thy people for an inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 37, E'If there be in the land famine, if there be pestilence, blasting, mildew, locust, or if there be caterpiller; if their enemy besiege them in the land of their cities; whatsoever plague, whatsoever sickness there be;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 38, E'What prayer and supplication soever be made by any man, or by all thy people Israel, which shall know every man the plague of his own heart, and spread forth his hands toward this house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 39, E'Then hear thou in heaven thy dwelling place, and forgive, and do, and give to every man according to his ways, whose heart thou knowest; (for thou, even thou only, knowest the hearts of all the children of men;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 40, E'That they may fear thee all the days that they live in the land which thou gavest unto our fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 41, E'Moreover concerning a stranger, that is not of thy people Israel, but cometh out of a far country for thy nameâ€™s sake;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 42, E'(For they shall hear of thy great name, and of thy strong hand, and of thy stretched out arm;) when he shall come and pray toward this house;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 43, E'Hear thou in heaven thy dwelling place, and do according to all that the stranger calleth to thee for: that all people of the earth may know thy name, to fear thee, as do thy people Israel; and that they may know that this house, which I have builded, is called by thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 44, E'If thy people go out to battle against their enemy, whithersoever thou shalt send them, and shall pray unto the LORD toward the city which thou hast chosen, and toward the house that I have built for thy name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 45, E'Then hear thou in heaven their prayer and their supplication, and maintain their cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 46, E'If they sin against thee, (for there is no man that sinneth not,) and thou be angry with them, and deliver them to the enemy, so that they carry them away captives unto the land of the enemy, far or near;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 47, E'Yet if they shall bethink themselves in the land whither they were carried captives, and repent, and make supplication unto thee in the land of them that carried them captives, saying, We have sinned, and have done perversely, we have committed wickedness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 48, E'And so return unto thee with all their heart, and with all their soul, in the land of their enemies, which led them away captive, and pray unto thee toward their land, which thou gavest unto their fathers, the city which thou hast chosen, and the house which I have built for thy name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 49, E'Then hear thou their prayer and their supplication in heaven thy dwelling place, and maintain their cause,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 50, E'And forgive thy people that have sinned against thee, and all their transgressions wherein they have transgressed against thee, and give them compassion before them who carried them captive, that they may have compassion on them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 51, E'For they be thy people, and thine inheritance, which thou broughtest forth out of Egypt, from the midst of the furnace of iron:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 52, E'That thine eyes may be open unto the supplication of thy servant, and unto the supplication of thy people Israel, to hearken unto them in all that they call for unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 53, E'For thou didst separate them from among all the people of the earth, to be thine inheritance, as thou spakest by the hand of Moses thy servant, when thou broughtest our fathers out of Egypt, O LORD God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 54, E'And it was so, that when Solomon had made an end of praying all this prayer and supplication unto the LORD, he arose from before the altar of the LORD, from kneeling on his knees with his hands spread up to heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 55, E'And he stood, and blessed all the congregation of Israel with a loud voice, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 56, E'Blessed be the LORD, that hath given rest unto his people Israel, according to all that he promised: there hath not failed one word of all his good promise, which he promised by the hand of Moses his servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 57, E'The LORD our God be with us, as he was with our fathers: let him not leave us, nor forsake us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 58, E'That he may incline our hearts unto him, to walk in all his ways, and to keep his commandments, and his statutes, and his judgments, which he commanded our fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 59, E'And let these my words, wherewith I have made supplication before the LORD, be nigh unto the LORD our God day and night, that he maintain the cause of his servant, and the cause of his people Israel at all times, as the matter shall require:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 60, E'That all the people of the earth may know that the LORD is God, and that there is none else.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 61, E'Let your heart therefore be perfect with the LORD our God, to walk in his statutes, and to keep his commandments, as at this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 62, E'And the king, and all Israel with him, offered sacrifice before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 63, E'And Solomon offered a sacrifice of peace offerings, which he offered unto the LORD, two and twenty thousand oxen, and an hundred and twenty thousand sheep. So the king and all the children of Israel dedicated the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 64, E'The same day did the king hallow the middle of the court that was before the house of the LORD: for there he offered burnt offerings, and meat offerings, and the fat of the peace offerings: because the brasen altar that was before the LORD was too little to receive the burnt offerings, and meat offerings, and the fat of the peace offerings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 65, E'And at that time Solomon held a feast, and all Israel with him, a great congregation, from the entering in of Hamath unto the river of Egypt, before the LORD our God, seven days and seven days, even fourteen days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 8, 66, E'On the eighth day he sent the people away: and they blessed the king, and went unto their tents joyful and glad of heart for all the goodness that the LORD had done for David his servant, and for Israel his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 1, E'And it came to pass, when Solomon had finished the building of the house of the LORD, and the kingâ€™s house, and all Solomonâ€™s desire which he was pleased to do,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 2, E'That the LORD appeared to Solomon the second time, as he had appeared unto him at Gibeon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 3, E'And the LORD said unto him, I have heard thy prayer and thy supplication, that thou hast made before me: I have hallowed this house, which thou hast built, to put my name there for ever; and mine eyes and mine heart shall be there perpetually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 4, E'And if thou wilt walk before me, as David thy father walked, in integrity of heart, and in uprightness, to do according to all that I have commanded thee, and wilt keep my statutes and my judgments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 5, E'Then I will establish the throne of thy kingdom upon Israel for ever, as I promised to David thy father, saying, There shall not fail thee a man upon the throne of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 6, E'But if ye shall at all turn from following me, ye or your children, and will not keep my commandments and my statutes which I have set before you, but go and serve other gods, and worship them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 7, E'Then will I cut off Israel out of the land which I have given them; and this house, which I have hallowed for my name, will I cast out of my sight; and Israel shall be a proverb and a byword among all people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 8, E'And at this house, which is high, every one that passeth by it shall be astonished, and shall hiss; and they shall say, Why hath the LORD done thus unto this land, and to this house?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 9, E'And they shall answer, Because they forsook the LORD their God, who brought forth their fathers out of the land of Egypt, and have taken hold upon other gods, and have worshipped them, and served them: therefore hath the LORD brought upon them all this evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 10, E'And it came to pass at the end of twenty years, when Solomon had built the two houses, the house of the LORD, and the kingâ€™s house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 11, E'(Now Hiram the king of Tyre had furnished Solomon with cedar trees and fir trees, and with gold, according to all his desire,) that then king Solomon gave Hiram twenty cities in the land of Galilee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 12, E'And Hiram came out from Tyre to see the cities which Solomon had given him; and they pleased him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 13, E'And he said, What cities are these which thou hast given me, my brother? And he called them the land of Cabul unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 14, E'And Hiram sent to the king sixscore talents of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 15, E'And this is the reason of the levy which king Solomon raised; for to build the house of the LORD, and his own house, and Millo, and the wall of Jerusalem, and Hazor, and Megiddo, and Gezer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 16, E'For Pharaoh king of Egypt had gone up, and taken Gezer, and burnt it with fire, and slain the Canaanites that dwelt in the city, and given it for a present unto his daughter, Solomonâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 17, E'And Solomon built Gezer, and Bethhoron the nether,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 18, E'And Baalath, and Tadmor in the wilderness, in the land,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 19, E'And all the cities of store that Solomon had, and cities for his chariots, and cities for his horsemen, and that which Solomon desired to build in Jerusalem, and in Lebanon, and in all the land of his dominion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 20, E'And all the people that were left of the Amorites, Hittites, Perizzites, Hivites, and Jebusites, which were not of the children of Israel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 21, E'Their children that were left after them in the land, whom the children of Israel also were not able utterly to destroy, upon those did Solomon levy a tribute of bondservice unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 22, E'But of the children of Israel did Solomon make no bondmen: but they were men of war, and his servants, and his princes, and his captains, and rulers of his chariots, and his horsemen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 23, E'These were the chief of the officers that were over Solomonâ€™s work, five hundred and fifty, which bare rule over the people that wrought in the work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 24, E'But Pharaohâ€™s daughter came up out of the city of David unto her house which Solomon had built for her: then did he build Millo.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 25, E'And three times in a year did Solomon offer burnt offerings and peace offerings upon the altar which he built unto the LORD, and he burnt incense upon the altar that was before the LORD. So he finished the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 26, E'And king Solomon made a navy of ships in Eziongeber, which is beside Eloth, on the shore of the Red sea, in the land of Edom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 27, E'And Hiram sent in the navy his servants, shipmen that had knowledge of the sea, with the servants of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 9, 28, E'And they came to Ophir, and fetched from thence gold, four hundred and twenty talents, and brought it to king Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 1, E'And when the queen of Sheba heard of the fame of Solomon concerning the name of the LORD, she came to prove him with hard questions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 2, E'And she came to Jerusalem with a very great train, with camels that bare spices, and very much gold, and precious stones: and when she was come to Solomon, she communed with him of all that was in her heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 3, E'And Solomon told her all her questions: there was not any thing hid from the king, which he told her not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 4, E'And when the queen of Sheba had seen all Solomonâ€™s wisdom, and the house that he had built,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 5, E'And the meat of his table, and the sitting of his servants, and the attendance of his ministers, and their apparel, and his cupbearers, and his ascent by which he went up unto the house of the LORD; there was no more spirit in her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 6, E'And she said to the king, It was a true report that I heard in mine own land of thy acts and of thy wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 7, E'Howbeit I believed not the words, until I came, and mine eyes had seen it: and, behold, the half was not told me: thy wisdom and prosperity exceedeth the fame which I heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 8, E'Happy are thy men, happy are these thy servants, which stand continually before thee, and that hear thy wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 9, E'Blessed be the LORD thy God, which delighted in thee, to set thee on the throne of Israel: because the LORD loved Israel for ever, therefore made he thee king, to do judgment and justice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 10, E'And she gave the king an hundred and twenty talents of gold, and of spices very great store, and precious stones: there came no more such abundance of spices as these which the queen of Sheba gave to king Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 11, E'And the navy also of Hiram, that brought gold from Ophir, brought in from Ophir great plenty of almug trees, and precious stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 12, E'And the king made of the almug trees pillars for the house of the LORD, and for the kingâ€™s house, harps also and psalteries for singers: there came no such almug trees, nor were seen unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 13, E'And king Solomon gave unto the queen of Sheba all her desire, whatsoever she asked, beside that which Solomon gave her of his royal bounty. So she turned and went to her own country, she and her servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 14, E'Now the weight of gold that came to Solomon in one year was six hundred threescore and six talents of gold,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 15, E'Beside that he had of the merchantmen, and of the traffick of the spice merchants, and of all the kings of Arabia, and of the governors of the country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 16, E'And king Solomon made two hundred targets of beaten gold: six hundred shekels of gold went to one target.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 17, E'And he made three hundred shields of beaten gold; three pound of gold went to one shield: and the king put them in the house of the forest of Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 18, E'Moreover the king made a great throne of ivory, and overlaid it with the best gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 19, E'The throne had six steps, and the top of the throne was round behind: and there were stays on either side on the place of the seat, and two lions stood beside the stays.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 20, E'And twelve lions stood there on the one side and on the other upon the six steps: there was not the like made in any kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 21, E'And all king Solomonâ€™s drinking vessels were of gold, and all the vessels of the house of the forest of Lebanon were of pure gold; none were of silver: it was nothing accounted of in the days of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 22, E'For the king had at sea a navy of Tharshish with the navy of Hiram: once in three years came the navy of Tharshish, bringing gold, and silver, ivory, and apes, and peacocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 23, E'So king Solomon exceeded all the kings of the earth for riches and for wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 24, E'And all the earth sought to Solomon, to hear his wisdom, which God had put in his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 25, E'And they brought every man his present, vessels of silver, and vessels of gold, and garments, and armour, and spices, horses, and mules, a rate year by year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 26, E'And Solomon gathered together chariots and horsemen: and he had a thousand and four hundred chariots, and twelve thousand horsemen, whom he bestowed in the cities for chariots, and with the king at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 27, E'And the king made silver to be in Jerusalem as stones, and cedars made he to be as the sycomore trees that are in the vale, for abundance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 28, E'And Solomon had horses brought out of Egypt, and linen yarn: the kingâ€™s merchants received the linen yarn at a price.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 10, 29, E'And a chariot came up and went out of Egypt for six hundred shekels of silver, and an horse for an hundred and fifty: and so for all the kings of the Hittites, and for the kings of Syria, did they bring them out by their means.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 1, E'But king Solomon loved many strange women, together with the daughter of Pharaoh, women of the Moabites, Ammonites, Edomites, Zidonians, and Hittites;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 2, E'Of the nations concerning which the LORD said unto the children of Israel, Ye shall not go in to them, neither shall they come in unto you: for surely they will turn away your heart after their gods: Solomon clave unto these in love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 3, E'And he had seven hundred wives, princesses, and three hundred concubines: and his wives turned away his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 4, E'For it came to pass, when Solomon was old, that his wives turned away his heart after other gods: and his heart was not perfect with the LORD his God, as was the heart of David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 5, E'For Solomon went after Ashtoreth the goddess of the Zidonians, and after Milcom the abomination of the Ammonites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 6, E'And Solomon did evil in the sight of the LORD, and went not fully after the LORD, as did David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 7, E'Then did Solomon build an high place for Chemosh, the abomination of Moab, in the hill that is before Jerusalem, and for Molech, the abomination of the children of Ammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 8, E'And likewise did he for all his strange wives, which burnt incense and sacrificed unto their gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 9, E'And the LORD was angry with Solomon, because his heart was turned from the LORD God of Israel, which had appeared unto him twice,')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 10, E'And had commanded him concerning this thing, that he should not go after other gods: but he kept not that which the LORD commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 11, E'Wherefore the LORD said unto Solomon, Forasmuch as this is done of thee, and thou hast not kept my covenant and my statutes, which I have commanded thee, I will surely rend the kingdom from thee, and will give it to thy servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 12, E'Notwithstanding in thy days I will not do it for David thy fatherâ€™s sake: but I will rend it out of the hand of thy son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 13, E'Howbeit I will not rend away all the kingdom; but will give one tribe to thy son for David my servantâ€™s sake, and for Jerusalemâ€™s sake which I have chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 14, E'And the LORD stirred up an adversary unto Solomon, Hadad the Edomite: he was of the kingâ€™s seed in Edom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 15, E'For it came to pass, when David was in Edom, and Joab the captain of the host was gone up to bury the slain, after he had smitten every male in Edom;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 16, E'(For six months did Joab remain there with all Israel, until he had cut off every male in Edom:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 17, E'That Hadad fled, he and certain Edomites of his fatherâ€™s servants with him, to go into Egypt; Hadad being yet a little child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 18, E'And they arose out of Midian, and came to Paran: and they took men with them out of Paran, and they came to Egypt, unto Pharaoh king of Egypt; which gave him an house, and appointed him victuals, and gave him land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 19, E'And Hadad found great favour in the sight of Pharaoh, so that he gave him to wife the sister of his own wife, the sister of Tahpenes the queen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 20, E'And the sister of Tahpenes bare him Genubath his son, whom Tahpenes weaned in Pharaohâ€™s house: and Genubath was in Pharaohâ€™s household among the sons of Pharaoh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 21, E'And when Hadad heard in Egypt that David slept with his fathers, and that Joab the captain of the host was dead, Hadad said to Pharaoh, Let me depart, that I may go to mine own country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 22, E'Then Pharaoh said unto him, But what hast thou lacked with me, that, behold, thou seekest to go to thine own country? And he answered, Nothing: howbeit let me go in any wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 23, E'And God stirred him up another adversary, Rezon the son of Eliadah, which fled from his lord Hadadezer king of Zobah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 24, E'And he gathered men unto him, and became captain over a band, when David slew them of Zobah: and they went to Damascus, and dwelt therein, and reigned in Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 25, E'And he was an adversary to Israel all the days of Solomon, beside the mischief that Hadad did: and he abhorred Israel, and reigned over Syria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 26, E'And Jeroboam the son of Nebat, an Ephrathite of Zereda, Solomonâ€™s servant, whose motherâ€™s name was Zeruah, a widow woman, even he lifted up his hand against the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 27, E'And this was the cause that he lifted up his hand against the king: Solomon built Millo, and repaired the breaches of the city of David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 28, E'And the man Jeroboam was a mighty man of valour: and Solomon seeing the young man that he was industrious, he made him ruler over all the charge of the house of Joseph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 29, E'And it came to pass at that time when Jeroboam went out of Jerusalem, that the prophet Ahijah the Shilonite found him in the way; and he had clad himself with a new garment; and they two were alone in the field:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 30, E'And Ahijah caught the new garment that was on him, and rent it in twelve pieces:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 31, E'And he said to Jeroboam, Take thee ten pieces: for thus saith the LORD, the God of Israel, Behold, I will rend the kingdom out of the hand of Solomon, and will give ten tribes to thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 32, E'(But he shall have one tribe for my servant Davidâ€™s sake, and for Jerusalemâ€™s sake, the city which I have chosen out of all the tribes of Israel:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 33, E'Because that they have forsaken me, and have worshipped Ashtoreth the goddess of the Zidonians, Chemosh the god of the Moabites, and Milcom the god of the children of Ammon, and have not walked in my ways, to do that which is right in mine eyes, and to keep my statutes and my judgments, as did David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 34, E'Howbeit I will not take the whole kingdom out of his hand: but I will make him prince all the days of his life for David my servantâ€™s sake, whom I chose, because he kept my commandments and my statutes:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 35, E'But I will take the kingdom out of his sonâ€™s hand, and will give it unto thee, even ten tribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 36, E'And unto his son will I give one tribe, that David my servant may have a light alway before me in Jerusalem, the city which I have chosen me to put my name there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 37, E'And I will take thee, and thou shalt reign according to all that thy soul desireth, and shalt be king over Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 38, E'And it shall be, if thou wilt hearken unto all that I command thee, and wilt walk in my ways, and do that is right in my sight, to keep my statutes and my commandments, as David my servant did; that I will be with thee, and build thee a sure house, as I built for David, and will give Israel unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 39, E'And I will for this afflict the seed of David, but not for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 40, E'Solomon sought therefore to kill Jeroboam. And Jeroboam arose, and fled into Egypt, unto Shishak king of Egypt, and was in Egypt until the death of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 41, E'And the rest of the acts of Solomon, and all that he did, and his wisdom, are they not written in the book of the acts of Solomon?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 42, E'And the time that Solomon reigned in Jerusalem over all Israel was forty years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 11, 43, E'And Solomon slept with his fathers, and was buried in the city of David his father: and Rehoboam his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 1, E'And Rehoboam went to Shechem: for all Israel were come to Shechem to make him king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 2, E'And it came to pass, when Jeroboam the son of Nebat, who was yet in Egypt, heard of it, (for he was fled from the presence of king Solomon, and Jeroboam dwelt in Egypt;)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 3, E'That they sent and called him. And Jeroboam and all the congregation of Israel came, and spake unto Rehoboam, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 4, E'Thy father made our yoke grievous: now therefore make thou the grievous service of thy father, and his heavy yoke which he put upon us, lighter, and we will serve thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 5, E'And he said unto them, Depart yet for three days, then come again to me. And the people departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 6, E'And king Rehoboam consulted with the old men, that stood before Solomon his father while he yet lived, and said, How do ye advise that I may answer this people?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 7, E'And they spake unto him, saying, If thou wilt be a servant unto this people this day, and wilt serve them, and answer them, and speak good words to them, then they will be thy servants for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 8, E'But he forsook the counsel of the old men, which they had given him, and consulted with the young men that were grown up with him, and which stood before him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 9, E'And he said unto them, What counsel give ye that we may answer this people, who have spoken to me, saying, Make the yoke which thy father did put upon us lighter?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 10, E'And the young men that were grown up with him spake unto him, saying, Thus shalt thou speak unto this people that spake unto thee, saying, Thy father made our yoke heavy, but make thou it lighter unto us; thus shalt thou say unto them, My little finger shall be thicker than my fatherâ€™s loins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 11, E'And now whereas my father did lade you with a heavy yoke, I will add to your yoke: my father hath chastised you with whips, but I will chastise you with scorpions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 12, E'So Jeroboam and all the people came to Rehoboam the third day, as the king had appointed, saying, Come to me again the third day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 13, E'And the king answered the people roughly, and forsook the old menâ€™s counsel that they gave him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 14, E'And spake to them after the counsel of the young men, saying, My father made your yoke heavy, and I will add to your yoke: my father also chastised you with whips, but I will chastise you with scorpions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 15, E'Wherefore the king hearkened not unto the people; for the cause was from the LORD, that he might perform his saying, which the LORD spake by Ahijah the Shilonite unto Jeroboam the son of Nebat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 16, E'So when all Israel saw that the king hearkened not unto them, the people answered the king, saying, What portion have we in David? neither have we inheritance in the son of Jesse: to your tents, O Israel: now see to thine own house, David. So Israel departed unto their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 17, E'But as for the children of Israel which dwelt in the cities of Judah, Rehoboam reigned over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 18, E'Then king Rehoboam sent Adoram, who was over the tribute; and all Israel stoned him with stones, that he died. Therefore king Rehoboam made speed to get him up to his chariot, to flee to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 19, E'So Israel rebelled against the house of David unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 20, E'And it came to pass, when all Israel heard that Jeroboam was come again, that they sent and called him unto the congregation, and made him king over all Israel: there was none that followed the house of David, but the tribe of Judah only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 21, E'And when Rehoboam was come to Jerusalem, he assembled all the house of Judah, with the tribe of Benjamin, an hundred and fourscore thousand chosen men, which were warriors, to fight against the house of Israel, to bring the kingdom again to Rehoboam the son of Solomon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 22, E'But the word of God came unto Shemaiah the man of God, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 23, E'Speak unto Rehoboam, the son of Solomon, king of Judah, and unto all the house of Judah and Benjamin, and to the remnant of the people, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 24, E'Thus saith the LORD, Ye shall not go up, nor fight against your brethren the children of Israel: return every man to his house; for this thing is from me. They hearkened therefore to the word of the LORD, and returned to depart, according to the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 25, E'Then Jeroboam built Shechem in mount Ephraim, and dwelt therein; and went out from thence, and built Penuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 26, E'And Jeroboam said in his heart, Now shall the kingdom return to the house of David:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 27, E'If this people go up to do sacrifice in the house of the LORD at Jerusalem, then shall the heart of this people turn again unto their lord, even unto Rehoboam king of Judah, and they shall kill me, and go again to Rehoboam king of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 28, E'Whereupon the king took counsel, and made two calves of gold, and said unto them, It is too much for you to go up to Jerusalem: behold thy gods, O Israel, which brought thee up out of the land of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 29, E'And he set the one in Bethel, and the other put he in Dan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 30, E'And this thing became a sin: for the people went to worship before the one, even unto Dan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 31, E'And he made an house of high places, and made priests of the lowest of the people, which were not of the sons of Levi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 32, E'And Jeroboam ordained a feast in the eighth month, on the fifteenth day of the month, like unto the feast that is in Judah, and he offered upon the altar. So did he in Bethel, sacrificing unto the calves that he had made: and he placed in Bethel the priests of the high places which he had made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 12, 33, E'So he offered upon the altar which he had made in Bethel the fifteenth day of the eighth month, even in the month which he had devised of his own heart; and ordained a feast unto the children of Israel: and he offered upon the altar, and burnt incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 1, E'And, behold, there came a man of God out of Judah by the word of the LORD unto Bethel: and Jeroboam stood by the altar to burn incense.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 2, E'And he cried against the altar in the word of the LORD, and said, O altar, altar, thus saith the LORD; Behold, a child shall be born unto the house of David, Josiah by name; and upon thee shall he offer the priests of the high places that burn incense upon thee, and menâ€™s bones shall be burnt upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 3, E'And he gave a sign the same day, saying, This is the sign which the LORD hath spoken; Behold, the altar shall be rent, and the ashes that are upon it shall be poured out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 4, E'And it came to pass, when king Jeroboam heard the saying of the man of God, which had cried against the altar in Bethel, that he put forth his hand from the altar, saying, Lay hold on him. And his hand, which he put forth against him, dried up, so that he could not pull it in again to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 5, E'The altar also was rent, and the ashes poured out from the altar, according to the sign which the man of God had given by the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 6, E'And the king answered and said unto the man of God, Intreat now the face of the LORD thy God, and pray for me, that my hand may be restored me again. And the man of God besought the LORD, and the kingâ€™s hand was restored him again, and became as it was before.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 7, E'And the king said unto the man of God, Come home with me, and refresh thyself, and I will give thee a reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 8, E'And the man of God said unto the king, If thou wilt give me half thine house, I will not go in with thee, neither will I eat bread nor drink water in this place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 9, E'For so was it charged me by the word of the LORD, saying, Eat no bread, nor drink water, nor turn again by the same way that thou camest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 10, E'So he went another way, and returned not by the way that he came to Bethel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 11, E'Now there dwelt an old prophet in Bethel; and his sons came and told him all the works that the man of God had done that day in Bethel: the words which he had spoken unto the king, them they told also to their father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 12, E'And their father said unto them, What way went he? For his sons had seen what way the man of God went, which came from Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 13, E'And he said unto his sons, Saddle me the ass. So they saddled him the ass: and he rode thereon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 14, E'And went after the man of God, and found him sitting under an oak: and he said unto him, Art thou the man of God that camest from Judah? And he said, I am.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 15, E'Then he said unto him, Come home with me, and eat bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 16, E'And he said, I may not return with thee, nor go in with thee: neither will I eat bread nor drink water with thee in this place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 17, E'For it was said to me by the word of the LORD, Thou shalt eat no bread nor drink water there, nor turn again to go by the way that thou camest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 18, E'He said unto him, I am a prophet also as thou art; and an angel spake unto me by the word of the LORD, saying, Bring him back with thee into thine house, that he may eat bread and drink water. But he lied unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 19, E'So he went back with him, and did eat bread in his house, and drank water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 20, E'And it came to pass, as they sat at the table, that the word of the LORD came unto the prophet that brought him back:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 21, E'And he cried unto the man of God that came from Judah, saying, Thus saith the LORD, Forasmuch as thou hast disobeyed the mouth of the LORD, and hast not kept the commandment which the LORD thy God commanded thee,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 22, E'But camest back, and hast eaten bread and drunk water in the place, of the which the Lord did say to thee, Eat no bread, and drink no water; thy carcase shall not come unto the sepulchre of thy fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 23, E'And it came to pass, after he had eaten bread, and after he had drunk, that he saddled for him the ass, to wit, for the prophet whom he had brought back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 24, E'And when he was gone, a lion met him by the way, and slew him: and his carcase was cast in the way, and the ass stood by it, the lion also stood by the carcase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 25, E'And, behold, men passed by, and saw the carcase cast in the way, and the lion standing by the carcase: and they came and told it in the city where the old prophet dwelt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 26, E'And when the prophet that brought him back from the way heard thereof, he said, It is the man of God, who was disobedient unto the word of the LORD: therefore the LORD hath delivered him unto the lion, which hath torn him, and slain him, according to the word of the LORD, which he spake unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 27, E'And he spake to his sons, saying, Saddle me the ass. And they saddled him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 28, E'And he went and found his carcase cast in the way, and the ass and the lion standing by the carcase: the lion had not eaten the carcase, nor torn the ass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 29, E'And the prophet took up the carcase of the man of God, and laid it upon the ass, and brought it back: and the old prophet came to the city, to mourn and to bury him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 30, E'And he laid his carcase in his own grave; and they mourned over him, saying, Alas, my brother!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 31, E'And it came to pass, after he had buried him, that he spake to his sons, saying, When I am dead, then bury me in the sepulchre wherein the man of God is buried; lay my bones beside his bones:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 32, E'For the saying which he cried by the word of the LORD against the altar in Bethel, and against all the houses of the high places which are in the cities of Samaria, shall surely come to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 33, E'After this thing Jeroboam returned not from his evil way, but made again of the lowest of the people priests of the high places: whosoever would, he consecrated him, and he became one of the priests of the high places.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 13, 34, E'And this thing became sin unto the house of Jeroboam, even to cut it off, and to destroy it from off the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 1, E'At that time Abijah the son of Jeroboam fell sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 2, E'And Jeroboam said to his wife, Arise, I pray thee, and disguise thyself, that thou be not known to be the wife of Jeroboam; and get thee to Shiloh: behold, there is Ahijah the prophet, which told me that I should be king over this people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 3, E'And take with thee ten loaves, and cracknels, and a cruse of honey, and go to him: he shall tell thee what shall become of the child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 4, E'And Jeroboamâ€™s wife did so, and arose, and went to Shiloh, and came to the house of Ahijah. But Ahijah could not see; for his eyes were set by reason of his age.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 5, E'And the LORD said unto Ahijah, Behold, the wife of Jeroboam cometh to ask a thing of thee for her son; for he is sick: thus and thus shalt thou say unto her: for it shall be, when she cometh in, that she shall feign herself to be another woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 6, E'And it was so, when Ahijah heard the sound of her feet, as she came in at the door, that he said, Come in, thou wife of Jeroboam; why feignest thou thyself to be another? for I am sent to thee with heavy tidings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 7, E'Go, tell Jeroboam, Thus saith the LORD God of Israel, Forasmuch as I exalted thee from among the people, and made thee prince over my people Israel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 8, E'And rent the kingdom away from the house of David, and gave it thee: and yet thou hast not been as my servant David, who kept my commandments, and who followed me with all his heart, to do that only which was right in mine eyes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 9, E'But hast done evil above all that were before thee: for thou hast gone and made thee other gods, and molten images, to provoke me to anger, and hast cast me behind thy back:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 10, E'Therefore, behold, I will bring evil upon the house of Jeroboam, and will cut off from Jeroboam him that pisseth against the wall, and him that is shut up and left in Israel, and will take away the remnant of the house of Jeroboam, as a man taketh away dung, till it be all gone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 11, E'Him that dieth of Jeroboam in the city shall the dogs eat; and him that dieth in the field shall the fowls of the air eat: for the LORD hath spoken it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 12, E'Arise thou therefore, get thee to thine own house: and when thy feet enter into the city, the child shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 13, E'And all Israel shall mourn for him, and bury him: for he only of Jeroboam shall come to the grave, because in him there is found some good thing toward the LORD God of Israel in the house of Jeroboam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 14, E'Moreover the LORD shall raise him up a king over Israel, who shall cut off the house of Jeroboam that day: but what? even now.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 15, E'For the LORD shall smite Israel, as a reed is shaken in the water, and he shall root up Israel out of this good land, which he gave to their fathers, and shall scatter them beyond the river, because they have made their groves, provoking the LORD to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 16, E'And he shall give Israel up because of the sins of Jeroboam, who did sin, and who made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 17, E'And Jeroboamâ€™s wife arose, and departed, and came to Tirzah: and when she came to the threshold of the door, the child died;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 18, E'And they buried him; and all Israel mourned for him, according to the word of the LORD, which he spake by the hand of his servant Ahijah the prophet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 19, E'And the rest of the acts of Jeroboam, how he warred, and how he reigned, behold, they are written in the book of the chronicles of the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 20, E'And the days which Jeroboam reigned were two and twenty years: and he slept with his fathers, and Nadab his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 21, E'And Rehoboam the son of Solomon reigned in Judah. Rehoboam was forty and one years old when he began to reign, and he reigned seventeen years in Jerusalem, the city which the LORD did choose out of all the tribes of Israel, to put his name there. And his motherâ€™s name was Naamah an Ammonitess.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 22, E'And Judah did evil in the sight of the LORD, and they provoked him to jealousy with their sins which they had committed, above all that their fathers had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 23, E'For they also built them high places, and images, and groves, on every high hill, and under every green tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 24, E'And there were also sodomites in the land: and they did according to all the abominations of the nations which the LORD cast out before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 25, E'And it came to pass in the fifth year of king Rehoboam, that Shishak king of Egypt came up against Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 26, E'And he took away the treasures of the house of the LORD, and the treasures of the kingâ€™s house; he even took away all: and he took away all the shields of gold which Solomon had made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 27, E'And king Rehoboam made in their stead brasen shields, and committed them unto the hands of the chief of the guard, which kept the door of the kingâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 28, E'And it was so, when the king went into the house of the LORD, that the guard bare them, and brought them back into the guard chamber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 29, E'Now the rest of the acts of Rehoboam, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 30, E'And there was war between Rehoboam and Jeroboam all their days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 14, 31, E'And Rehoboam slept with his fathers, and was buried with his fathers in the city of David. And his motherâ€™s name was Naamah an Ammonitess. And Abijam his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 1, E'Now in the eighteenth year of king Jeroboam the son of Nebat reigned Abijam over Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 2, E'Three years reigned he in Jerusalem. And his motherâ€™s name was Maachah, the daughter of Abishalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 3, E'And he walked in all the sins of his father, which he had done before him: and his heart was not perfect with the LORD his God, as the heart of David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 4, E'Nevertheless for Davidâ€™s sake did the LORD his God give him a lamp in Jerusalem, to set up his son after him, and to establish Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 5, E'Because David did that which was right in the eyes of the LORD, and turned not aside from any thing that he commanded him all the days of his life, save only in the matter of Uriah the Hittite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 6, E'And there was war between Rehoboam and Jeroboam all the days of his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 7, E'Now the rest of the acts of Abijam, and all that he did, are they not written in the book of the chronicles of the kings of Judah? And there was war between Abijam and Jeroboam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 8, E'And Abijam slept with his fathers; and they buried him in the city of David: and Asa his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 9, E'And in the twentieth year of Jeroboam king of Israel reigned Asa over Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 10, E'And forty and one years reigned he in Jerusalem. And his motherâ€™s name was Maachah, the daughter of Abishalom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 11, E'And Asa did that which was right in the eyes of the LORD, as did David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 12, E'And he took away the sodomites out of the land, and removed all the idols that his fathers had made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 13, E'And also Maachah his mother, even her he removed from being queen, because she had made an idol in a grove; and Asa destroyed her idol, and burnt it by the brook Kidron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 14, E'But the high places were not removed: nevertheless Asaâ€™s heart was perfect with the LORD all his days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 15, E'And he brought in the things which his father had dedicated, and the things which himself had dedicated, into the house of the LORD, silver, and gold, and vessels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 16, E'And there was war between Asa and Baasha king of Israel all their days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 17, E'And Baasha king of Israel went up against Judah, and built Ramah, that he might not suffer any to go out or come in to Asa king of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 18, E'Then Asa took all the silver and the gold that were left in the treasures of the house of the LORD, and the treasures of the kingâ€™s house, and delivered them into the hand of his servants: and king Asa sent them to Benhadad, the son of Tabrimon, the son of Hezion, king of Syria, that dwelt at Damascus, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 19, E'There is a league between me and thee, and between my father and thy father: behold, I have sent unto thee a present of silver and gold; come and break thy league with Baasha king of Israel, that he may depart from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 20, E'So Benhadad hearkened unto king Asa, and sent the captains of the hosts which he had against the cities of Israel, and smote Ijon, and Dan, and Abelbethmaachah, and all Cinneroth, with all the land of Naphtali.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 21, E'And it came to pass, when Baasha heard thereof, that he left off building of Ramah, and dwelt in Tirzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 22, E'Then king Asa made a proclamation throughout all Judah; none was exempted: and they took away the stones of Ramah, and the timber thereof, wherewith Baasha had builded; and king Asa built with them Geba of Benjamin, and Mizpah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 23, E'The rest of all the acts of Asa, and all his might, and all that he did, and the cities which he built, are they not written in the book of the chronicles of the kings of Judah? Nevertheless in the time of his old age he was diseased in his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 24, E'And Asa slept with his fathers, and was buried with his fathers in the city of David his father: and Jehoshaphat his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 25, E'And Nadab the son of Jeroboam began to reign over Israel in the second year of Asa king of Judah, and reigned over Israel two years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 26, E'And he did evil in the sight of the LORD, and walked in the way of his father, and in his sin wherewith he made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 27, E'And Baasha the son of Ahijah, of the house of Issachar, conspired against him; and Baasha smote him at Gibbethon, which belonged to the Philistines; for Nadab and all Israel laid siege to Gibbethon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 28, E'Even in the third year of Asa king of Judah did Baasha slay him, and reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 29, E'And it came to pass, when he reigned, that he smote all the house of Jeroboam; he left not to Jeroboam any that breathed, until he had destroyed him, according unto the saying of the LORD, which he spake by his servant Ahijah the Shilonite:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 30, E'Because of the sins of Jeroboam which he sinned, and which he made Israel sin, by his provocation wherewith he provoked the LORD God of Israel to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 31, E'Now the rest of the acts of Nadab, and all that he did, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 32, E'And there was war between Asa and Baasha king of Israel all their days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 33, E'In the third year of Asa king of Judah began Baasha the son of Ahijah to reign over all Israel in Tirzah, twenty and four years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 15, 34, E'And he did evil in the sight of the LORD, and walked in the way of Jeroboam, and in his sin wherewith he made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 1, E'Then the word of the LORD came to Jehu the son of Hanani against Baasha, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 2, E'Forasmuch as I exalted thee out of the dust, and made thee prince over my people Israel; and thou hast walked in the way of Jeroboam, and hast made my people Israel to sin, to provoke me to anger with their sins;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 3, E'Behold, I will take away the posterity of Baasha, and the posterity of his house; and will make thy house like the house of Jeroboam the son of Nebat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 4, E'Him that dieth of Baasha in the city shall the dogs eat; and him that dieth of his in the fields shall the fowls of the air eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 5, E'Now the rest of the acts of Baasha, and what he did, and his might, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 6, E'So Baasha slept with his fathers, and was buried in Tirzah: and Elah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 7, E'And also by the hand of the prophet Jehu the son of Hanani came the word of the LORD against Baasha, and against his house, even for all the evil that he did in the sight of the LORD, in provoking him to anger with the work of his hands, in being like the house of Jeroboam; and because he killed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 8, E'In the twenty and sixth year of Asa king of Judah began Elah the son of Baasha to reign over Israel in Tirzah, two years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 9, E'And his servant Zimri, captain of half his chariots, conspired against him, as he was in Tirzah, drinking himself drunk in the house of Arza steward of his house in Tirzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 10, E'And Zimri went in and smote him, and killed him, in the twenty and seventh year of Asa king of Judah, and reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 11, E'And it came to pass, when he began to reign, as soon as he sat on his throne, that he slew all the house of Baasha: he left him not one that pisseth against a wall, neither of his kinsfolks, nor of his friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 12, E'Thus did Zimri destroy all the house of Baasha, according to the word of the LORD, which he spake against Baasha by Jehu the prophet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 13, E'For all the sins of Baasha, and the sins of Elah his son, by which they sinned, and by which they made Israel to sin, in provoking the LORD God of Israel to anger with their vanities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 14, E'Now the rest of the acts of Elah, and all that he did, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 15, E'In the twenty and seventh year of Asa king of Judah did Zimri reign seven days in Tirzah. And the people were encamped against Gibbethon, which belonged to the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 16, E'And the people that were encamped heard say, Zimri hath conspired, and hath also slain the king: wherefore all Israel made Omri, the captain of the host, king over Israel that day in the camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 17, E'And Omri went up from Gibbethon, and all Israel with him, and they besieged Tirzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 18, E'And it came to pass, when Zimri saw that the city was taken, that he went into the palace of the kingâ€™s house, and burnt the kingâ€™s house over him with fire, and died,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 19, E'For his sins which he sinned in doing evil in the sight of the LORD, in walking in the way of Jeroboam, and in his sin which he did, to make Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 20, E'Now the rest of the acts of Zimri, and his treason that he wrought, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 21, E'Then were the people of Israel divided into two parts: half of the people followed Tibni the son of Ginath, to make him king; and half followed Omri.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 22, E'But the people that followed Omri prevailed against the people that followed Tibni the son of Ginath: so Tibni died, and Omri reigned.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 23, E'In the thirty and first year of Asa king of Judah began Omri to reign over Israel, twelve years: six years reigned he in Tirzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 24, E'And he bought the hill Samaria of Shemer for two talents of silver, and built on the hill, and called the name of the city which he built, after the name of Shemer, owner of the hill, Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 25, E'But Omri wrought evil in the eyes of the LORD, and did worse than all that were before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 26, E'For he walked in all the way of Jeroboam the son of Nebat, and in his sin wherewith he made Israel to sin, to provoke the LORD God of Israel to anger with their vanities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 27, E'Now the rest of the acts of Omri which he did, and his might that he shewed, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 28, E'So Omri slept with his fathers, and was buried in Samaria: and Ahab his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 29, E'And in the thirty and eighth year of Asa king of Judah began Ahab the son of Omri to reign over Israel: and Ahab the son of Omri reigned over Israel in Samaria twenty and two years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 30, E'And Ahab the son of Omri did evil in the sight of the LORD above all that were before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 31, E'And it came to pass, as if it had been a light thing for him to walk in the sins of Jeroboam the son of Nebat, that he took to wife Jezebel the daughter of Ethbaal king of the Zidonians, and went and served Baal, and worshipped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 32, E'And he reared up an altar for Baal in the house of Baal, which he had built in Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 33, E'And Ahab made a grove; and Ahab did more to provoke the LORD God of Israel to anger than all the kings of Israel that were before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 16, 34, E'In his days did Hiel the Bethelite build Jericho: he laid the foundation thereof in Abiram his firstborn, and set up the gates thereof in his youngest son Segub, according to the word of the LORD, which he spake by Joshua the son of Nun.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 1, E'And Elijah the Tishbite, who was of the inhabitants of Gilead, said unto Ahab, As the LORD God of Israel liveth, before whom I stand, there shall not be dew nor rain these years, but according to my word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 2, E'And the word of the LORD came unto him, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 3, E'Get thee hence, and turn thee eastward, and hide thyself by the brook Cherith, that is before Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 4, E'And it shall be, that thou shalt drink of the brook; and I have commanded the ravens to feed thee there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 5, E'So he went and did according unto the word of the LORD: for he went and dwelt by the brook Cherith, that is before Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 6, E'And the ravens brought him bread and flesh in the morning, and bread and flesh in the evening; and he drank of the brook.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 7, E'And it came to pass after a while, that the brook dried up, because there had been no rain in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 8, E'And the word of the LORD came unto him, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 9, E'Arise, get thee to Zarephath, which belongeth to Zidon, and dwell there: behold, I have commanded a widow woman there to sustain thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 10, E'So he arose and went to Zarephath. And when he came to the gate of the city, behold, the widow woman was there gathering of sticks: and he called to her, and said, Fetch me, I pray thee, a little water in a vessel, that I may drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 11, E'And as she was going to fetch it, he called to her, and said, Bring me, I pray thee, a morsel of bread in thine hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 12, E'And she said, As the LORD thy God liveth, I have not a cake, but an handful of meal in a barrel, and a little oil in a cruse: and, behold, I am gathering two sticks, that I may go in and dress it for me and my son, that we may eat it, and die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 13, E'And Elijah said unto her, Fear not; go and do as thou hast said: but make me thereof a little cake first, and bring it unto me, and after make for thee and for thy son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 14, E'For thus saith the LORD God of Israel, The barrel of meal shall not waste, neither shall the cruse of oil fail, until the day that the LORD sendeth rain upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 15, E'And she went and did according to the saying of Elijah: and she, and he, and her house, did eat many days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 16, E'And the barrel of meal wasted not, neither did the cruse of oil fail, according to the word of the LORD, which he spake by Elijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 17, E'And it came to pass after these things, that the son of the woman, the mistress of the house, fell sick; and his sickness was so sore, that there was no breath left in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 18, E'And she said unto Elijah, What have I to do with thee, O thou man of God? art thou come unto me to call my sin to remembrance, and to slay my son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 19, E'And he said unto her, Give me thy son. And he took him out of her bosom, and carried him up into a loft, where he abode, and laid him upon his own bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 20, E'And he cried unto the LORD, and said, O LORD my God, hast thou also brought evil upon the widow with whom I sojourn, by slaying her son?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 21, E'And he stretched himself upon the child three times, and cried unto the LORD, and said, O LORD my God, I pray thee, let this childâ€™s soul come into him again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 22, E'And the LORD heard the voice of Elijah; and the soul of the child came into him again, and he revived.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 23, E'And Elijah took the child, and brought him down out of the chamber into the house, and delivered him unto his mother: and Elijah said, See, thy son liveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 17, 24, E'And the woman said to Elijah, Now by this I know that thou art a man of God, and that the word of the LORD in thy mouth is truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 1, E'And it came to pass after many days, that the word of the LORD came to Elijah in the third year, saying, Go, shew thyself unto Ahab; and I will send rain upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 2, E'And Elijah went to shew himself unto Ahab. And there was a sore famine in Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 3, E'And Ahab called Obadiah, which was the governor of his house. (Now Obadiah feared the LORD greatly:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 4, E'For it was so, when Jezebel cut off the prophets of the LORD, that Obadiah took an hundred prophets, and hid them by fifty in a cave, and fed them with bread and water.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 5, E'And Ahab said unto Obadiah, Go into the land, unto all fountains of water, and unto all brooks: peradventure we may find grass to save the horses and mules alive, that we lose not all the beasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 6, E'So they divided the land between them to pass throughout it: Ahab went one way by himself, and Obadiah went another way by himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 7, E'And as Obadiah was in the way, behold, Elijah met him: and he knew him, and fell on his face, and said, Art thou that my lord Elijah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 8, E'And he answered him, I am: go, tell thy lord, Behold, Elijah is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 9, E'And he said, What have I sinned, that thou wouldest deliver thy servant into the hand of Ahab, to slay me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 10, E'As the LORD thy God liveth, there is no nation or kingdom, whither my lord hath not sent to seek thee: and when they said, He is not there; he took an oath of the kingdom and nation, that they found thee not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 11, E'And now thou sayest, Go, tell thy lord, Behold, Elijah is here.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 12, E'And it shall come to pass, as soon as I am gone from thee, that the Spirit of the LORD shall carry thee whither I know not; and so when I come and tell Ahab, and he cannot find thee, he shall slay me: but I thy servant fear the LORD from my youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 13, E'Was it not told my lord what I did when Jezebel slew the prophets of the LORD, how I hid an hundred men of the LORDâ€™s prophets by fifty in a cave, and fed them with bread and water?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 14, E'And now thou sayest, Go, tell thy lord, Behold, Elijah is here: and he shall slay me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 15, E'And Elijah said, As the LORD of hosts liveth, before whom I stand, I will surely shew myself unto him to day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 16, E'So Obadiah went to meet Ahab, and told him: and Ahab went to meet Elijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 17, E'And it came to pass, when Ahab saw Elijah, that Ahab said unto him, Art thou he that troubleth Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 18, E'And he answered, I have not troubled Israel; but thou, and thy fatherâ€™s house, in that ye have forsaken the commandments of the LORD, and thou hast followed Baalim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 19, E'Now therefore send, and gather to me all Israel unto mount Carmel, and the prophets of Baal four hundred and fifty, and the prophets of the groves four hundred, which eat at Jezebelâ€™s table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 20, E'So Ahab sent unto all the children of Israel, and gathered the prophets together unto mount Carmel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 21, E'And Elijah came unto all the people, and said, How long halt ye between two opinions? if the LORD be God, follow him: but if Baal, then follow him. And the people answered him not a word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 22, E'Then said Elijah unto the people, I, even I only, remain a prophet of the LORD; but Baalâ€™s prophets are four hundred and fifty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 23, E'Let them therefore give us two bullocks; and let them choose one bullock for themselves, and cut it in pieces, and lay it on wood, and put no fire under: and I will dress the other bullock, and lay it on wood, and put no fire under:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 24, E'And call ye on the name of your gods, and I will call on the name of the LORD: and the God that answereth by fire, let him be God. And all the people answered and said, It is well spoken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 25, E'And Elijah said unto the prophets of Baal, Choose you one bullock for yourselves, and dress it first; for ye are many; and call on the name of your gods, but put no fire under.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 26, E'And they took the bullock which was given them, and they dressed it, and called on the name of Baal from morning even until noon, saying, O Baal, hear us. But there was no voice, nor any that answered. And they leaped upon the altar which was made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 27, E'And it came to pass at noon, that Elijah mocked them, and said, Cry aloud: for he is a god; either he is talking, or he is pursuing, or he is in a journey, or peradventure he sleepeth, and must be awaked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 28, E'And they cried aloud, and cut themselves after their manner with knives and lancets, till the blood gushed out upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 29, E'And it came to pass, when midday was past, and they prophesied until the time of the offering of the evening sacrifice, that there was neither voice, nor any to answer, nor any that regarded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 30, E'And Elijah said unto all the people, Come near unto me. And all the people came near unto him. And he repaired the altar of the LORD that was broken down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 31, E'And Elijah took twelve stones, according to the number of the tribes of the sons of Jacob, unto whom the word of the LORD came, saying, Israel shall be thy name:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 32, E'And with the stones he built an altar in the name of the LORD: and he made a trench about the altar, as great as would contain two measures of seed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 33, E'And he put the wood in order, and cut the bullock in pieces, and laid him on the wood, and said, Fill four barrels with water, and pour it on the burnt sacrifice, and on the wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 34, E'And he said, Do it the second time. And they did it the second time. And he said, Do it the third time. And they did it the third time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 35, E'And the water ran round about the altar; and he filled the trench also with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 36, E'And it came to pass at the time of the offering of the evening sacrifice, that Elijah the prophet came near, and said, LORD God of Abraham, Isaac, and of Israel, let it be known this day that thou art God in Israel, and that I am thy servant, and that I have done all these things at thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 37, E'Hear me, O LORD, hear me, that this people may know that thou art the LORD God, and that thou hast turned their heart back again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 38, E'Then the fire of the LORD fell, and consumed the burnt sacrifice, and the wood, and the stones, and the dust, and licked up the water that was in the trench.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 39, E'And when all the people saw it, they fell on their faces: and they said, The LORD, he is the God; the LORD, he is the God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 40, E'And Elijah said unto them, Take the prophets of Baal; let not one of them escape. And they took them: and Elijah brought them down to the brook Kishon, and slew them there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 41, E'And Elijah said unto Ahab, Get thee up, eat and drink; for there is a sound of abundance of rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 42, E'So Ahab went up to eat and to drink. And Elijah went up to the top of Carmel; and he cast himself down upon the earth, and put his face between his knees,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 43, E'And said to his servant, Go up now, look toward the sea. And he went up, and looked, and said, There is nothing. And he said, Go again seven times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 44, E'And it came to pass at the seventh time, that he said, Behold, there ariseth a little cloud out of the sea, like a manâ€™s hand. And he said, Go up, say unto Ahab, Prepare thy chariot, and get thee down, that the rain stop thee not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 45, E'And it came to pass in the mean while, that the heaven was black with clouds and wind, and there was a great rain. And Ahab rode, and went to Jezreel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 18, 46, E'And the hand of the LORD was on Elijah; and he girded up his loins, and ran before Ahab to the entrance of Jezreel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 1, E'And Ahab told Jezebel all that Elijah had done, and withal how he had slain all the prophets with the sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 2, E'Then Jezebel sent a messenger unto Elijah, saying, So let the gods do to me, and more also, if I make not thy life as the life of one of them by to morrow about this time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 3, E'And when he saw that, he arose, and went for his life, and came to Beersheba, which belongeth to Judah, and left his servant there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 4, E'But he himself went a dayâ€™s journey into the wilderness, and came and sat down under a juniper tree: and he requested for himself that he might die; and said, It is enough; now, O LORD, take away my life; for I am not better than my fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 5, E'And as he lay and slept under a juniper tree, behold, then an angel touched him, and said unto him, Arise and eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 6, E'And he looked, and, behold, there was a cake baken on the coals, and a cruse of water at his head. And he did eat and drink, and laid him down again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 7, E'And the angel of the LORD came again the second time, and touched him, and said, Arise and eat; because the journey is too great for thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 8, E'And he arose, and did eat and drink, and went in the strength of that meat forty days and forty nights unto Horeb the mount of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 9, E'And he came thither unto a cave, and lodged there; and, behold, the word of the LORD came to him, and he said unto him, What doest thou here, Elijah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 10, E'And he said, I have been very jealous for the LORD God of hosts: for the children of Israel have forsaken thy covenant, thrown down thine altars, and slain thy prophets with the sword; and I, even I only, am left; and they seek my life, to take it away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 11, E'And he said, Go forth, and stand upon the mount before the LORD. And, behold, the LORD passed by, and a great and strong wind rent the mountains, and brake in pieces the rocks before the LORD; but the LORD was not in the wind: and after the wind an earthquake; but the LORD was not in the earthquake:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 12, E'And after the earthquake a fire; but the LORD was not in the fire: and after the fire a still small voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 13, E'And it was so, when Elijah heard it, that he wrapped his face in his mantle, and went out, and stood in the entering in of the cave. And, behold, there came a voice unto him, and said, What doest thou here, Elijah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 14, E'And he said, I have been very jealous for the LORD God of hosts: because the children of Israel have forsaken thy covenant, thrown down thine altars, and slain thy prophets with the sword; and I, even I only, am left; and they seek my life, to take it away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 15, E'And the LORD said unto him, Go, return on thy way to the wilderness of Damascus: and when thou comest, anoint Hazael to be king over Syria:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 16, E'And Jehu the son of Nimshi shalt thou anoint to be king over Israel: and Elisha the son of Shaphat of Abelmeholah shalt thou anoint to be prophet in thy room.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 17, E'And it shall come to pass, that him that escapeth the sword of Hazael shall Jehu slay: and him that escapeth from the sword of Jehu shall Elisha slay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 18, E'Yet I have left me seven thousand in Israel, all the knees which have not bowed unto Baal, and every mouth which hath not kissed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 19, E'So he departed thence, and found Elisha the son of Shaphat, who was plowing with twelve yoke of oxen before him, and he with the twelfth: and Elijah passed by him, and cast his mantle upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 20, E'And he left the oxen, and ran after Elijah, and said, Let me, I pray thee, kiss my father and my mother, and then I will follow thee. And he said unto him, Go back again: for what have I done to thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 19, 21, E'And he returned back from him, and took a yoke of oxen, and slew them, and boiled their flesh with the instruments of the oxen, and gave unto the people, and they did eat. Then he arose, and went after Elijah, and ministered unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 1, E'And Benhadad the king of Syria gathered all his host together: and there were thirty and two kings with him, and horses, and chariots; and he went up and besieged Samaria, and warred against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 2, E'And he sent messengers to Ahab king of Israel into the city, and said unto him, Thus saith Benhadad,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 3, E'Thy silver and thy gold is mine; thy wives also and thy children, even the goodliest, are mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 4, E'And the king of Israel answered and said, My lord, O king, according to thy saying, I am thine, and all that I have.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 5, E'And the messengers came again, and said, Thus speaketh Benhadad, saying, Although I have sent unto thee, saying, Thou shalt deliver me thy silver, and thy gold, and thy wives, and thy children;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 6, E'Yet I will send my servants unto thee to morrow about this time, and they shall search thine house, and the houses of thy servants; and it shall be, that whatsoever is pleasant in thine eyes, they shall put it in their hand, and take it away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 7, E'Then the king of Israel called all the elders of the land, and said, Mark, I pray you, and see how this man seeketh mischief: for he sent unto me for my wives, and for my children, and for my silver, and for my gold; and I denied him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 8, E'And all the elders and all the people said unto him, Hearken not unto him, nor consent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 9, E'Wherefore he said unto the messengers of Benhadad, Tell my lord the king, All that thou didst send for to thy servant at the first I will do: but this thing I may not do. And the messengers departed, and brought him word again.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 10, E'And Benhadad sent unto him, and said, The gods do so unto me, and more also, if the dust of Samaria shall suffice for handfuls for all the people that follow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 11, E'And the king of Israel answered and said, Tell him, Let not him that girdeth on his harness boast himself as he that putteth it off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 12, E'And it came to pass, when Ben-hadad heard this message, as he was drinking, he and the kings in the pavilions, that he said unto his servants, Set yourselves in array. And they set themselves in array against the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 13, E'And, behold, there came a prophet unto Ahab king of Israel, saying, Thus saith the LORD, Hast thou seen all this great multitude? behold, I will deliver it into thine hand this day; and thou shalt know that I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 14, E'And Ahab said, By whom? And he said, Thus saith the LORD, Even by the young men of the princes of the provinces. Then he said, Who shall order the battle? And he answered, Thou.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 15, E'Then he numbered the young men of the princes of the provinces, and they were two hundred and thirty two: and after them he numbered all the people, even all the children of Israel, being seven thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 16, E'And they went out at noon. But Benhadad was drinking himself drunk in the pavilions, he and the kings, the thirty and two kings that helped him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 17, E'And the young men of the princes of the provinces went out first; and Benhadad sent out, and they told him, saying, There are men come out of Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 18, E'And he said, Whether they be come out for peace, take them alive; or whether they be come out for war, take them alive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 19, E'So these young men of the princes of the provinces came out of the city, and the army which followed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 20, E'And they slew every one his man: and the Syrians fled; and Israel pursued them: and Benhadad the king of Syria escaped on an horse with the horsemen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 21, E'And the king of Israel went out, and smote the horses and chariots, and slew the Syrians with a great slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 22, E'And the prophet came to the king of Israel, and said unto him, Go, strengthen thyself, and mark, and see what thou doest: for at the return of the year the king of Syria will come up against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 23, E'And the servants of the king of Syria said unto him, Their gods are gods of the hills; therefore they were stronger than we; but let us fight against them in the plain, and surely we shall be stronger than they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 24, E'And do this thing, Take the kings away, every man out of his place, and put captains in their rooms:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 25, E'And number thee an army, like the army that thou hast lost, horse for horse, and chariot for chariot: and we will fight against them in the plain, and surely we shall be stronger than they. And he hearkened unto their voice, and did so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 26, E'And it came to pass at the return of the year, that Benhadad numbered the Syrians, and went up to Aphek, to fight against Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 27, E'And the children of Israel were numbered, and were all present, and went against them: and the children of Israel pitched before them like two little flocks of kids; but the Syrians filled the country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 28, E'And there came a man of God, and spake unto the king of Israel, and said, Thus saith the LORD, Because the Syrians have said, The LORD is God of the hills, but he is not God of the valleys, therefore will I deliver all this great multitude into thine hand, and ye shall know that I am the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 29, E'And they pitched one over against the other seven days. And so it was, that in the seventh day the battle was joined: and the children of Israel slew of the Syrians an hundred thousand footmen in one day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 30, E'But the rest fled to Aphek, into the city; and there a wall fell upon twenty and seven thousand of the men that were left. And Benhadad fled, and came into the city, into an inner chamber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 31, E'And his servants said unto him, Behold now, we have heard that the kings of the house of Israel are merciful kings: let us, I pray thee, put sackcloth on our loins, and ropes upon our heads, and go out to the king of Israel: peradventure he will save thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 32, E'So they girded sackcloth on their loins, and put ropes on their heads, and came to the king of Israel, and said, Thy servant Benhadad saith, I pray thee, let me live. And he said, Is he yet alive? he is my brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 33, E'Now the men did diligently observe whether any thing would come from him, and did hastily catch it: and they said, Thy brother Benhadad. Then he said, Go ye, bring him. Then Benhadad came forth to him; and he caused him to come up into the chariot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 34, E'And Ben-hadad said unto him, The cities, which my father took from thy father, I will restore; and thou shalt make streets for thee in Damascus, as my father made in Samaria. Then said Ahab, I will send thee away with this covenant. So he made a covenant with him, and sent him away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 35, E'And a certain man of the sons of the prophets said unto his neighbour in the word of the LORD, Smite me, I pray thee. And the man refused to smite him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 36, E'Then said he unto him, Because thou hast not obeyed the voice of the LORD, behold, as soon as thou art departed from me, a lion shall slay thee. And as soon as he was departed from him, a lion found him, and slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 37, E'Then he found another man, and said, Smite me, I pray thee. And the man smote him, so that in smiting he wounded him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 38, E'So the prophet departed, and waited for the king by the way, and disguised himself with ashes upon his face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 39, E'And as the king passed by, he cried unto the king: and he said, Thy servant went out into the midst of the battle; and, behold, a man turned aside, and brought a man unto me, and said, Keep this man: if by any means he be missing, then shall thy life be for his life, or else thou shalt pay a talent of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 40, E'And as thy servant was busy here and there, he was gone. And the king of Israel said unto him, So shall thy judgment be; thyself hast decided it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 41, E'And he hasted, and took the ashes away from his face; and the king of Israel discerned him that he was of the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 42, E'And he said unto him, Thus saith the LORD, Because thou hast let go out of thy hand a man whom I appointed to utter destruction, therefore thy life shall go for his life, and thy people for his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 20, 43, E'And the king of Israel went to his house heavy and displeased, and came to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 1, E'And it came to pass after these things, that Naboth the Jezreelite had a vineyard, which was in Jezreel, hard by the palace of Ahab king of Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 2, E'And Ahab spake unto Naboth, saying, Give me thy vineyard, that I may have it for a garden of herbs, because it is near unto my house: and I will give thee for it a better vineyard than it; or, if it seem good to thee, I will give thee the worth of it in money.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 3, E'And Naboth said to Ahab, The LORD forbid it me, that I should give the inheritance of my fathers unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 4, E'And Ahab came into his house heavy and displeased because of the word which Naboth the Jezreelite had spoken to him: for he had said, I will not give thee the inheritance of my fathers. And he laid him down upon his bed, and turned away his face, and would eat no bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 5, E'But Jezebel his wife came to him, and said unto him, Why is thy spirit so sad, that thou eatest no bread?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 6, E'And he said unto her, Because I spake unto Naboth the Jezreelite, and said unto him, Give me thy vineyard for money; or else, if it please thee, I will give thee another vineyard for it: and he answered, I will not give thee my vineyard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 7, E'And Jezebel his wife said unto him, Dost thou now govern the kingdom of Israel? arise, and eat bread, and let thine heart be merry: I will give thee the vineyard of Naboth the Jezreelite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 8, E'So she wrote letters in Ahabâ€™s name, and sealed them with his seal, and sent the letters unto the elders and to the nobles that were in his city, dwelling with Naboth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 9, E'And she wrote in the letters, saying, Proclaim a fast, and set Naboth on high among the people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 10, E'And set two men, sons of Belial, before him, to bear witness against him, saying, Thou didst blaspheme God and the king. And then carry him out, and stone him, that he may die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 11, E'And the men of his city, even the elders and the nobles who were the inhabitants in his city, did as Jezebel had sent unto them, and as it was written in the letters which she had sent unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 12, E'They proclaimed a fast, and set Naboth on high among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 13, E'And there came in two men, children of Belial, and sat before him: and the men of Belial witnessed against him, even against Naboth, in the presence of the people, saying, Naboth did blaspheme God and the king. Then they carried him forth out of the city, and stoned him with stones, that he died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 14, E'Then they sent to Jezebel, saying, Naboth is stoned, and is dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 15, E'And it came to pass, when Jezebel heard that Naboth was stoned, and was dead, that Jezebel said to Ahab, Arise, take possession of the vineyard of Naboth the Jezreelite, which he refused to give thee for money: for Naboth is not alive, but dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 16, E'And it came to pass, when Ahab heard that Naboth was dead, that Ahab rose up to go down to the vineyard of Naboth the Jezreelite, to take possession of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 17, E'And the word of the LORD came to Elijah the Tishbite, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 18, E'Arise, go down to meet Ahab king of Israel, which is in Samaria: behold, he is in the vineyard of Naboth, whither he is gone down to possess it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 19, E'And thou shalt speak unto him, saying, Thus saith the LORD, Hast thou killed, and also taken possession? And thou shalt speak unto him, saying, Thus saith the LORD, In the place where dogs licked the blood of Naboth shall dogs lick thy blood, even thine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 20, E'And Ahab said to Elijah, Hast thou found me, O mine enemy? And he answered, I have found thee: because thou hast sold thyself to work evil in the sight of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 21, E'Behold, I will bring evil upon thee, and will take away thy posterity, and will cut off from Ahab him that pisseth against the wall, and him that is shut up and left in Israel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 22, E'And will make thine house like the house of Jeroboam the son of Nebat, and like the house of Baasha the son of Ahijah, for the provocation wherewith thou hast provoked me to anger, and made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 23, E'And of Jezebel also spake the LORD, saying, The dogs shall eat Jezebel by the wall of Jezreel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 24, E'Him that dieth of Ahab in the city the dogs shall eat; and him that dieth in the field shall the fowls of the air eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 25, E'But there was none like unto Ahab, which did sell himself to work wickedness in the sight of the LORD, whom Jezebel his wife stirred up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 26, E'And he did very abominably in following idols, according to all things as did the Amorites, whom the LORD cast out before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 27, E'And it came to pass, when Ahab heard those words, that he rent his clothes, and put sackcloth upon his flesh, and fasted, and lay in sackcloth, and went softly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 28, E'And the word of the LORD came to Elijah the Tishbite, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 21, 29, E'Seest thou how Ahab humbleth himself before me? because he humbleth himself before me, I will not bring the evil in his days: but in his sonâ€™s days will I bring the evil upon his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 1, E'And they continued three years without war between Syria and Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 2, E'And it came to pass in the third year, that Jehoshaphat the king of Judah came down to the king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 3, E'And the king of Israel said unto his servants, Know ye that Ramoth in Gilead is ours, and we be still, and take it not out of the hand of the king of Syria?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 4, E'And he said unto Jehoshaphat, Wilt thou go with me to battle to Ramothgilead? And Jehoshaphat said to the king of Israel, I am as thou art, my people as thy people, my horses as thy horses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 5, E'And Jehoshaphat said unto the king of Israel, Enquire, I pray thee, at the word of the LORD to day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 6, E'Then the king of Israel gathered the prophets together, about four hundred men, and said unto them, Shall I go against Ramothgilead to battle, or shall I forbear? And they said, Go up; for the LORD shall deliver it into the hand of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 7, E'And Jehoshaphat said, Is there not here a prophet of the LORD besides, that we might enquire of him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 8, E'And the king of Israel said unto Jehoshaphat, There is yet one man, Micaiah the son of Imlah, by whom we may enquire of the LORD: but I hate him; for he doth not prophesy good concerning me, but evil. And Jehoshaphat said, Let not the king say so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 9, E'Then the king of Israel called an officer, and said, Hasten hither Micaiah the son of Imlah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 10, E'And the king of Israel and Jehoshaphat the king of Judah sat each on his throne, having put on their robes, in a void place in the entrance of the gate of Samaria; and all the prophets prophesied before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 11, E'And Zedekiah the son of Chenaanah made him horns of iron: and he said, Thus saith the LORD, With these shalt thou push the Syrians, until thou have consumed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 12, E'And all the prophets prophesied so, saying, Go up to Ramothgilead, and prosper: for the LORD shall deliver it into the kingâ€™s hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 13, E'And the messenger that was gone to call Micaiah spake unto him, saying, Behold now, the words of the prophets declare good unto the king with one mouth: let thy word, I pray thee, be like the word of one of them, and speak that which is good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 14, E'And Micaiah said, As the LORD liveth, what the LORD saith unto me, that will I speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 15, E'So he came to the king. And the king said unto him, Micaiah, shall we go against Ramothgilead to battle, or shall we forbear? And he answered him, Go, and prosper: for the LORD shall deliver it into the hand of the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 16, E'And the king said unto him, How many times shall I adjure thee that thou tell me nothing but that which is true in the name of the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 17, E'And he said, I saw all Israel scattered upon the hills, as sheep that have not a shepherd: and the LORD said, These have no master: let them return every man to his house in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 18, E'And the king of Israel said unto Jehoshaphat, Did I not tell thee that he would prophesy no good concerning me, but evil?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 19, E'And he said, Hear thou therefore the word of the LORD: I saw the LORD sitting on his throne, and all the host of heaven standing by him on his right hand and on his left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 20, E'And the LORD said, Who shall persuade Ahab, that he may go up and fall at Ramothgilead? And one said on this manner, and another said on that manner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 21, E'And there came forth a spirit, and stood before the LORD, and said, I will persuade him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 22, E'And the LORD said unto him, Wherewith? And he said, I will go forth, and I will be a lying spirit in the mouth of all his prophets. And he said, Thou shalt persuade him, and prevail also: go forth, and do so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 23, E'Now therefore, behold, the LORD hath put a lying spirit in the mouth of all these thy prophets, and the LORD hath spoken evil concerning thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 24, E'But Zedekiah the son of Chenaanah went near, and smote Micaiah on the cheek, and said, Which way went the Spirit of the LORD from me to speak unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 25, E'And Micaiah said, Behold, thou shalt see in that day, when thou shalt go into an inner chamber to hide thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 26, E'And the king of Israel said, Take Micaiah, and carry him back unto Amon the governor of the city, and to Joash the kingâ€™s son;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 27, E'And say, Thus saith the king, Put this fellow in the prison, and feed him with bread of affliction and with water of affliction, until I come in peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 28, E'And Micaiah said, If thou return at all in peace, the LORD hath not spoken by me. And he said, Hearken, O people, every one of you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 29, E'So the king of Israel and Jehoshaphat the king of Judah went up to Ramothgilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 30, E'And the king of Israel said unto Jehoshaphat, I will disguise myself, and enter into the battle; but put thou on thy robes. And the king of Israel disguised himself, and went into the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 31, E'But the king of Syria commanded his thirty and two captains that had rule over his chariots, saying, Fight neither with small nor great, save only with the king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 32, E'And it came to pass, when the captains of the chariots saw Jehoshaphat, that they said, Surely it is the king of Israel. And they turned aside to fight against him: and Jehoshaphat cried out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 33, E'And it came to pass, when the captains of the chariots perceived that it was not the king of Israel, that they turned back from pursuing him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 34, E'And a certain man drew a bow at a venture, and smote the king of Israel between the joints of the harness: wherefore he said unto the driver of his chariot, Turn thine hand, and carry me out of the host; for I am wounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 35, E'And the battle increased that day: and the king was stayed up in his chariot against the Syrians, and died at even: and the blood ran out of the wound into the midst of the chariot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 36, E'And there went a proclamation throughout the host about the going down of the sun, saying, Every man to his city, and every man to his own country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 37, E'So the king died, and was brought to Samaria; and they buried the king in Samaria.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 38, E'And one washed the chariot in the pool of Samaria; and the dogs licked up his blood; and they washed his armour; according unto the word of the LORD which he spake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 39, E'Now the rest of the acts of Ahab, and all that he did, and the ivory house which he made, and all the cities that he built, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 40, E'So Ahab slept with his fathers; and Ahaziah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 41, E'And Jehoshaphat the son of Asa began to reign over Judah in the fourth year of Ahab king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 42, E'Jehoshaphat was thirty and five years old when he began to reign; and he reigned twenty and five years in Jerusalem. And his motherâ€™s name was Azubah the daughter of Shilhi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 43, E'And he walked in all the ways of Asa his father; he turned not aside from it, doing that which was right in the eyes of the LORD: nevertheless the high places were not taken away; for the people offered and burnt incense yet in the high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 44, E'And Jehoshaphat made peace with the king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 45, E'Now the rest of the acts of Jehoshaphat, and his might that he shewed, and how he warred, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 46, E'And the remnant of the sodomites, which remained in the days of his father Asa, he took out of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 47, E'There was then no king in Edom: a deputy was king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 48, E'Jehoshaphat made ships of Tharshish to go to Ophir for gold: but they went not; for the ships were broken at Eziongeber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 49, E'Then said Ahaziah the son of Ahab unto Jehoshaphat, Let my servants go with thy servants in the ships. But Jehoshaphat would not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 50, E'And Jehoshaphat slept with his fathers, and was buried with his fathers in the city of David his father: and Jehoram his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 51, E'Ahaziah the son of Ahab began to reign over Israel in Samaria the seventeenth year of Jehoshaphat king of Judah, and reigned two years over Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 52, E'And he did evil in the sight of the LORD, and walked in the way of his father, and in the way of his mother, and in the way of Jeroboam the son of Nebat, who made Israel to sin:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4b39ef45-ac77-4ef2-b7ba-c7bcb35cc66c', 22, 53, E'For he served Baal, and worshipped him, and provoked to anger the LORD God of Israel, according to all that his father had done.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 1, E'Then Moab rebelled against Israel after the death of Ahab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 2, E'And Ahaziah fell down through a lattice in his upper chamber that was in Samaria, and was sick: and he sent messengers, and said unto them, Go, enquire of Baalzebub the god of Ekron whether I shall recover of this disease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 3, E'But the angel of the LORD said to Elijah the Tishbite, Arise, go up to meet the messengers of the king of Samaria, and say unto them, Is it not because there is not a God in Israel, that ye go to enquire of Baalzebub the god of Ekron?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 4, E'Now therefore thus saith the LORD, Thou shalt not come down from that bed on which thou art gone up, but shalt surely die. And Elijah departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 5, E'And when the messengers turned back unto him, he said unto them, Why are ye now turned back?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 6, E'And they said unto him, There came a man up to meet us, and said unto us, Go, turn again unto the king that sent you, and say unto him, Thus saith the LORD, Is it not because there is not a God in Israel, that thou sendest to enquire of Baalzebub the god of Ekron? therefore thou shalt not come down from that bed on which thou art gone up, but shalt surely die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 7, E'And he said unto them, What manner of man was he which came up to meet you, and told you these words?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 8, E'And they answered him, He was an hairy man, and girt with a girdle of leather about his loins. And he said, It is Elijah the Tishbite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 9, E'Then the king sent unto him a captain of fifty with his fifty. And he went up to him: and, behold, he sat on the top of an hill. And he spake unto him, Thou man of God, the king hath said, Come down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 10, E'And Elijah answered and said to the captain of fifty, If I be a man of God, then let fire come down from heaven, and consume thee and thy fifty. And there came down fire from heaven, and consumed him and his fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 11, E'Again also he sent unto him another captain of fifty with his fifty. And he answered and said unto him, O man of God, thus hath the king said, Come down quickly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 12, E'And Elijah answered and said unto them, If I be a man of God, let fire come down from heaven, and consume thee and thy fifty. And the fire of God came down from heaven, and consumed him and his fifty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 13, E'And he sent again a captain of the third fifty with his fifty. And the third captain of fifty went up, and came and fell on his knees before Elijah, and besought him, and said unto him, O man of God, I pray thee, let my life, and the life of these fifty thy servants, be precious in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 14, E'Behold, there came fire down from heaven, and burnt up the two captains of the former fifties with their fifties: therefore let my life now be precious in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 15, E'And the angel of the LORD said unto Elijah, Go down with him: be not afraid of him. And he arose, and went down with him unto the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 16, E'And he said unto him, Thus saith the LORD, Forasmuch as thou hast sent messengers to enquire of Baalzebub the god of Ekron, is it not because there is no God in Israel to enquire of his word? therefore thou shalt not come down off that bed on which thou art gone up, but shalt surely die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 17, E'So he died according to the word of the LORD which Elijah had spoken. And Jehoram reigned in his stead in the second year of Jehoram the son of Jehoshaphat king of Judah; because he had no son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 1, 18, E'Now the rest of the acts of Ahaziah which he did, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 1, E'And it came to pass, when the LORD would take up Elijah into heaven by a whirlwind, that Elijah went with Elisha from Gilgal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 2, E'And Elijah said unto Elisha, Tarry here, I pray thee; for the LORD hath sent me to Bethel. And Elisha said unto him, As the LORD liveth, and as thy soul liveth, I will not leave thee. So they went down to Bethel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 3, E'And the sons of the prophets that were at Bethel came forth to Elisha, and said unto him, Knowest thou that the LORD will take away thy master from thy head to day? And he said, Yea, I know it; hold ye your peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 4, E'And Elijah said unto him, Elisha, tarry here, I pray thee; for the LORD hath sent me to Jericho. And he said, As the LORD liveth, and as thy soul liveth, I will not leave thee. So they came to Jericho.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 5, E'And the sons of the prophets that were at Jericho came to Elisha, and said unto him, Knowest thou that the LORD will take away thy master from thy head to day? And he answered, Yea, I know it; hold ye your peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 6, E'And Elijah said unto him, Tarry, I pray thee, here; for the LORD hath sent me to Jordan. And he said, As the LORD liveth, and as thy soul liveth, I will not leave thee. And they two went on.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 7, E'And fifty men of the sons of the prophets went, and stood to view afar off: and they two stood by Jordan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 8, E'And Elijah took his mantle, and wrapped it together, and smote the waters, and they were divided hither and thither, so that they two went over on dry ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 9, E'And it came to pass, when they were gone over, that Elijah said unto Elisha, Ask what I shall do for thee, before I be taken away from thee. And Elisha said, I pray thee, let a double portion of thy spirit be upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 10, E'And he said, Thou hast asked a hard thing: nevertheless, if thou see me when I am taken from thee, it shall be so unto thee; but if not, it shall not be so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 11, E'And it came to pass, as they still went on, and talked, that, behold, there appeared a chariot of fire, and horses of fire, and parted them both asunder; and Elijah went up by a whirlwind into heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 12, E'And Elisha saw it, and he cried, My father, my father, the chariot of Israel, and the horsemen thereof. And he saw him no more: and he took hold of his own clothes, and rent them in two pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 13, E'He took up also the mantle of Elijah that fell from him, and went back, and stood by the bank of Jordan;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 14, E'And he took the mantle of Elijah that fell from him, and smote the waters, and said, Where is the LORD God of Elijah? and when he also had smitten the waters, they parted hither and thither: and Elisha went over.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 15, E'And when the sons of the prophets which were to view at Jericho saw him, they said, The spirit of Elijah doth rest on Elisha. And they came to meet him, and bowed themselves to the ground before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 16, E'And they said unto him, Behold now, there be with thy servants fifty strong men; let them go, we pray thee, and seek thy master: lest peradventure the Spirit of the LORD hath taken him up, and cast him upon some mountain, or into some valley. And he said, Ye shall not send.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 17, E'And when they urged him till he was ashamed, he said, Send. They sent therefore fifty men; and they sought three days, but found him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 18, E'And when they came again to him, (for he tarried at Jericho,) he said unto them, Did I not say unto you, Go not?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 19, E'And the men of the city said unto Elisha, Behold, I pray thee, the situation of this city is pleasant, as my lord seeth: but the water is naught, and the ground barren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 20, E'And he said, Bring me a new cruse, and put salt therein. And they brought it to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 21, E'And he went forth unto the spring of the waters, and cast the salt in there, and said, Thus saith the LORD, I have healed these waters; there shall not be from thence any more death or barren land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 22, E'So the waters were healed unto this day, according to the saying of Elisha which he spake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 23, E'And he went up from thence unto Bethel: and as he was going up by the way, there came forth little children out of the city, and mocked him, and said unto him, Go up, thou bald head; go up, thou bald head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 24, E'And he turned back, and looked on them, and cursed them in the name of the LORD. And there came forth two she bears out of the wood, and tare forty and two children of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 2, 25, E'And he went from thence to mount Carmel, and from thence he returned to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 1, E'Now Jehoram the son of Ahab began to reign over Israel in Samaria the eighteenth year of Jehoshaphat king of Judah, and reigned twelve years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 2, E'And he wrought evil in the sight of the LORD; but not like his father, and like his mother: for he put away the image of Baal that his father had made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 3, E'Nevertheless he cleaved unto the sins of Jeroboam the son of Nebat, which made Israel to sin; he departed not therefrom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 4, E'And Mesha king of Moab was a sheepmaster, and rendered unto the king of Israel an hundred thousand lambs, and an hundred thousand rams, with the wool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 5, E'But it came to pass, when Ahab was dead, that the king of Moab rebelled against the king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 6, E'And king Jehoram went out of Samaria the same time, and numbered all Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 7, E'And he went and sent to Jehoshaphat the king of Judah, saying, The king of Moab hath rebelled against me: wilt thou go with me against Moab to battle? And he said, I will go up: I am as thou art, my people as thy people, and my horses as thy horses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 8, E'And he said, Which way shall we go up? And he answered, The way through the wilderness of Edom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 9, E'So the king of Israel went, and the king of Judah, and the king of Edom: and they fetched a compass of seven daysâ€™ journey: and there was no water for the host, and for the cattle that followed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 10, E'And the king of Israel said, Alas! that the LORD hath called these three kings together, to deliver them into the hand of Moab!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 11, E'But Jehoshaphat said, Is there not here a prophet of the LORD, that we may enquire of the LORD by him? And one of the king of Israelâ€™s servants answered and said, Here is Elisha the son of Shaphat, which poured water on the hands of Elijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 12, E'And Jehoshaphat said, The word of the LORD is with him. So the king of Israel and Jehoshaphat and the king of Edom went down to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 13, E'And Elisha said unto the king of Israel, What have I to do with thee? get thee to the prophets of thy father, and to the prophets of thy mother. And the king of Israel said unto him, Nay: for the LORD hath called these three kings together, to deliver them into the hand of Moab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 14, E'And Elisha said, As the LORD of hosts liveth, before whom I stand, surely, were it not that I regard the presence of Jehoshaphat the king of Judah, I would not look toward thee, nor see thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 15, E'But now bring me a minstrel. And it came to pass, when the minstrel played, that the hand of the LORD came upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 16, E'And he said, Thus saith the LORD, Make this valley full of ditches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 17, E'For thus saith the LORD, Ye shall not see wind, neither shall ye see rain; yet that valley shall be filled with water, that ye may drink, both ye, and your cattle, and your beasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 18, E'And this is but a light thing in the sight of the LORD: he will deliver the Moabites also into your hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 19, E'And ye shall smite every fenced city, and every choice city, and shall fell every good tree, and stop all wells of water, and mar every good piece of land with stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 20, E'And it came to pass in the morning, when the meat offering was offered, that, behold, there came water by the way of Edom, and the country was filled with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 21, E'And when all the Moabites heard that the kings were come up to fight against them, they gathered all that were able to put on armour, and upward, and stood in the border.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 22, E'And they rose up early in the morning, and the sun shone upon the water, and the Moabites saw the water on the other side as red as blood:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 23, E'And they said, This is blood: the kings are surely slain, and they have smitten one another: now therefore, Moab, to the spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 24, E'And when they came to the camp of Israel, the Israelites rose up and smote the Moabites, so that they fled before them: but they went forward smiting the Moabites, even in their country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 25, E'And they beat down the cities, and on every good piece of land cast every man his stone, and filled it; and they stopped all the wells of water, and felled all the good trees: only in Kirharaseth left they the stones thereof; howbeit the slingers went about it, and smote it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 26, E'And when the king of Moab saw that the battle was too sore for him, he took with him seven hundred men that drew swords, to break through even unto the king of Edom: but they could not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 3, 27, E'Then he took his eldest son that should have reigned in his stead, and offered him for a burnt offering upon the wall. And there was great indignation against Israel: and they departed from him, and returned to their own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 1, E'Now there cried a certain woman of the wives of the sons of the prophets unto Elisha, saying, Thy servant my husband is dead; and thou knowest that thy servant did fear the LORD: and the creditor is come to take unto him my two sons to be bondmen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 2, E'And Elisha said unto her, What shall I do for thee? tell me, what hast thou in the house? And she said, Thine handmaid hath not any thing in the house, save a pot of oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 3, E'Then he said, Go, borrow thee vessels abroad of all thy neighbours, even empty vessels; borrow not a few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 4, E'And when thou art come in, thou shalt shut the door upon thee and upon thy sons, and shalt pour out into all those vessels, and thou shalt set aside that which is full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 5, E'So she went from him, and shut the door upon her and upon her sons, who brought the vessels to her; and she poured out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 6, E'And it came to pass, when the vessels were full, that she said unto her son, Bring me yet a vessel. And he said unto her, There is not a vessel more. And the oil stayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 7, E'Then she came and told the man of God. And he said, Go, sell the oil, and pay thy debt, and live thou and thy children of the rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 8, E'And it fell on a day, that Elisha passed to Shunem, where was a great woman; and she constrained him to eat bread. And so it was, that as oft as he passed by, he turned in thither to eat bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 9, E'And she said unto her husband, Behold now, I perceive that this is an holy man of God, which passeth by us continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 10, E'Let us make a little chamber, I pray thee, on the wall; and let us set for him there a bed, and a table, and a stool, and a candlestick: and it shall be, when he cometh to us, that he shall turn in thither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 11, E'And it fell on a day, that he came thither, and he turned into the chamber, and lay there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 12, E'And he said to Gehazi his servant, Call this Shunammite. And when he had called her, she stood before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 13, E'And he said unto him, Say now unto her, Behold, thou hast been careful for us with all this care; what is to be done for thee? wouldest thou be spoken for to the king, or to the captain of the host? And she answered, I dwell among mine own people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 14, E'And he said, What then is to be done for her? And Gehazi answered, Verily she hath no child, and her husband is old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 15, E'And he said, Call her. And when he had called her, she stood in the door.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 16, E'And he said, About this season, according to the time of life, thou shalt embrace a son. And she said, Nay, my lord, thou man of God, do not lie unto thine handmaid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 17, E'And the woman conceived, and bare a son at that season that Elisha had said unto her, according to the time of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 18, E'And when the child was grown, it fell on a day, that he went out to his father to the reapers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 19, E'And he said unto his father, My head, my head. And he said to a lad, Carry him to his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 20, E'And when he had taken him, and brought him to his mother, he sat on her knees till noon, and then died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 21, E'And she went up, and laid him on the bed of the man of God, and shut the door upon him, and went out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 22, E'And she called unto her husband, and said, Send me, I pray thee, one of the young men, and one of the asses, that I may run to the man of God, and come again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 23, E'And he said, Wherefore wilt thou go to him to day? it is neither new moon, nor sabbath. And she said, It shall be well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 24, E'Then she saddled an ass, and said to her servant, Drive, and go forward; slack not thy riding for me, except I bid thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 25, E'So she went and came unto the man of God to mount Carmel. And it came to pass, when the man of God saw her afar off, that he said to Gehazi his servant, Behold, yonder is that Shunammite:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 26, E'Run now, I pray thee, to meet her, and say unto her, Is it well with thee? is it well with thy husband? is it well with the child? And she answered, It is well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 27, E'And when she came to the man of God to the hill, she caught him by the feet: but Gehazi came near to thrust her away. And the man of God said, Let her alone; for her soul is vexed within her: and the LORD hath hid it from me, and hath not told me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 28, E'Then she said, Did I desire a son of my lord? did I not say, Do not deceive me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 29, E'Then he said to Gehazi, Gird up thy loins, and take my staff in thine hand, and go thy way: if thou meet any man, salute him not; and if any salute thee, answer him not again: and lay my staff upon the face of the child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 30, E'And the mother of the child said, As the LORD liveth, and as thy soul liveth, I will not leave thee. And he arose, and followed her.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 31, E'And Gehazi passed on before them, and laid the staff upon the face of the child; but there was neither voice, nor hearing. Wherefore he went again to meet him, and told him, saying, The child is not awaked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 32, E'And when Elisha was come into the house, behold, the child was dead, and laid upon his bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 33, E'He went in therefore, and shut the door upon them twain, and prayed unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 34, E'And he went up, and lay upon the child, and put his mouth upon his mouth, and his eyes upon his eyes, and his hands upon his hands: and he stretched himself upon the child; and the flesh of the child waxed warm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 35, E'Then he returned, and walked in the house to and fro; and went up, and stretched himself upon him: and the child sneezed seven times, and the child opened his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 36, E'And he called Gehazi, and said, Call this Shunammite. So he called her. And when she was come in unto him, he said, Take up thy son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 37, E'Then she went in, and fell at his feet, and bowed herself to the ground, and took up her son, and went out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 38, E'And Elisha came again to Gilgal: and there was a dearth in the land; and the sons of the prophets were sitting before him: and he said unto his servant, Set on the great pot, and seethe pottage for the sons of the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 39, E'And one went out into the field to gather herbs, and found a wild vine, and gathered thereof wild gourds his lap full, and came and shred them into the pot of pottage: for they knew them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 40, E'So they poured out for the men to eat. And it came to pass, as they were eating of the pottage, that they cried out, and said, O thou man of God, there is death in the pot. And they could not eat thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 41, E'But he said, Then bring meal. And he cast it into the pot; and he said, Pour out for the people, that they may eat. And there was no harm in the pot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 42, E'And there came a man from Baalshalisha, and brought the man of God bread of the firstfruits, twenty loaves of barley, and full ears of corn in the husk thereof. And he said, Give unto the people, that they may eat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 43, E'And his servitor said, What, should I set this before an hundred men? He said again, Give the people, that they may eat: for thus saith the LORD, They shall eat, and shall leave thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 4, 44, E'So he set it before them, and they did eat, and left thereof, according to the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 1, E'Now Naaman, captain of the host of the king of Syria, was a great man with his master, and honourable, because by him the LORD had given deliverance unto Syria: he was also a mighty man in valour, but he was a leper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 2, E'And the Syrians had gone out by companies, and had brought away captive out of the land of Israel a little maid; and she waited on Naamanâ€™s wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 3, E'And she said unto her mistress, Would God my lord were with the prophet that is in Samaria! for he would recover him of his leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 4, E'And one went in, and told his lord, saying, Thus and thus said the maid that is of the land of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 5, E'And the king of Syria said, Go to, go, and I will send a letter unto the king of Israel. And he departed, and took with him ten talents of silver, and six thousand pieces of gold, and ten changes of raiment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 6, E'And he brought the letter to the king of Israel, saying, Now when this letter is come unto thee, behold, I have therewith sent Naaman my servant to thee, that thou mayest recover him of his leprosy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 7, E'And it came to pass, when the king of Israel had read the letter, that he rent his clothes, and said, Am I God, to kill and to make alive, that this man doth send unto me to recover a man of his leprosy? wherefore consider, I pray you, and see how he seeketh a quarrel against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 8, E'And it was so, when Elisha the man of God had heard that the king of Israel had rent his clothes, that he sent to the king, saying, Wherefore hast thou rent thy clothes? let him come now to me, and he shall know that there is a prophet in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 9, E'So Naaman came with his horses and with his chariot, and stood at the door of the house of Elisha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 10, E'And Elisha sent a messenger unto him, saying, Go and wash in Jordan seven times, and thy flesh shall come again to thee, and thou shalt be clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 11, E'But Naaman was wroth, and went away, and said, Behold, I thought, He will surely come out to me, and stand, and call on the name of the LORD his God, and strike his hand over the place, and recover the leper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 12, E'Are not Abana and Pharpar, rivers of Damascus, better than all the waters of Israel? may I not wash in them, and be clean? So he turned and went away in a rage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 13, E'And his servants came near, and spake unto him, and said, My father, if the prophet had bid thee do some great thing, wouldest thou not have done it? how much rather then, when he saith to thee, Wash, and be clean?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 14, E'Then went he down, and dipped himself seven times in Jordan, according to the saying of the man of God: and his flesh came again like unto the flesh of a little child, and he was clean.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 15, E'And he returned to the man of God, he and all his company, and came, and stood before him: and he said, Behold, now I know that there is no God in all the earth, but in Israel: now therefore, I pray thee, take a blessing of thy servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 16, E'But he said, As the LORD liveth, before whom I stand, I will receive none. And he urged him to take it; but he refused.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 17, E'And Naaman said, Shall there not then, I pray thee, be given to thy servant two mulesâ€™ burden of earth? for thy servant will henceforth offer neither burnt offering nor sacrifice unto other gods, but unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 18, E'In this thing the LORD pardon thy servant, that when my master goeth into the house of Rimmon to worship there, and he leaneth on my hand, and I bow myself in the house of Rimmon: when I bow down myself in the house of Rimmon, the LORD pardon thy servant in this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 19, E'And he said unto him, Go in peace. So he departed from him a little way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 20, E'But Gehazi, the servant of Elisha the man of God, said, Behold, my master hath spared Naaman this Syrian, in not receiving at his hands that which he brought: but, as the LORD liveth, I will run after him, and take somewhat of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 21, E'So Gehazi followed after Naaman. And when Naaman saw him running after him, he lighted down from the chariot to meet him, and said, Is all well?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 22, E'And he said, All is well. My master hath sent me, saying, Behold, even now there be come to me from mount Ephraim two young men of the sons of the prophets: give them, I pray thee, a talent of silver, and two changes of garments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 23, E'And Naaman said, Be content, take two talents. And he urged him, and bound two talents of silver in two bags, with two changes of garments, and laid them upon two of his servants; and they bare them before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 24, E'And when he came to the tower, he took them from their hand, and bestowed them in the house: and he let the men go, and they departed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 25, E'But he went in, and stood before his master. And Elisha said unto him, Whence comest thou, Gehazi? And he said, Thy servant went no whither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 26, E'And he said unto him, Went not mine heart with thee, when the man turned again from his chariot to meet thee? Is it a time to receive money, and to receive garments, and oliveyards, and vineyards, and sheep, and oxen, and menservants, and maidservants?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 5, 27, E'The leprosy therefore of Naaman shall cleave unto thee, and unto thy seed for ever. And he went out from his presence a leper as white as snow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 1, E'And the sons of the prophets said unto Elisha, Behold now, the place where we dwell with thee is too strait for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 2, E'Let us go, we pray thee, unto Jordan, and take thence every man a beam, and let us make us a place there, where we may dwell. And he answered, Go ye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 3, E'And one said, Be content, I pray thee, and go with thy servants. And he answered, I will go.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 4, E'So he went with them. And when they came to Jordan, they cut down wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 5, E'But as one was felling a beam, the axe head fell into the water: and he cried, and said, Alas, master! for it was borrowed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 6, E'And the man of God said, Where fell it? And he shewed him the place. And he cut down a stick, and cast it in thither; and the iron did swim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 7, E'Therefore said he, Take it up to thee. And he put out his hand, and took it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 8, E'Then the king of Syria warred against Israel, and took counsel with his servants, saying, In such and such a place shall be my camp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 9, E'And the man of God sent unto the king of Israel, saying, Beware that thou pass not such a place; for thither the Syrians are come down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 10, E'And the king of Israel sent to the place which the man of God told him and warned him of, and saved himself there, not once nor twice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 11, E'Therefore the heart of the king of Syria was sore troubled for this thing; and he called his servants, and said unto them, Will ye not shew me which of us is for the king of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 12, E'And one of his servants said, None, my lord, O king: but Elisha, the prophet that is in Israel, telleth the king of Israel the words that thou speakest in thy bedchamber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 13, E'And he said, Go and spy where he is, that I may send and fetch him. And it was told him, saying, Behold, he is in Dothan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 14, E'Therefore sent he thither horses, and chariots, and a great host: and they came by night, and compassed the city about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 15, E'And when the servant of the man of God was risen early, and gone forth, behold, an host compassed the city both with horses and chariots. And his servant said unto him, Alas, my master! how shall we do?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 16, E'And he answered, Fear not: for they that be with us are more than they that be with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 17, E'And Elisha prayed, and said, LORD, I pray thee, open his eyes, that he may see. And the LORD opened the eyes of the young man; and he saw: and, behold, the mountain was full of horses and chariots of fire round about Elisha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 18, E'And when they came down to him, Elisha prayed unto the LORD, and said, Smite this people, I pray thee, with blindness. And he smote them with blindness according to the word of Elisha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 19, E'And Elisha said unto them, This is not the way, neither is this the city: follow me, and I will bring you to the man whom ye seek. But he led them to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 20, E'And it came to pass, when they were come into Samaria, that Elisha said, LORD, open the eyes of these men, that they may see. And the LORD opened their eyes, and they saw; and, behold, they were in the midst of Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 21, E'And the king of Israel said unto Elisha, when he saw them, My father, shall I smite them? shall I smite them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 22, E'And he answered, Thou shalt not smite them: wouldest thou smite those whom thou hast taken captive with thy sword and with thy bow? set bread and water before them, that they may eat and drink, and go to their master.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 23, E'And he prepared great provision for them: and when they had eaten and drunk, he sent them away, and they went to their master. So the bands of Syria came no more into the land of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 24, E'And it came to pass after this, that Benhadad king of Syria gathered all his host, and went up, and besieged Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 25, E'And there was a great famine in Samaria: and, behold, they besieged it, until an assâ€™s head was sold for fourscore pieces of silver, and the fourth part of a cab of doveâ€™s dung for five pieces of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 26, E'And as the king of Israel was passing by upon the wall, there cried a woman unto him, saying, Help, my lord, O king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 27, E'And he said, If the LORD do not help thee, whence shall I help thee? out of the barnfloor, or out of the winepress?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 28, E'And the king said unto her, What aileth thee? And she answered, This woman said unto me, Give thy son, that we may eat him to day, and we will eat my son to morrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 29, E'So we boiled my son, and did eat him: and I said unto her on the next day, Give thy son, that we may eat him: and she hath hid her son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 30, E'And it came to pass, when the king heard the words of the woman, that he rent his clothes; and he passed by upon the wall, and the people looked, and, behold, he had sackcloth within upon his flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 31, E'Then he said, God do so and more also to me, if the head of Elisha the son of Shaphat shall stand on him this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 32, E'But Elisha sat in his house, and the elders sat with him; and the king sent a man from before him: but ere the messenger came to him, he said to the elders, See ye how this son of a murderer hath sent to take away mine head? look, when the messenger cometh, shut the door, and hold him fast at the door: is not the sound of his masterâ€™s feet behind him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 6, 33, E'And while he yet talked with them, behold, the messenger came down unto him: and he said, Behold, this evil is of the LORD; what should I wait for the LORD any longer?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 1, E'Then Elisha said, Hear ye the word of the LORD; Thus saith the LORD, To morrow about this time shall a measure of fine flour be sold for a shekel, and two measures of barley for a shekel, in the gate of Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 2, E'Then a lord on whose hand the king leaned answered the man of God, and said, Behold, if the LORD would make windows in heaven, might this thing be? And he said, Behold, thou shalt see it with thine eyes, but shalt not eat thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 3, E'And there were four leprous men at the entering in of the gate: and they said one to another, Why sit we here until we die?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 4, E'If we say, We will enter into the city, then the famine is in the city, and we shall die there: and if we sit still here, we die also. Now therefore come, and let us fall unto the host of the Syrians: if they save us alive, we shall live; and if they kill us, we shall but die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 5, E'And they rose up in the twilight, to go unto the camp of the Syrians: and when they were come to the uttermost part of the camp of Syria, behold, there was no man there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 6, E'For the LORD had made the host of the Syrians to hear a noise of chariots, and a noise of horses, even the noise of a great host: and they said one to another, Lo, the king of Israel hath hired against us the kings of the Hittites, and the kings of the Egyptians, to come upon us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 7, E'Wherefore they arose and fled in the twilight, and left their tents, and their horses, and their asses, even the camp as it was, and fled for their life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 8, E'And when these lepers came to the uttermost part of the camp, they went into one tent, and did eat and drink, and carried thence silver, and gold, and raiment, and went and hid it; and came again, and entered into another tent, and carried thence also, and went and hid it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 9, E'Then they said one to another, We do not well: this day is a day of good tidings, and we hold our peace: if we tarry till the morning light, some mischief will come upon us: now therefore come, that we may go and tell the kingâ€™s household.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 10, E'So they came and called unto the porter of the city: and they told them, saying, We came to the camp of the Syrians, and, behold, there was no man there, neither voice of man, but horses tied, and asses tied, and the tents as they were.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 11, E'And he called the porters; and they told it to the kingâ€™s house within.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 12, E'And the king arose in the night, and said unto his servants, I will now shew you what the Syrians have done to us. They know that we be hungry; therefore are they gone out of the camp to hide themselves in the field, saying, When they come out of the city, we shall catch them alive, and get into the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 13, E'And one of his servants answered and said, Let some take, I pray thee, five of the horses that remain, which are left in the city, (behold, they are as all the multitude of Israel that are left in it: behold, I say, they are even as all the multitude of the Israelites that are consumed:) and let us send and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 14, E'They took therefore two chariot horses; and the king sent after the host of the Syrians, saying, Go and see.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 15, E'And they went after them unto Jordan: and, lo, all the way was full of garments and vessels, which the Syrians had cast away in their haste. And the messengers returned, and told the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 16, E'And the people went out, and spoiled the tents of the Syrians. So a measure of fine flour was sold for a shekel, and two measures of barley for a shekel, according to the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 17, E'And the king appointed the lord on whose hand he leaned to have the charge of the gate: and the people trode upon him in the gate, and he died, as the man of God had said, who spake when the king came down to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 18, E'And it came to pass as the man of God had spoken to the king, saying, Two measures of barley for a shekel, and a measure of fine flour for a shekel, shall be to morrow about this time in the gate of Samaria:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 19, E'And that lord answered the man of God, and said, Now, behold, if the LORD should make windows in heaven, might such a thing be? And he said, Behold, thou shalt see it with thine eyes, but shalt not eat thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 7, 20, E'And so it fell out unto him: for the people trode upon him in the gate, and he died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 1, E'Then spake Elisha unto the woman, whose son he had restored to life, saying, Arise, and go thou and thine household, and sojourn wheresoever thou canst sojourn: for the LORD hath called for a famine; and it shall also come upon the land seven years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 2, E'And the woman arose, and did after the saying of the man of God: and she went with her household, and sojourned in the land of the Philistines seven years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 3, E'And it came to pass at the seven yearsâ€™ end, that the woman returned out of the land of the Philistines: and she went forth to cry unto the king for her house and for her land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 4, E'And the king talked with Gehazi the servant of the man of God, saying, Tell me, I pray thee, all the great things that Elisha hath done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 5, E'And it came to pass, as he was telling the king how he had restored a dead body to life, that, behold, the woman, whose son he had restored to life, cried to the king for her house and for her land. And Gehazi said, My lord, O king, this is the woman, and this is her son, whom Elisha restored to life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 6, E'And when the king asked the woman, she told him. So the king appointed unto her a certain officer, saying, Restore all that was hers, and all the fruits of the field since the day that she left the land, even until now.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 7, E'And Elisha came to Damascus; and Benhadad the king of Syria was sick; and it was told him, saying, The man of God is come hither.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 8, E'And the king said unto Hazael, Take a present in thine hand, and go, meet the man of God, and enquire of the LORD by him, saying, Shall I recover of this disease?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 9, E'So Hazael went to meet him, and took a present with him, even of every good thing of Damascus, forty camelsâ€™ burden, and came and stood before him, and said, Thy son Benhadad king of Syria hath sent me to thee, saying, Shall I recover of this disease?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 10, E'And Elisha said unto him, Go, say unto him, Thou mayest certainly recover: howbeit the LORD hath shewed me that he shall surely die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 11, E'And he settled his countenance stedfastly, until he was ashamed: and the man of God wept.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 12, E'And Hazael said, Why weepeth my lord? And he answered, Because I know the evil that thou wilt do unto the children of Israel: their strong holds wilt thou set on fire, and their young men wilt thou slay with the sword, and wilt dash their children, and rip up their women with child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 13, E'And Hazael said, But what, is thy servant a dog, that he should do this great thing? And Elisha answered, The LORD hath shewed me that thou shalt be king over Syria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 14, E'So he departed from Elisha, and came to his master; who said to him, What said Elisha to thee? And he answered, He told me that thou shouldest surely recover.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 15, E'And it came to pass on the morrow, that he took a thick cloth, and dipped it in water, and spread it on his face, so that he died: and Hazael reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 16, E'And in the fifth year of Joram the son of Ahab king of Israel, Jehoshaphat being then king of Judah, Jehoram the son of Je hoshaphat king of Judah began to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 17, E'Thirty and two years old was he when he began to reign; and he reigned eight years in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 18, E'And he walked in the way of the kings of Israel, as did the house of Ahab: for the daughter of Ahab was his wife: and he did evil in the sight of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 19, E'Yet the LORD would not destroy Judah for David his servantâ€™s sake, as he promised him to give him alway a light, and to his children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 20, E'In his days Edom revolted from under the hand of Judah, and made a king over themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 21, E'So Joram went over to Zair, and all the chariots with him: and he rose by night, and smote the Edomites which compassed him about, and the captains of the chariots: and the people fled into their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 22, E'Yet Edom revolted from under the hand of Judah unto this day. Then Libnah revolted at the same time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 23, E'And the rest of the acts of Joram, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 24, E'And Joram slept with his fathers, and was buried with his fathers in the city of David: and Ahaziah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 25, E'In the twelfth year of Joram the son of Ahab king of Israel did Ahaziah the son of Jehoram king of Judah begin to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 26, E'Two and twenty years old was Ahaziah when he began to reign; and he reigned one year in Jerusalem. And his motherâ€™s name was Athaliah, the daughter of Omri king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 27, E'And he walked in the way of the house of Ahab, and did evil in the sight of the LORD, as did the house of Ahab: for he was the son in law of the house of Ahab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 28, E'And he went with Joram the son of Ahab to the war against Hazael king of Syria in Ramothgilead; and the Syrians wounded Joram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 8, 29, E'And king Joram went back to be healed in Jezreel of the wounds which the Syrians had given him at Ramah, when he fought against Hazael king of Syria. And Ahaziah the son of Jehoram king of Judah went down to see Joram the son of Ahab in Jezreel, because he was sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 1, E'And Elisha the prophet called one of the children of the prophets, and said unto him, Gird up thy loins, and take this box of oil in thine hand, and go to Ramothgilead:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 2, E'And when thou comest thither, look out there Jehu the son of Jehoshaphat the son of Nimshi, and go in, and make him arise up from among his brethren, and carry him to an inner chamber;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 3, E'Then take the box of oil, and pour it on his head, and say, Thus saith the LORD, I have anointed thee king over Israel. Then open the door, and flee, and tarry not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 4, E'So the young man, even the young man the prophet, went to Ramothgilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 5, E'And when he came, behold, the captains of the host were sitting; and he said, I have an errand to thee, O captain. And Jehu said, Unto which of all us? And he said, To thee, O captain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 6, E'And he arose, and went into the house; and he poured the oil on his head, and said unto him, Thus saith the LORD God of Israel, I have anointed thee king over the people of the LORD, even over Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 7, E'And thou shalt smite the house of Ahab thy master, that I may avenge the blood of my servants the prophets, and the blood of all the servants of the LORD, at the hand of Jezebel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 8, E'For the whole house of Ahab shall perish: and I will cut off from Ahab him that pisseth against the wall, and him that is shut up and left in Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 9, E'And I will make the house of Ahab like the house of Jeroboam the son of Nebat, and like the house of Baasha the son of Ahijah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 10, E'And the dogs shall eat Jezebel in the portion of Jezreel, and there shall be none to bury her. And he opened the door, and fled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 11, E'Then Jehu came forth to the servants of his lord: and one said unto him, Is all well? wherefore came this mad fellow to thee? And he said unto them, Ye know the man, and his communication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 12, E'And they said, It is false; tell us now. And he said, Thus and thus spake he to me, saying, Thus saith the LORD, I have anointed thee king over Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 13, E'Then they hasted, and took every man his garment, and put it under him on the top of the stairs, and blew with trumpets, saying, Jehu is king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 14, E'So Jehu the son of Jehoshaphat the son of Nimshi conspired against Joram. (Now Joram had kept Ramothgilead, he and all Israel, because of Hazael king of Syria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 15, E'But king Joram was returned to be healed in Jezreel of the wounds which the Syrians had given him, when he fought with Hazael king of Syria.) And Jehu said, If it be your minds, then let none go forth nor escape out of the city to go to tell it in Jezreel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 16, E'So Jehu rode in a chariot, and went to Jezreel; for Joram lay there. And Ahaziah king of Judah was come down to see Joram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 17, E'And there stood a watchman on the tower in Jezreel, and he spied the company of Jehu as he came, and said, I see a company. And Joram said, Take an horseman, and send to meet them, and let him say, Is it peace?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 18, E'So there went one on horseback to meet him, and said, Thus saith the king, Is it peace? And Jehu said, What hast thou to do with peace? turn thee behind me. And the watchman told, saying, The messenger came to them, but he cometh not again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 19, E'Then he sent out a second on horseback, which came to them, and said, Thus saith the king, Is it peace? And Jehu answered, What hast thou to do with peace? turn thee behind me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 20, E'And the watchman told, saying, He came even unto them, and cometh not again: and the driving is like the driving of Jehu the son of Nimshi; for he driveth furiously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 21, E'And Joram said, Make ready. And his chariot was made ready. And Joram king of Israel and Ahaziah king of Judah went out, each in his chariot, and they went out against Jehu, and met him in the portion of Naboth the Jezreelite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 22, E'And it came to pass, when Joram saw Jehu, that he said, Is it peace, Jehu? And he answered, What peace, so long as the whoredoms of thy mother Jezebel and her witchcrafts are so many?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 23, E'And Joram turned his hands, and fled, and said to Ahaziah, There is treachery, O Ahaziah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 24, E'And Jehu drew a bow with his full strength, and smote Jehoram between his arms, and the arrow went out at his heart, and he sunk down in his chariot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 25, E'Then said Jehu to Bidkar his captain, Take up, and cast him in the portion of the field of Naboth the Jezreelite: for remember how that, when I and thou rode together after Ahab his father, the LORD laid this burden upon him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 26, E'Surely I have seen yesterday the blood of Naboth, and the blood of his sons, saith the LORD; and I will requite thee in this plat, saith the LORD. Now therefore take and cast him into the plat of ground, according to the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 27, E'But when Ahaziah the king of Judah saw this, he fled by the way of the garden house. And Jehu followed after him, and said, Smite him also in the chariot. And they did so at the going up to Gur, which is by Ibleam. And he fled to Megiddo, and died there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 28, E'And his servants carried him in a chariot to Jerusalem, and buried him in his sepulchre with his fathers in the city of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 29, E'And in the eleventh year of Joram the son of Ahab began Ahaziah to reign over Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 30, E'And when Jehu was come to Jezreel, Jezebel heard of it; and she painted her face, and tired her head, and looked out at a window.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 31, E'And as Jehu entered in at the gate, she said, Had Zimri peace, who slew his master?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 32, E'And he lifted up his face to the window, and said, Who is on my side? who? And there looked out to him two or three eunuchs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 33, E'And he said, Throw her down. So they threw her down: and some of her blood was sprinkled on the wall, and on the horses: and he trode her under foot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 34, E'And when he was come in, he did eat and drink, and said, Go, see now this cursed woman, and bury her: for she is a kingâ€™s daughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 35, E'And they went to bury her: but they found no more of her than the skull, and the feet, and the palms of her hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 36, E'Wherefore they came again, and told him. And he said, This is the word of the LORD, which he spake by his servant Elijah the Tishbite, saying, In the portion of Jezreel shall dogs eat the flesh of Jezebel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 9, 37, E'And the carcase of Jezebel shall be as dung upon the face of the field in the portion of Jezreel; so that they shall not say, This is Jezebel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 1, E'And Ahab had seventy sons in Samaria. And Jehu wrote letters, and sent to Samaria, unto the rulers of Jezreel, to the elders, and to them that brought up Ahabâ€™s children, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 2, E'Now as soon as this letter cometh to you, seeing your masterâ€™s sons are with you, and there are with you chariots and horses, a fenced city also, and armour;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 3, E'Look even out the best and meetest of your masterâ€™s sons, and set him on his fatherâ€™s throne, and fight for your masterâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 4, E'But they were exceedingly afraid, and said, Behold, two kings stood not before him: how then shall we stand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 5, E'And he that was over the house, and he that was over the city, the elders also, and the bringers up of the children, sent to Jehu, saying, We are thy servants, and will do all that thou shalt bid us; we will not make any king: do thou that which is good in thine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 6, E'Then he wrote a letter the second time to them, saying, If ye be mine, and if ye will hearken unto my voice, take ye the heads of the men your masterâ€™s sons, and come to me to Jezreel by to morrow this time. Now the kingâ€™s sons, being seventy persons, were with the great men of the city, which brought them up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 7, E'And it came to pass, when the letter came to them, that they took the kingâ€™s sons, and slew seventy persons, and put their heads in baskets, and sent him them to Jezreel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 8, E'And there came a messenger, and told him, saying, They have brought the heads of the kingâ€™s sons. And he said, Lay ye them in two heaps at the entering in of the gate until the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 9, E'And it came to pass in the morning, that he went out, and stood, and said to all the people, Ye be righteous: behold, I conspired against my master, and slew him: but who slew all these?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 10, E'Know now that there shall fall unto the earth nothing of the word of the LORD, which the LORD spake concerning the house of Ahab: for the LORD hath done that which he spake by his servant Elijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 11, E'So Jehu slew all that remained of the house of Ahab in Jezreel, and all his great men, and his kinsfolks, and his priests, until he left him none remaining.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 12, E'And he arose and departed, and came to Samaria. And as he was at the shearing house in the way,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 13, E'Jehu met with the brethren of Ahaziah king of Judah, and said, Who are ye? And they answered, We are the brethren of Ahaziah; and we go down to salute the children of the king and the children of the queen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 14, E'And he said, Take them alive. And they took them alive, and slew them at the pit of the shearing house, even two and forty men; neither left he any of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 15, E'And when he was departed thence, he lighted on Jehonadab the son of Rechab coming to meet him: and he saluted him, and said to him, Is thine heart right, as my heart is with thy heart? And Jehonadab answered, It is. If it be, give me thine hand. And he gave him his hand; and he took him up to him into the chariot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 16, E'And he said, Come with me, and see my zeal for the LORD. So they made him ride in his chariot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 17, E'And when he came to Samaria, he slew all that remained unto Ahab in Samaria, till he had destroyed him, according to the saying of the LORD, which he spake to Elijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 18, E'And Jehu gathered all the people together, and said unto them, Ahab served Baal a little; but Jehu shall serve him much.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 19, E'Now therefore call unto me all the prophets of Baal, all his servants, and all his priests; let none be wanting: for I have a great sacrifice to do to Baal; whosoever shall be wanting, he shall not live. But Jehu did it in subtilty, to the intent that he might destroy the worshippers of Baal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 20, E'And Jehu said, Proclaim a solemn assembly for Baal. And they proclaimed it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 21, E'And Jehu sent through all Israel: and all the worshippers of Baal came, so that there was not a man left that came not. And they came into the house of Baal; and the house of Baal was full from one end to another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 22, E'And he said unto him that was over the vestry, Bring forth vestments for all the worshippers of Baal. And he brought them forth vestments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 23, E'And Jehu went, and Jehonadab the son of Rechab, into the house of Baal, and said unto the worshippers of Baal, Search, and look that there be here with you none of the servants of the LORD, but the worshippers of Baal only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 24, E'And when they went in to offer sacrifices and burnt offerings, Jehu appointed fourscore men without, and said, If any of the men whom I have brought into your hands escape, he that letteth him go, his life shall be for the life of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 25, E'And it came to pass, as soon as he had made an end of offering the burnt offering, that Jehu said to the guard and to the captains, Go in, and slay them; let none come forth. And they smote them with the edge of the sword; and the guard and the captains cast them out, and went to the city of the house of Baal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 26, E'And they brought forth the images out of the house of Baal, and burned them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 27, E'And they brake down the image of Baal, and brake down the house of Baal, and made it a draught house unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 28, E'Thus Jehu destroyed Baal out of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 29, E'Howbeit from the sins of Jeroboam the son of Nebat, who made Israel to sin, Jehu departed not from after them, to wit, the golden calves that were in Bethel, and that were in Dan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 30, E'And the LORD said unto Jehu, Because thou hast done well in executing that which is right in mine eyes, and hast done unto the house of Ahab according to all that was in mine heart, thy children of the fourth generation shall sit on the throne of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 31, E'But Jehu took no heed to walk in the law of the LORD God of Israel with all his heart: for he departed not from the sins of Jeroboam, which made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 32, E'In those days the LORD began to cut Israel short: and Hazael smote them in all the coasts of Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 33, E'From Jordan eastward, all the land of Gilead, the Gadites, and the Reubenites, and the Manassites, from Aroer, which is by the river Arnon, even Gilead and Bashan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 34, E'Now the rest of the acts of Jehu, and all that he did, and all his might, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 35, E'And Jehu slept with his fathers: and they buried him in Samaria. And Jehoahaz his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 10, 36, E'And the time that Jehu reigned over Israel in Samaria was twenty and eight years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 1, E'And when Athaliah the mother of Ahaziah saw that her son was dead, she arose and destroyed all the seed royal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 2, E'But Jehosheba, the daughter of king Joram, sister of Ahaziah, took Joash the son of Ahaziah, and stole him from among the kingâ€™s sons which were slain; and they hid him, even him and his nurse, in the bedchamber from Athaliah, so that he was not slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 3, E'And he was with her hid in the house of the LORD six years. And Athaliah did reign over the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 4, E'And the seventh year Jehoiada sent and fetched the rulers over hundreds, with the captains and the guard, and brought them to him into the house of the LORD, and made a covenant with them, and took an oath of them in the house of the LORD, and shewed them the kingâ€™s son.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 5, E'And he commanded them, saying, This is the thing that ye shall do; A third part of you that enter in on the sabbath shall even be keepers of the watch of the kingâ€™s house;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 6, E'And a third part shall be at the gate of Sur; and a third part at the gate behind the guard: so shall ye keep the watch of the house, that it be not broken down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 7, E'And two parts of all you that go forth on the sabbath, even they shall keep the watch of the house of the LORD about the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 8, E'And ye shall compass the king round about, every man with his weapons in his hand: and he that cometh within the ranges, let him be slain: and be ye with the king as he goeth out and as he cometh in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 9, E'And the captains over the hundreds did according to all things that Jehoiada the priest commanded: and they took every man his men that were to come in on the sabbath, with them that should go out on the sabbath, and came to Jehoiada the priest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 10, E'And to the captains over hundreds did the priest give king Davidâ€™s spears and shields, that were in the temple of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 11, E'And the guard stood, every man with his weapons in his hand, round about the king, from the right corner of the temple to the left corner of the temple, along by the altar and the temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 12, E'And he brought forth the kingâ€™s son, and put the crown upon him, and gave him the testimony; and they made him king, and anointed him; and they clapped their hands, and said, God save the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 13, E'And when Athaliah heard the noise of the guard and of the people, she came to the people into the temple of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 14, E'And when she looked, behold, the king stood by a pillar, as the manner was, and the princes and the trumpeters by the king, and all the people of the land rejoiced, and blew with trumpets: and Athaliah rent her clothes, and cried, Treason, Treason.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 15, E'But Jehoiada the priest commanded the captains of the hundreds, the officers of the host, and said unto them, Have her forth without the ranges: and him that followeth her kill with the sword. For the priest had said, Let her not be slain in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 16, E'And they laid hands on her; and she went by the way by the which the horses came into the kingâ€™s house: and there was she slain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 17, E'And Jehoiada made a covenant between the LORD and the king and the people, that they should be the LORDâ€™s people; between the king also and the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 18, E'And all the people of the land went into the house of Baal, and brake it down; his altars and his images brake they in pieces thoroughly, and slew Mattan the priest of Baal before the altars. And the priest appointed officers over the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 19, E'And he took the rulers over hundreds, and the captains, and the guard, and all the people of the land; and they brought down the king from the house of the LORD, and came by the way of the gate of the guard to the kingâ€™s house. And he sat on the throne of the kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 20, E'And all the people of the land rejoiced, and the city was in quiet: and they slew Athaliah with the sword beside the kingâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 11, 21, E'Seven years old was Jehoash when he began to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 1, E'In the seventh year of Jehu Jehoash began to reign; and forty years reigned he in Jerusalem. And his motherâ€™s name was Zibiah of Beersheba.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 2, E'And Jehoash did that which was right in the sight of the LORD all his days wherein Jehoiada the priest instructed him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 3, E'But the high places were not taken away: the people still sacrificed and burnt incense in the high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 4, E'And Jehoash said to the priests, All the money of the dedicated things that is brought into the house of the LORD, even the money of every one that passeth the account, the money that every man is set at, and all the money that cometh into any manâ€™s heart to bring into the house of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 5, E'Let the priests take it to them, every man of his acquaintance: and let them repair the breaches of the house, wheresoever any breach shall be found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 6, E'But it was so, that in the three and twentieth year of king Jehoash the priests had not repaired the breaches of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 7, E'Then king Jehoash called for Jehoiada the priest, and the other priests, and said unto them, Why repair ye not the breaches of the house? now therefore receive no more money of your acquaintance, but deliver it for the breaches of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 8, E'And the priests consented to receive no more money of the people, neither to repair the breaches of the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 9, E'But Jehoiada the priest took a chest, and bored a hole in the lid of it, and set it beside the altar, on the right side as one cometh into the house of the LORD: and the priests that kept the door put therein all the money that was brought into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 10, E'And it was so, when they saw that there was much money in the chest, that the kingâ€™s scribe and the high priest came up, and they put up in bags, and told the money that was found in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 11, E'And they gave the money, being told, into the hands of them that did the work, that had the oversight of the house of the LORD: and they laid it out to the carpenters and builders, that wrought upon the house of the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 12, E'And to masons, and hewers of stone, and to buy timber and hewed stone to repair the breaches of the house of the LORD, and for all that was laid out for the house to repair it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 13, E'Howbeit there were not made for the house of the LORD bowls of silver, snuffers, basons, trumpets, any vessels of gold, or vessels of silver, of the money that was brought into the house of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 14, E'But they gave that to the workmen, and repaired therewith the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 15, E'Moreover they reckoned not with the men, into whose hand they delivered the money to be bestowed on workmen: for they dealt faithfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 16, E'The trespass money and sin money was not brought into the house of the LORD: it was the priestsâ€™.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 17, E'Then Hazael king of Syria went up, and fought against Gath, and took it: and Hazael set his face to go up to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 18, E'And Jehoash king of Judah took all the hallowed things that Jehoshaphat, and Jehoram, and Ahaziah, his fathers, kings of Judah, had dedicated, and his own hallowed things, and all the gold that was found in the treasures of the house of the LORD, and in the kingâ€™s house, and sent it to Hazael king of Syria: and he went away from Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 19, E'And the rest of the acts of Joash, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 20, E'And his servants arose, and made a conspiracy, and slew Joash in the house of Millo, which goeth down to Silla.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 12, 21, E'For Jozachar the son of Shimeath, and Jehozabad the son of Shomer, his servants, smote him, and he died; and they buried him with his fathers in the city of David: and Amaziah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 1, E'In the three and twentieth year of Joash the son of Ahaziah king of Judah Jehoahaz the son of Jehu began to reign over Israel in Samaria, and reigned seventeen years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 2, E'And he did that which was evil in the sight of the LORD, and followed the sins of Jeroboam the son of Nebat, which made Israel to sin; he departed not therefrom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 3, E'And the anger of the LORD was kindled against Israel, and he delivered them into the hand of Hazael king of Syria, and into the hand of Benhadad the son of Hazael, all their days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 4, E'And Jehoahaz besought the LORD, and the LORD hearkened unto him: for he saw the oppression of Israel, because the king of Syria oppressed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 5, E'(And the LORD gave Israel a saviour, so that they went out from under the hand of the Syrians: and the children of Israel dwelt in their tents, as beforetime.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 6, E'Nevertheless they departed not from the sins of the house of Jeroboam, who made Israel sin, but walked therein: and there remained the grove also in Samaria.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 7, E'Neither did he leave of the people to Jehoahaz but fifty horsemen, and ten chariots, and ten thousand footmen; for the king of Syria had destroyed them, and had made them like the dust by threshing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 8, E'Now the rest of the acts of Jehoahaz, and all that he did, and his might, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 9, E'And Jehoahaz slept with his fathers; and they buried him in Samaria: and Joash his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 10, E'In the thirty and seventh year of Joash king of Judah began Jehoash the son of Jehoahaz to reign over Israel in Samaria, and reigned sixteen years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 11, E'And he did that which was evil in the sight of the LORD; he departed not from all the sins of Jeroboam the son of Nebat, who made Israel sin: but he walked therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 12, E'And the rest of the acts of Joash, and all that he did, and his might wherewith he fought against Amaziah king of Judah, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 13, E'And Joash slept with his fathers; and Jeroboam sat upon his throne: and Joash was buried in Samaria with the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 14, E'Now Elisha was fallen sick of his sickness whereof he died. And Joash the king of Israel came down unto him, and wept over his face, and said, O my father, my father, the chariot of Israel, and the horsemen thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 15, E'And Elisha said unto him, Take bow and arrows. And he took unto him bow and arrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 16, E'And he said to the king of Israel, Put thine hand upon the bow. And he put his hand upon it: and Elisha put his hands upon the kingâ€™s hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 17, E'And he said, Open the window eastward. And he opened it. Then Elisha said, Shoot. And he shot. And he said, The arrow of the LORDâ€™s deliverance, and the arrow of deliverance from Syria: for thou shalt smite the Syrians in Aphek, till thou have consumed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 18, E'And he said, Take the arrows. And he took them. And he said unto the king of Israel, Smite upon the ground. And he smote thrice, and stayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 19, E'And the man of God was wroth with him, and said, Thou shouldest have smitten five or six times; then hadst thou smitten Syria till thou hadst consumed it: whereas now thou shalt smite Syria but thrice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 20, E'And Elisha died, and they buried him. And the bands of the Moabites invaded the land at the coming in of the year.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 21, E'And it came to pass, as they were burying a man, that, behold, they spied a band of men; and they cast the man into the sepulchre of Elisha: and when the man was let down, and touched the bones of Elisha, he revived, and stood up on his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 22, E'But Hazael king of Syria oppressed Israel all the days of Jehoahaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 23, E'And the LORD was gracious unto them, and had compassion on them, and had respect unto them, because of his covenant with Abraham, Isaac, and Jacob, and would not destroy them, neither cast he them from his presence as yet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 24, E'So Hazael king of Syria died; and Benhadad his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 13, 25, E'And Jehoash the son of Jehoahaz took again out of the hand of Benhadad the son of Hazael the cities, which he had taken out of the hand of Jehoahaz his father by war. Three times did Joash beat him, and recovered the cities of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 1, E'In the second year of Joash son of Jehoahaz king of Israel reigned Amaziah the son of Joash king of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 2, E'He was twenty and five years old when he began to reign, and reigned twenty and nine years in Jerusalem. And his motherâ€™s name was Jehoaddan of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 3, E'And he did that which was right in the sight of the LORD, yet not like David his father: he did according to all things as Joash his father did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 4, E'Howbeit the high places were not taken away: as yet the people did sacrifice and burnt incense on the high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 5, E'And it came to pass, as soon as the kingdom was confirmed in his hand, that he slew his servants which had slain the king his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 6, E'But the children of the murderers he slew not: according unto that which is written in the book of the law of Moses, wherein the LORD commanded, saying, The fathers shall not be put to death for the children, nor the children be put to death for the fathers; but every man shall be put to death for his own sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 7, E'He slew of Edom in the valley of salt ten thousand, and took Selah by war, and called the name of it Joktheel unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 8, E'Then Amaziah sent messengers to Jehoash, the son of Jehoahaz son of Jehu, king of Israel, saying, Come, let us look one another in the face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 9, E'And Jehoash the king of Israel sent to Amaziah king of Judah, saying, The thistle that was in Lebanon sent to the cedar that was in Lebanon, saying, Give thy daughter to my son to wife: and there passed by a wild beast that was in Lebanon, and trode down the thistle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 10, E'Thou hast indeed smitten Edom, and thine heart hath lifted thee up: glory of this, and tarry at home: for why shouldest thou meddle to thy hurt, that thou shouldest fall, even thou, and Judah with thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 11, E'But Amaziah would not hear. Therefore Jehoash king of Israel went up; and he and Amaziah king of Judah looked one another in the face at Bethshemesh, which belongeth to Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 12, E'And Judah was put to the worse before Israel; and they fled every man to their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 13, E'And Jehoash king of Israel took Amaziah king of Judah, the son of Jehoash the son of Ahaziah, at Bethshemesh, and came to Jerusalem, and brake down the wall of Jerusalem from the gate of Ephraim unto the corner gate, four hundred cubits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 14, E'And he took all the gold and silver, and all the vessels that were found in the house of the LORD, and in the treasures of the kingâ€™s house, and hostages, and returned to Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 15, E'Now the rest of the acts of Jehoash which he did, and his might, and how he fought with Amaziah king of Judah, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 16, E'And Jehoash slept with his fathers, and was buried in Samaria with the kings of Israel; and Jeroboam his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 17, E'And Amaziah the son of Joash king of Judah lived after the death of Jehoash son of Jehoahaz king of Israel fifteen years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 18, E'And the rest of the acts of Amaziah, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 19, E'Now they made a conspiracy against him in Jerusalem: and he fled to Lachish; but they sent after him to Lachish, and slew him there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 20, E'And they brought him on horses: and he was buried at Jerusalem with his fathers in the city of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 21, E'And all the people of Judah took Azariah, which was sixteen years old, and made him king instead of his father Amaziah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 22, E'He built Elath, and restored it to Judah, after that the king slept with his fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 23, E'In the fifteenth year of Amaziah the son of Joash king of Judah Jeroboam the son of Joash king of Israel began to reign in Samaria, and reigned forty and one years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 24, E'And he did that which was evil in the sight of the LORD: he departed not from all the sins of Jeroboam the son of Nebat, who made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 25, E'He restored the coast of Israel from the entering of Hamath unto the sea of the plain, according to the word of the LORD God of Israel, which he spake by the hand of his servant Jonah, the son of Amittai, the prophet, which was of Gathhepher.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 26, E'For the LORD saw the affliction of Israel, that it was very bitter: for there was not any shut up, nor any left, nor any helper for Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 27, E'And the LORD said not that he would blot out the name of Israel from under heaven: but he saved them by the hand of Jeroboam the son of Joash.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 28, E'Now the rest of the acts of Jeroboam, and all that he did, and his might, how he warred, and how he recovered Damascus, and Hamath, which belonged to Judah, for Israel, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 14, 29, E'And Jeroboam slept with his fathers, even with the kings of Israel; and Zachariah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 1, E'In the twenty and seventh year of Jeroboam king of Israel began Azariah son of Amaziah king of Judah to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 2, E'Sixteen years old was he when he began to reign, and he reigned two and fifty years in Jerusalem. And his motherâ€™s name was Jecholiah of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 3, E'And he did that which was right in the sight of the LORD, according to all that his father Amaziah had done;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 4, E'Save that the high places were not removed: the people sacrificed and burnt incense still on the high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 5, E'And the LORD smote the king, so that he was a leper unto the day of his death, and dwelt in a several house. And Jotham the kingâ€™s son was over the house, judging the people of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 6, E'And the rest of the acts of Azariah, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 7, E'So Azariah slept with his fathers; and they buried him with his fathers in the city of David: and Jotham his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 8, E'In the thirty and eighth year of Azariah king of Judah did Zachariah the son of Jeroboam reign over Israel in Samaria six months.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 9, E'And he did that which was evil in the sight of the LORD, as his fathers had done: he departed not from the sins of Jeroboam the son of Nebat, who made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 10, E'And Shallum the son of Jabesh conspired against him, and smote him before the people, and slew him, and reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 11, E'And the rest of the acts of Zachariah, behold, they are written in the book of the chronicles of the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 12, E'This was the word of the LORD which he spake unto Jehu, saying, Thy sons shall sit on the throne of Israel unto the fourth generation. And so it came to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 13, E'Shallum the son of Jabesh began to reign in the nine and thirtieth year of Uzziah king of Judah; and he reigned a full month in Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 14, E'For Menahem the son of Gadi went up from Tirzah, and came to Samaria, and smote Shallum the son of Jabesh in Samaria, and slew him, and reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 15, E'And the rest of the acts of Shallum, and his conspiracy which he made, behold, they are written in the book of the chronicles of the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 16, E'Then Menahem smote Tiphsah, and all that were therein, and the coasts thereof from Tirzah: because they opened not to him, therefore he smote it; and all the women therein that were with child he ripped up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 17, E'In the nine and thirtieth year of Azariah king of Judah began Menahem the son of Gadi to reign over Israel, and reigned ten years in Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 18, E'And he did that which was evil in the sight of the LORD: he departed not all his days from the sins of Jeroboam the son of Nebat, who made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 19, E'And Pul the king of Assyria came against the land: and Menahem gave Pul a thousand talents of silver, that his hand might be with him to confirm the kingdom in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 20, E'And Menahem exacted the money of Israel, even of all the mighty men of wealth, of each man fifty shekels of silver, to give to the king of Assyria. So the king of Assyria turned back, and stayed not there in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 21, E'And the rest of the acts of Menahem, and all that he did, are they not written in the book of the chronicles of the kings of Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 22, E'And Menahem slept with his fathers; and Pekahiah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 23, E'In the fiftieth year of Azariah king of Judah Pekahiah the son of Menahem began to reign over Israel in Samaria, and reigned two years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 24, E'And he did that which was evil in the sight of the LORD: he departed not from the sins of Jeroboam the son of Nebat, who made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 25, E'But Pekah the son of Remaliah, a captain of his, conspired against him, and smote him in Samaria, in the palace of the kingâ€™s house, with Argob and Arieh, and with him fifty men of the Gileadites: and he killed him, and reigned in his room.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 26, E'And the rest of the acts of Pekahiah, and all that he did, behold, they are written in the book of the chronicles of the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 27, E'In the two and fiftieth year of Azariah king of Judah Pekah the son of Remaliah began to reign over Israel in Samaria, and reigned twenty years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 28, E'And he did that which was evil in the sight of the LORD: he departed not from the sins of Jeroboam the son of Nebat, who made Israel to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 29, E'In the days of Pekah king of Israel came Tiglathpileser king of Assyria, and took Ijon, and Abelbethmaachah, and Janoah, and Kedesh, and Hazor, and Gilead, and Galilee, all the land of Naphtali, and carried them captive to Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 30, E'And Hoshea the son of Elah made a conspiracy against Pekah the son of Remaliah, and smote him, and slew him, and reigned in his stead, in the twentieth year of Jotham the son of Uzziah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 31, E'And the rest of the acts of Pekah, and all that he did, behold, they are written in the book of the chronicles of the kings of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 32, E'In the second year of Pekah the son of Remaliah king of Israel began Jotham the son of Uzziah king of Judah to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 33, E'Five and twenty years old was he when he began to reign, and he reigned sixteen years in Jerusalem. And his motherâ€™s name was Jerusha, the daughter of Zadok.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 34, E'And he did that which was right in the sight of the LORD: he did according to all that his father Uzziah had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 35, E'Howbeit the high places were not removed: the people sacrificed and burned incense still in the high places. He built the higher gate of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 36, E'Now the rest of the acts of Jotham, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 37, E'In those days the LORD began to send against Judah Rezin the king of Syria, and Pekah the son of Remaliah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 15, 38, E'And Jotham slept with his fathers, and was buried with his fathers in the city of David his father: and Ahaz his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 1, E'In the seventeenth year of Pekah the son of Remaliah Ahaz the son of Jotham king of Judah began to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 2, E'Twenty years old was Ahaz when he began to reign, and reigned sixteen years in Jerusalem, and did not that which was right in the sight of the LORD his God, like David his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 3, E'But he walked in the way of the kings of Israel, yea, and made his son to pass through the fire, according to the abominations of the heathen, whom the LORD cast out from before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 4, E'And he sacrificed and burnt incense in the high places, and on the hills, and under every green tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 5, E'Then Rezin king of Syria and Pekah son of Remaliah king of Israel came up to Jerusalem to war: and they besieged Ahaz, but could not overcome him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 6, E'At that time Rezin king of Syria recovered Elath to Syria, and drave the Jews from Elath: and the Syrians came to Elath, and dwelt there unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 7, E'So Ahaz sent messengers to Tiglathpileser king of Assyria, saying, I am thy servant and thy son: come up, and save me out of the hand of the king of Syria, and out of the hand of the king of Israel, which rise up against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 8, E'And Ahaz took the silver and gold that was found in the house of the LORD, and in the treasures of the kingâ€™s house, and sent it for a present to the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 9, E'And the king of Assyria hearkened unto him: for the king of Assyria went up against Damascus, and took it, and carried the people of it captive to Kir, and slew Rezin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 10, E'And king Ahaz went to Damascus to meet Tiglathpileser king of Assyria, and saw an altar that was at Damascus: and king Ahaz sent to Urijah the priest the fashion of the altar, and the pattern of it, according to all the workmanship thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 11, E'And Urijah the priest built an altar according to all that king Ahaz had sent from Damascus: so Urijah the priest made it against king Ahaz came from Damascus.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 12, E'And when the king was come from Damascus, the king saw the altar: and the king approached to the altar, and offered thereon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 13, E'And he burnt his burnt offering and his meat offering, and poured his drink offering, and sprinkled the blood of his peace offerings, upon the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 14, E'And he brought also the brasen altar, which was before the LORD, from the forefront of the house, from between the altar and the house of the LORD, and put it on the north side of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 15, E'And king Ahaz commanded Urijah the priest, saying, Upon the great altar burn the morning burnt offering, and the evening meat offering, and the kingâ€™s burnt sacrifice, and his meat offering, with the burnt offering of all the people of the land, and their meat offering, and their drink offerings; and sprinkle upon it all the blood of the burnt offering, and all the blood of the sacrifice: and the brasen altar shall be for me to enquire by.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 16, E'Thus did Urijah the priest, according to all that king Ahaz commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 17, E'And king Ahaz cut off the borders of the bases, and removed the laver from off them; and took down the sea from off the brasen oxen that were under it, and put it upon a pavement of stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 18, E'And the covert for the sabbath that they had built in the house, and the kingâ€™s entry without, turned he from the house of the LORD for the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 19, E'Now the rest of the acts of Ahaz which he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 16, 20, E'And Ahaz slept with his fathers, and was buried with his fathers in the city of David: and Hezekiah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 1, E'In the twelfth year of Ahaz king of Judah began Hoshea the son of Elah to reign in Samaria over Israel nine years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 2, E'And he did that which was evil in the sight of the LORD, but not as the kings of Israel that were before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 3, E'Against him came up Shalmaneser king of Assyria; and Hoshea became his servant, and gave him presents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 4, E'And the king of Assyria found conspiracy in Hoshea: for he had sent messengers to So king of Egypt, and brought no present to the king of Assyria, as he had done year by year: therefore the king of Assyria shut him up, and bound him in prison.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 5, E'Then the king of Assyria came up throughout all the land, and went up to Samaria, and besieged it three years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 6, E'In the ninth year of Hoshea the king of Assyria took Samaria, and carried Israel away into Assyria, and placed them in Halah and in Habor by the river of Gozan, and in the cities of the Medes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 7, E'For so it was, that the children of Israel had sinned against the LORD their God, which had brought them up out of the land of Egypt, from under the hand of Pharaoh king of Egypt, and had feared other gods,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 8, E'And walked in the statutes of the heathen, whom the LORD cast out from before the children of Israel, and of the kings of Israel, which they had made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 9, E'And the children of Israel did secretly those things that were not right against the LORD their God, and they built them high places in all their cities, from the tower of the watchmen to the fenced city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 10, E'And they set them up images and groves in every high hill, and under every green tree:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 11, E'And there they burnt incense in all the high places, as did the heathen whom the LORD carried away before them; and wrought wicked things to provoke the LORD to anger:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 12, E'For they served idols, whereof the LORD had said unto them, Ye shall not do this thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 13, E'Yet the LORD testified against Israel, and against Judah, by all the prophets, and by all the seers, saying, Turn ye from your evil ways, and keep my commandments and my statutes, according to all the law which I commanded your fathers, and which I sent to you by my servants the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 14, E'Notwithstanding they would not hear, but hardened their necks, like to the neck of their fathers, that did not believe in the LORD their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 15, E'And they rejected his statutes, and his covenant that he made with their fathers, and his testimonies which he testified against them; and they followed vanity, and became vain, and went after the heathen that were round about them, concerning whom the LORD had charged them, that they should not do like them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 16, E'And they left all the commandments of the LORD their God, and made them molten images, even two calves, and made a grove, and worshipped all the host of heaven, and served Baal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 17, E'And they caused their sons and their daughters to pass through the fire, and used divination and enchantments, and sold themselves to do evil in the sight of the LORD, to provoke him to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 18, E'Therefore the LORD was very angry with Israel, and removed them out of his sight: there was none left but the tribe of Judah only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 19, E'Also Judah kept not the commandments of the LORD their God, but walked in the statutes of Israel which they made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 20, E'And the LORD rejected all the seed of Israel, and afflicted them, and delivered them into the hand of spoilers, until he had cast them out of his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 21, E'For he rent Israel from the house of David; and they made Jeroboam the son of Nebat king: and Jeroboam drave Israel from following the LORD, and made them sin a great sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 22, E'For the children of Israel walked in all the sins of Jeroboam which he did; they departed not from them;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 23, E'Until the LORD removed Israel out of his sight, as he had said by all his servants the prophets. So was Israel carried away out of their own land to Assyria unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 24, E'And the king of Assyria brought men from Babylon, and from Cuthah, and from Ava, and from Hamath, and from Sepharvaim, and placed them in the cities of Samaria instead of the children of Israel: and they possessed Samaria, and dwelt in the cities thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 25, E'And so it was at the beginning of their dwelling there, that they feared not the LORD: therefore the LORD sent lions among them, which slew some of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 26, E'Wherefore they spake to the king of Assyria, saying, The nations which thou hast removed, and placed in the cities of Samaria, know not the manner of the God of the land: therefore he hath sent lions among them, and, behold, they slay them, because they know not the manner of the God of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 27, E'Then the king of Assyria commanded, saying, Carry thither one of the priests whom ye brought from thence; and let them go and dwell there, and let him teach them the manner of the God of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 28, E'Then one of the priests whom they had carried away from Samaria came and dwelt in Bethel, and taught them how they should fear the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 29, E'Howbeit every nation made gods of their own, and put them in the houses of the high places which the Samaritans had made, every nation in their cities wherein they dwelt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 30, E'And the men of Babylon made Succothbenoth, and the men of Cuth made Nergal, and the men of Hamath made Ashima,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 31, E'And the Avites made Nibhaz and Tartak, and the Sepharvites burnt their children in fire to Adrammelech and Anammelech, the gods of Sepharvaim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 32, E'So they feared the LORD, and made unto themselves of the lowest of them priests of the high places, which sacrificed for them in the houses of the high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 33, E'They feared the LORD, and served their own gods, after the manner of the nations whom they carried away from thence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 34, E'Unto this day they do after the former manners: they fear not the LORD, neither do they after their statutes, or after their ordinances, or after the law and commandment which the LORD commanded the children of Jacob, whom he named Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 35, E'With whom the LORD had made a covenant, and charged them, saying, Ye shall not fear other gods, nor bow yourselves to them, nor serve them, nor sacrifice to them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 36, E'But the LORD, who brought you up out of the land of Egypt with great power and a stretched out arm, him shall ye fear, and him shall ye worship, and to him shall ye do sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 37, E'And the statutes, and the ordinances, and the law, and the commandment, which he wrote for you, ye shall observe to do for evermore; and ye shall not fear other gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 38, E'And the covenant that I have made with you ye shall not forget; neither shall ye fear other gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 39, E'But the LORD your God ye shall fear; and he shall deliver you out of the hand of all your enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 40, E'Howbeit they did not hearken, but they did after their former manner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 17, 41, E'So these nations feared the LORD, and served their graven images, both their children, and their childrenâ€™s children: as did their fathers, so do they unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 1, E'Now it came to pass in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 2, E'Twenty and five years old was he when he began to reign; and he reigned twenty and nine years in Jerusalem. His motherâ€™s name also was Abi, the daughter of Zachariah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 3, E'And he did that which was right in the sight of the LORD, according to all that David his father did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 4, E'He removed the high places, and brake the images, and cut down the groves, and brake in pieces the brasen serpent that Moses had made: for unto those days the children of Israel did burn incense to it: and he called it Nehushtan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 5, E'He trusted in the LORD God of Israel; so that after him was none like him among all the kings of Judah, nor any that were before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 6, E'For he clave to the LORD, and departed not from following him, but kept his commandments, which the LORD commanded Moses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 7, E'And the LORD was with him; and he prospered whithersoever he went forth: and he rebelled against the king of Assyria, and served him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 8, E'He smote the Philistines, even unto Gaza, and the borders thereof, from the tower of the watchmen to the fenced city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 9, E'And it came to pass in the fourth year of king Hezekiah, which was the seventh year of Hoshea son of Elah king of Israel, that Shalmaneser king of Assyria came up against Samaria, and besieged it.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 10, E'And at the end of three years they took it: even in the sixth year of Hezekiah, that is the ninth year of Hoshea king of Israel, Samaria was taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 11, E'And the king of Assyria did carry away Israel unto Assyria, and put them in Halah and in Habor by the river of Gozan, and in the cities of the Medes:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 12, E'Because they obeyed not the voice of the LORD their God, but transgressed his covenant, and all that Moses the servant of the LORD commanded, and would not hear them, nor do them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 13, E'Now in the fourteenth year of king Hezekiah did Sennacherib king of Assyria come up against all the fenced cities of Judah, and took them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 14, E'And Hezekiah king of Judah sent to the king of Assyria to Lachish, saying, I have offended; return from me: that which thou puttest on me will I bear. And the king of Assyria appointed unto Hezekiah king of Judah three hundred talents of silver and thirty talents of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 15, E'And Hezekiah gave him all the silver that was found in the house of the LORD, and in the treasures of the kingâ€™s house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 16, E'At that time did Hezekiah cut off the gold from the doors of the temple of the LORD, and from the pillars which Hezekiah king of Judah had overlaid, and gave it to the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 17, E'And the king of Assyria sent Tartan and Rabsaris and Rabshakeh from Lachish to king Hezekiah with a great host against Jerusalem. And they went up and came to Jerusalem. And when they were come up, they came and stood by the conduit of the upper pool, which is in the highway of the fullerâ€™s field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 18, E'And when they had called to the king, there came out to them Eliakim the son of Hilkiah, which was over the household, and Shebna the scribe, and Joah the son of Asaph the recorder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 19, E'And Rabshakeh said unto them, Speak ye now to Hezekiah, Thus saith the great king, the king of Assyria, What confidence is this wherein thou trustest?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 20, E'Thou sayest, (but they are but vain words,) I have counsel and strength for the war. Now on whom dost thou trust, that thou rebellest against me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 21, E'Now, behold, thou trustest upon the staff of this bruised reed, even upon Egypt, on which if a man lean, it will go into his hand, and pierce it: so is Pharaoh king of Egypt unto all that trust on him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 22, E'But if ye say unto me, We trust in the LORD our God: is not that he, whose high places and whose altars Hezekiah hath taken away, and hath said to Judah and Jerusalem, Ye shall worship before this altar in Jerusalem?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 23, E'Now therefore, I pray thee, give pledges to my lord the king of Assyria, and I will deliver thee two thousand horses, if thou be able on thy part to set riders upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 24, E'How then wilt thou turn away the face of one captain of the least of my masterâ€™s servants, and put thy trust on Egypt for chariots and for horsemen?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 25, E'Am I now come up without the LORD against this place to destroy it? The LORD said to me, Go up against this land, and destroy it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 26, E'Then said Eliakim the son of Hilkiah, and Shebna, and Joah, unto Rabshakeh, Speak, I pray thee, to thy servants in the Syrian language; for we understand it: and talk not with us in the Jewsâ€™ language in the ears of the people that are on the wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 27, E'But Rabshakeh said unto them, Hath my master sent me to thy master, and to thee, to speak these words? hath he not sent me to the men which sit on the wall, that they may eat their own dung, and drink their own piss with you?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 28, E'Then Rabshakeh stood and cried with a loud voice in the Jewsâ€™ language, and spake, saying, Hear the word of the great king, the king of Assyria:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 29, E'Thus saith the king, Let not Hezekiah deceive you: for he shall not be able to deliver you out of his hand:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 30, E'Neither let Hezekiah make you trust in the LORD, saying, The LORD will surely deliver us, and this city shall not be delivered into the hand of the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 31, E'Hearken not to Hezekiah: for thus saith the king of Assyria, Make an agreement with me by a present, and come out to me, and then eat ye every man of his own vine, and every one of his fig tree, and drink ye every one the waters of his cistern:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 32, E'Until I come and take you away to a land like your own land, a land of corn and wine, a land of bread and vineyards, a land of oil olive and of honey, that ye may live, and not die: and hearken not unto Hezekiah, when he persuadeth you, saying, The LORD will deliver us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 33, E'Hath any of the gods of the nations delivered at all his land out of the hand of the king of Assyria?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 34, E'Where are the gods of Hamath, and of Arpad? where are the gods of Sepharvaim, Hena, and Ivah? have they delivered Samaria out of mine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 35, E'Who are they among all the gods of the countries, that have delivered their country out of mine hand, that the LORD should deliver Jerusalem out of mine hand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 36, E'But the people held their peace, and answered him not a word: for the kingâ€™s commandment was, saying, Answer him not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 18, 37, E'Then came Eliakim the son of Hilkiah, which was over the household, and Shebna the scribe, and Joah the son of Asaph the recorder, to Hezekiah with their clothes rent, and told him the words of Rabshakeh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 1, E'And it came to pass, when king Hezekiah heard it, that he rent his clothes, and covered himself with sackcloth, and went into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 2, E'And he sent Eliakim, which was over the household, and Shebna the scribe, and the elders of the priests, covered with sackcloth, to Isaiah the prophet the son of Amoz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 3, E'And they said unto him, Thus saith Hezekiah, This day is a day of trouble, and of rebuke, and blasphemy; for the children are come to the birth, and there is not strength to bring forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 4, E'It may be the LORD thy God will hear all the words of Rabshakeh, whom the king of Assyria his master hath sent to reproach the living God; and will reprove the words which the LORD thy God hath heard: wherefore lift up thy prayer for the remnant that are left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 5, E'So the servants of king Hezekiah came to Isaiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 6, E'And Isaiah said unto them, Thus shall ye say to your master, Thus saith the LORD, Be not afraid of the words which thou hast heard, with which the servants of the king of Assyria have blasphemed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 7, E'Behold, I will send a blast upon him, and he shall hear a rumour, and shall return to his own land; and I will cause him to fall by the sword in his own land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 8, E'So Rabshakeh returned, and found the king of Assyria warring against Libnah: for he had heard that he was departed from Lachish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 9, E'And when he heard say of Tirhakah king of Ethiopia, Behold, he is come out to fight against thee: he sent messengers again unto Hezekiah, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 10, E'Thus shall ye speak to Hezekiah king of Judah, saying, Let not thy God in whom thou trustest deceive thee, saying, Jerusalem shall not be delivered into the hand of the king of Assyria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 11, E'Behold, thou hast heard what the kings of Assyria have done to all lands, by destroying them utterly: and shalt thou be delivered?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 12, E'Have the gods of the nations delivered them which my fathers have destroyed; as Gozan, and Haran, and Rezeph, and the children of Eden which were in Thelasar?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 13, E'Where is the king of Hamath, and the king of Arpad, and the king of the city of Sepharvaim, of Hena, and Ivah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 14, E'And Hezekiah received the letter of the hand of the messengers, and read it: and Hezekiah went up into the house of the LORD, and spread it before the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 15, E'And Hezekiah prayed before the LORD, and said, O LORD God of Israel, which dwellest between the cherubims, thou art the God, even thou alone, of all the kingdoms of the earth; thou hast made heaven and earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 16, E'LORD, bow down thine ear, and hear: open, LORD, thine eyes, and see: and hear the words of Sennacherib, which hath sent him to reproach the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 17, E'Of a truth, LORD, the kings of Assyria have destroyed the nations and their lands,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 18, E'And have cast their gods into the fire: for they were no gods, but the work of menâ€™s hands, wood and stone: therefore they have destroyed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 19, E'Now therefore, O LORD our God, I beseech thee, save thou us out of his hand, that all the kingdoms of the earth may know that thou art the LORD God, even thou only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 20, E'Then Isaiah the son of Amoz sent to Hezekiah, saying, Thus saith the LORD God of Israel, That which thou hast prayed to me against Sennacherib king of Assyria I have heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 21, E'This is the word that the LORD hath spoken concerning him; The virgin the daughter of Zion hath despised thee, and laughed thee to scorn; the daughter of Jerusalem hath shaken her head at thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 22, E'Whom hast thou reproached and blasphemed? and against whom hast thou exalted thy voice, and lifted up thine eyes on high? even against the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 23, E'By thy messengers thou hast reproached the LORD, and hast said, With the multitude of my chariots I am come up to the height of the mountains, to the sides of Lebanon, and will cut down the tall cedar trees thereof, and the choice fir trees thereof: and I will enter into the lodgings of his borders, and into the forest of his Carmel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 24, E'I have digged and drunk strange waters, and with the sole of my feet have I dried up all the rivers of besieged places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 25, E'Hast thou not heard long ago how I have done it, and of ancient times that I have formed it? now have I brought it to pass, that thou shouldest be to lay waste fenced cities into ruinous heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 26, E'Therefore their inhabitants were of small power, they were dismayed and confounded; they were as the grass of the field, and as the green herb, as the grass on the house tops, and as corn blasted before it be grown up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 27, E'But I know thy abode, and thy going out, and thy coming in, and thy rage against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 28, E'Because thy rage against me and thy tumult is come up into mine ears, therefore I will put my hook in thy nose, and my bridle in thy lips, and I will turn thee back by the way by which thou camest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 29, E'And this shall be a sign unto thee, Ye shall eat this year such things as grow of themselves, and in the second year that which springeth of the same; and in the third year sow ye, and reap, and plant vineyards, and eat the fruits thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 30, E'And the remnant that is escaped of the house of Judah shall yet again take root downward, and bear fruit upward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 31, E'For out of Jerusalem shall go forth a remnant, and they that escape out of mount Zion: the zeal of the LORD of hosts shall do this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 32, E'Therefore thus saith the LORD concerning the king of Assyria, He shall not come into this city, nor shoot an arrow there, nor come before it with shield, nor cast a bank against it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 33, E'By the way that he came, by the same shall he return, and shall not come into this city, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 34, E'For I will defend this city, to save it, for mine own sake, and for my servant Davidâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 35, E'And it came to pass that night, that the angel of the LORD went out, and smote in the camp of the Assyrians an hundred fourscore and five thousand: and when they arose early in the morning, behold, they were all dead corpses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 36, E'So Sennacherib king of Assyria departed, and went and returned, and dwelt at Nineveh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 19, 37, E'And it came to pass, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer his sons smote him with the sword: and they escaped into the land of Armenia. And Esarhaddon his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 1, E'In those days was Hezekiah sick unto death. And the prophet Isaiah the son of Amoz came to him, and said unto him, Thus saith the LORD, Set thine house in order; for thou shalt die, and not live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 2, E'Then he turned his face to the wall, and prayed unto the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 3, E'I beseech thee, O LORD, remember now how I have walked before thee in truth and with a perfect heart, and have done that which is good in thy sight. And Hezekiah wept sore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 4, E'And it came to pass, afore Isaiah was gone out into the middle court, that the word of the LORD came to him, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 5, E'Turn again, and tell Hezekiah the captain of my people, Thus saith the LORD, the God of David thy father, I have heard thy prayer, I have seen thy tears: behold, I will heal thee: on the third day thou shalt go up unto the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 6, E'And I will add unto thy days fifteen years; and I will deliver thee and this city out of the hand of the king of Assyria; and I will defend this city for mine own sake, and for my servant Davidâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 7, E'And Isaiah said, Take a lump of figs. And they took and laid it on the boil, and he recovered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 8, E'And Hezekiah said unto Isaiah, What shall be the sign that the LORD will heal me, and that I shall go up into the house of the LORD the third day?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 9, E'And Isaiah said, This sign shalt thou have of the LORD, that the LORD will do the thing that he hath spoken: shall the shadow go forward ten degrees, or go back ten degrees?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 10, E'And Hezekiah answered, It is a light thing for the shadow to go down ten degrees: nay, but let the shadow return backward ten degrees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 11, E'And Isaiah the prophet cried unto the LORD: and he brought the shadow ten degrees backward, by which it had gone down in the dial of Ahaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 12, E'At that time Berodachbaladan, the son of Baladan, king of Babylon, sent letters and a present unto Hezekiah: for he had heard that Hezekiah had been sick.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 13, E'And Hezekiah hearkened unto them, and shewed them all the house of his precious things, the silver, and the gold, and the spices, and the precious ointment, and all the house of his armour, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah shewed them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 14, E'Then came Isaiah the prophet unto king Hezekiah, and said unto him, What said these men? and from whence came they unto thee? And Hezekiah said, They are come from a far country, even from Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 15, E'And he said, What have they seen in thine house? And Hezekiah answered, All the things that are in mine house have they seen: there is nothing among my treasures that I have not shewed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 16, E'And Isaiah said unto Hezekiah, Hear the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 17, E'Behold, the days come, that all that is in thine house, and that which thy fathers have laid up in store unto this day, shall be carried into Babylon: nothing shall be left, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 18, E'And of thy sons that shall issue from thee, which thou shalt beget, shall they take away; and they shall be eunuchs in the palace of the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 19, E'Then said Hezekiah unto Isaiah, Good is the word of the LORD which thou hast spoken. And he said, Is it not good, if peace and truth be in my days?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 20, E'And the rest of the acts of Hezekiah, and all his might, and how he made a pool, and a conduit, and brought water into the city, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 20, 21, E'And Hezekiah slept with his fathers: and Manasseh his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 1, E'Manasseh was twelve years old when he began to reign, and reigned fifty and five years in Jerusalem. And his motherâ€™s name was Hephzibah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 2, E'And he did that which was evil in the sight of the LORD, after the abominations of the heathen, whom the LORD cast out before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 3, E'For he built up again the high places which Hezekiah his father had destroyed; and he reared up altars for Baal, and made a grove, as did Ahab king of Israel; and worshipped all the host of heaven, and served them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 4, E'And he built altars in the house of the LORD, of which the LORD said, In Jerusalem will I put my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 5, E'And he built altars for all the host of heaven in the two courts of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 6, E'And he made his son pass through the fire, and observed times, and used enchantments, and dealt with familiar spirits and wizards: he wrought much wickedness in the sight of the LORD, to provoke him to anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 7, E'And he set a graven image of the grove that he had made in the house, of which the LORD said to David, and to Solomon his son, In this house, and in Jerusalem, which I have chosen out of all tribes of Israel, will I put my name for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 8, E'Neither will I make the feet of Israel move any more out of the land which I gave their fathers; only if they will observe to do according to all that I have commanded them, and according to all the law that my servant Moses commanded them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 9, E'But they hearkened not: and Manasseh seduced them to do more evil than did the nations whom the LORD destroyed before the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 10, E'And the LORD spake by his servants the prophets, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 11, E'Because Manasseh king of Judah hath done these abominations, and hath done wickedly above all that the Amorites did, which were before him, and hath made Judah also to sin with his idols:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 12, E'Therefore thus saith the LORD God of Israel, Behold, I am bringing such evil upon Jerusalem and Judah, that whosoever heareth of it, both his ears shall tingle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 13, E'And I will stretch over Jerusalem the line of Samaria, and the plummet of the house of Ahab: and I will wipe Jerusalem as a man wipeth a dish, wiping it, and turning it upside down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 14, E'And I will forsake the remnant of mine inheritance, and deliver them into the hand of their enemies; and they shall become a prey and a spoil to all their enemies;')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 15, E'Because they have done that which was evil in my sight, and have provoked me to anger, since the day their fathers came forth out of Egypt, even unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 16, E'Moreover Manasseh shed innocent blood very much, till he had filled Jerusalem from one end to another; beside his sin wherewith he made Judah to sin, in doing that which was evil in the sight of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 17, E'Now the rest of the acts of Manasseh, and all that he did, and his sin that he sinned, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 18, E'And Manasseh slept with his fathers, and was buried in the garden of his own house, in the garden of Uzza: and Amon his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 19, E'Amon was twenty and two years old when he began to reign, and he reigned two years in Jerusalem. And his motherâ€™s name was Meshullemeth, the daughter of Haruz of Jotbah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 20, E'And he did that which was evil in the sight of the LORD, as his father Manasseh did.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 21, E'And he walked in all the way that his father walked in, and served the idols that his father served, and worshipped them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 22, E'And he forsook the LORD God of his fathers, and walked not in the way of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 23, E'And the servants of Amon conspired against him, and slew the king in his own house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 24, E'And the people of the land slew all them that had conspired against king Amon; and the people of the land made Josiah his son king in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 25, E'Now the rest of the acts of Amon which he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 21, 26, E'And he was buried in his sepulchre in the garden of Uzza: and Josiah his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 1, E'Josiah was eight years old when he began to reign, and he reigned thirty and one years in Jerusalem. And his motherâ€™s name was Jedidah, the daughter of Adaiah of Boscath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 2, E'And he did that which was right in the sight of the LORD, and walked in all the way of David his father, and turned not aside to the right hand or to the left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 3, E'And it came to pass in the eighteenth year of king Josiah, that the king sent Shaphan the son of Azaliah, the son of Meshullam, the scribe, to the house of the LORD, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 4, E'Go up to Hilkiah the high priest, that he may sum the silver which is brought into the house of the LORD, which the keepers of the door have gathered of the people:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 5, E'And let them deliver it into the hand of the doers of the work, that have the oversight of the house of the LORD: and let them give it to the doers of the work which is in the house of the LORD, to repair the breaches of the house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 6, E'Unto carpenters, and builders, and masons, and to buy timber and hewn stone to repair the house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 7, E'Howbeit there was no reckoning made with them of the money that was delivered into their hand, because they dealt faithfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 8, E'And Hilkiah the high priest said unto Shaphan the scribe, I have found the book of the law in the house of the LORD. And Hilkiah gave the book to Shaphan, and he read it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 9, E'And Shaphan the scribe came to the king, and brought the king word again, and said, Thy servants have gathered the money that was found in the house, and have delivered it into the hand of them that do the work, that have the oversight of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 10, E'And Shaphan the scribe shewed the king, saying, Hilkiah the priest hath delivered me a book. And Shaphan read it before the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 11, E'And it came to pass, when the king had heard the words of the book of the law, that he rent his clothes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 12, E'And the king commanded Hilkiah the priest, and Ahikam the son of Shaphan, and Achbor the son of Michaiah, and Shaphan the scribe, and Asahiah a servant of the kingâ€™s, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 13, E'Go ye, enquire of the LORD for me, and for the people, and for all Judah, concerning the words of this book that is found: for great is the wrath of the LORD that is kindled against us, because our fathers have not hearkened unto the words of this book, to do according unto all that which is written concerning us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 14, E'So Hilkiah the priest, and Ahikam, and Achbor, and Shaphan, and Asahiah, went unto Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe; (now she dwelt in Jerusalem in the college;) and they communed with her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 15, E'And she said unto them, Thus saith the LORD God of Israel, Tell the man that sent you to me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 16, E'Thus saith the LORD, Behold, I will bring evil upon this place, and upon the inhabitants thereof, even all the words of the book which the king of Judah hath read:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 17, E'Because they have forsaken me, and have burned incense unto other gods, that they might provoke me to anger with all the works of their hands; therefore my wrath shall be kindled against this place, and shall not be quenched.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 18, E'But to the king of Judah which sent you to enquire of the LORD, thus shall ye say to him, Thus saith the LORD God of Israel, As touching the words which thou hast heard;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 19, E'Because thine heart was tender, and thou hast humbled thyself before the LORD, when thou heardest what I spake against this place, and against the inhabitants thereof, that they should become a desolation and a curse, and hast rent thy clothes, and wept before me; I also have heard thee, saith the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 22, 20, E'Behold therefore, I will gather thee unto thy fathers, and thou shalt be gathered into thy grave in peace; and thine eyes shall not see all the evil which I will bring upon this place. And they brought the king word again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 1, E'And the king sent, and they gathered unto him all the elders of Judah and of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 2, E'And the king went up into the house of the LORD, and all the men of Judah and all the inhabitants of Jerusalem with him, and the priests, and the prophets, and all the people, both small and great: and he read in their ears all the words of the book of the covenant which was found in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 3, E'And the king stood by a pillar, and made a covenant before the LORD, to walk after the LORD, and to keep his commandments and his testimonies and his statutes with all their heart and all their soul, to perform the words of this covenant that were written in this book. And all the people stood to the covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 4, E'And the king commanded Hilkiah the high priest, and the priests of the second order, and the keepers of the door, to bring forth out of the temple of the LORD all the vessels that were made for Baal, and for the grove, and for all the host of heaven: and he burned them without Jerusalem in the fields of Kidron, and carried the ashes of them unto Bethel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 5, E'And he put down the idolatrous priests, whom the kings of Judah had ordained to burn incense in the high places in the cities of Judah, and in the places round about Jerusalem; them also that burned incense unto Baal, to the sun, and to the moon, and to the planets, and to all the host of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 6, E'And he brought out the grove from the house of the LORD, without Jerusalem, unto the brook Kidron, and burned it at the brook Kidron, and stamped it small to powder, and cast the powder thereof upon the graves of the children of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 7, E'And he brake down the houses of the sodomites, that were by the house of the LORD, where the women wove hangings for the grove.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 8, E'And he brought all the priests out of the cities of Judah, and defiled the high places where the priests had burned incense, from Geba to Beersheba, and brake down the high places of the gates that were in the entering in of the gate of Joshua the governor of the city, which were on a manâ€™s left hand at the gate of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 9, E'Nevertheless the priests of the high places came not up to the altar of the LORD in Jerusalem, but they did eat of the unleavened bread among their brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 10, E'And he defiled Topheth, which is in the valley of the children of Hinnom, that no man might make his son or his daughter to pass through the fire to Molech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 11, E'And he took away the horses that the kings of Judah had given to the sun, at the entering in of the house of the LORD, by the chamber of Nathanmelech the chamberlain, which was in the suburbs, and burned the chariots of the sun with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 12, E'And the altars that were on the top of the upper chamber of Ahaz, which the kings of Judah had made, and the altars which Manasseh had made in the two courts of the house of the LORD, did the king beat down, and brake them down from thence, and cast the dust of them into the brook Kidron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 13, E'And the high places that were before Jerusalem, which were on the right hand of the mount of corruption, which Solomon the king of Israel had builded for Ashtoreth the abomination of the Zidonians, and for Chemosh the abomination of the Moabites, and for Milcom the abomination of the children of Ammon, did the king defile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 14, E'And he brake in pieces the images, and cut down the groves, and filled their places with the bones of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 15, E'Moreover the altar that was at Bethel, and the high place which Jeroboam the son of Nebat, who made Israel to sin, had made, both that altar and the high place he brake down, and burned the high place, and stamped it small to powder, and burned the grove.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 16, E'And as Josiah turned himself, he spied the sepulchres that were there in the mount, and sent, and took the bones out of the sepulchres, and burned them upon the altar, and polluted it, according to the word of the LORD which the man of God proclaimed, who proclaimed these words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 17, E'Then he said, What title is that that I see? And the men of the city told him, It is the sepulchre of the man of God, which came from Judah, and proclaimed these things that thou hast done against the altar of Bethel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 18, E'And he said, Let him alone; let no man move his bones. So they let his bones alone, with the bones of the prophet that came out of Samaria.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 19, E'And all the houses also of the high places that were in the cities of Samaria, which the kings of Israel had made to provoke the Lord to anger, Josiah took away, and did to them according to all the acts that he had done in Bethel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 20, E'And he slew all the priests of the high places that were there upon the altars, and burned menâ€™s bones upon them, and returned to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 21, E'And the king commanded all the people, saying, Keep the passover unto the LORD your God, as it is written in the book of this covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 22, E'Surely there was not holden such a passover from the days of the judges that judged Israel, nor in all the days of the kings of Israel, nor of the kings of Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 23, E'But in the eighteenth year of king Josiah, wherein this passover was holden to the LORD in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 24, E'Moreover the workers with familiar spirits, and the wizards, and the images, and the idols, and all the abominations that were spied in the land of Judah and in Jerusalem, did Josiah put away, that he might perform the words of the law which were written in the book that Hilkiah the priest found in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 25, E'And like unto him was there no king before him, that turned to the LORD with all his heart, and with all his soul, and with all his might, according to all the law of Moses; neither after him arose there any like him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 26, E'Notwithstanding the LORD turned not from the fierceness of his great wrath, wherewith his anger was kindled against Judah, because of all the provocations that Manasseh had provoked him withal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 27, E'And the LORD said, I will remove Judah also out of my sight, as I have removed Israel, and will cast off this city Jerusalem which I have chosen, and the house of which I said, My name shall be there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 28, E'Now the rest of the acts of Josiah, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 29, E'In his days Pharaohnechoh king of Egypt went up against the king of Assyria to the river Euphrates: and king Josiah went against him; and he slew him at Megiddo, when he had seen him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 30, E'And his servants carried him in a chariot dead from Megiddo, and brought him to Jerusalem, and buried him in his own sepulchre. And the people of the land took Jehoahaz the son of Josiah, and anointed him, and made him king in his fatherâ€™s stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 31, E'Jehoahaz was twenty and three years old when he began to reign; and he reigned three months in Jerusalem. And his motherâ€™s name was Hamutal, the daughter of Jeremiah of Libnah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 32, E'And he did that which was evil in the sight of the LORD, according to all that his fathers had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 33, E'And Pharaohnechoh put him in bands at Riblah in the land of Hamath, that he might not reign in Jerusalem; and put the land to a tribute of an hundred talents of silver, and a talent of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 34, E'And Pharaohnechoh made Eliakim the son of Josiah king in the room of Josiah his father, and turned his name to Jehoiakim, and took Jehoahaz away: and he came to Egypt, and died there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 35, E'And Jehoiakim gave the silver and the gold to Pharaoh; but he taxed the land to give the money according to the commandment of Pharaoh: he exacted the silver and the gold of the people of the land, of every one according to his taxation, to give it unto Pharaohnechoh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 36, E'Jehoiakim was twenty and five years old when he began to reign; and he reigned eleven years in Jerusalem. And his motherâ€™s name was Zebudah, the daughter of Pedaiah of Rumah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 23, 37, E'And he did that which was evil in the sight of the LORD, according to all that his fathers had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 1, E'In his days Nebuchadnezzar king of Babylon came up, and Jehoiakim became his servant three years: then he turned and rebelled against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 2, E'And the LORD sent against him bands of the Chaldees, and bands of the Syrians, and bands of the Moabites, and bands of the children of Ammon, and sent them against Judah to destroy it, according to the word of the LORD, which he spake by his servants the prophets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 3, E'Surely at the commandment of the LORD came this upon Judah, to remove them out of his sight, for the sins of Manasseh, according to all that he did;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 4, E'And also for the innocent blood that he shed: for he filled Jerusalem with innocent blood; which the LORD would not pardon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 5, E'Now the rest of the acts of Jehoiakim, and all that he did, are they not written in the book of the chronicles of the kings of Judah?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 6, E'So Jehoiakim slept with his fathers: and Jehoiachin his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 7, E'And the king of Egypt came not again any more out of his land: for the king of Babylon had taken from the river of Egypt unto the river Euphrates all that pertained to the king of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 8, E'Jehoiachin was eighteen years old when he began to reign, and he reigned in Jerusalem three months. And his motherâ€™s name was Nehushta, the daughter of Elnathan of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 9, E'And he did that which was evil in the sight of the LORD, according to all that his father had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 10, E'At that time the servants of Nebuchadnezzar king of Babylon came up against Jerusalem, and the city was besieged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 11, E'And Nebuchadnezzar king of Babylon came against the city, and his servants did besiege it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 12, E'And Jehoiachin the king of Judah went out to the king of Babylon, he, and his mother, and his servants, and his princes, and his officers: and the king of Babylon took him in the eighth year of his reign.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 13, E'And he carried out thence all the treasures of the house of the LORD, and the treasures of the kingâ€™s house, and cut in pieces all the vessels of gold which Solomon king of Israel had made in the temple of the LORD, as the LORD had said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 14, E'And he carried away all Jerusalem, and all the princes, and all the mighty men of valour, even ten thousand captives, and all the craftsmen and smiths: none remained, save the poorest sort of the people of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 15, E'And he carried away Jehoiachin to Babylon, and the kingâ€™s mother, and the kingâ€™s wives, and his officers, and the mighty of the land, those carried he into captivity from Jerusalem to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 16, E'And all the men of might, even seven thousand, and craftsmen and smiths a thousand, all that were strong and apt for war, even them the king of Babylon brought captive to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 17, E'And the king of Babylon made Mattaniah his fatherâ€™s brother king in his stead, and changed his name to Zedekiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 18, E'Zedekiah was twenty and one years old when he began to reign, and he reigned eleven years in Jerusalem. And his motherâ€™s name was Hamutal, the daughter of Jeremiah of Libnah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 19, E'And he did that which was evil in the sight of the LORD, according to all that Jehoiakim had done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 24, 20, E'For through the anger of the LORD it came to pass in Jerusalem and Judah, until he had cast them out from his presence, that Zedekiah rebelled against the king of Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 1, E'And it came to pass in the ninth year of his reign, in the tenth month, in the tenth day of the month, that Nebuchadnezzar king of Babylon came, he, and all his host, against Jerusalem, and pitched against it; and they built forts against it round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 2, E'And the city was besieged unto the eleventh year of king Zedekiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 3, E'And on the ninth day of the fourth month the famine prevailed in the city, and there was no bread for the people of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 4, E'And the city was broken up, and all the men of war fled by night by the way of the gate between two walls, which is by the kingâ€™s garden: (now the Chaldees were against the city round about:) and the king went the way toward the plain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 5, E'And the army of the Chaldees pursued after the king, and overtook him in the plains of Jericho: and all his army were scattered from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 6, E'So they took the king, and brought him up to the king of Babylon to Riblah; and they gave judgment upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 7, E'And they slew the sons of Zedekiah before his eyes, and put out the eyes of Zedekiah, and bound him with fetters of brass, and carried him to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 8, E'And in the fifth month, on the seventh day of the month, which is the nineteenth year of king Nebuchadnezzar king of Babylon, came Nebuzaradan, captain of the guard, a servant of the king of Babylon, unto Jerusalem:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 9, E'And he burnt the house of the LORD, and the kingâ€™s house, and all the houses of Jerusalem, and every great manâ€™s house burnt he with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 10, E'And all the army of the Chaldees, that were with the captain of the guard, brake down the walls of Jerusalem round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 11, E'Now the rest of the people that were left in the city, and the fugitives that fell away to the king of Babylon, with the remnant of the multitude, did Nebuzaradan the captain of the guard carry away.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 12, E'But the captain of the guard left of the poor of the land to be vinedressers and husbandmen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 13, E'And the pillars of brass that were in the house of the LORD, and the bases, and the brasen sea that was in the house of the LORD, did the Chaldees break in pieces, and carried the brass of them to Babylon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 14, E'And the pots, and the shovels, and the snuffers, and the spoons, and all the vessels of brass wherewith they ministered, took they away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 15, E'And the firepans, and the bowls, and such things as were of gold, in gold, and of silver, in silver, the captain of the guard took away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 16, E'The two pillars, one sea, and the bases which Solomon had made for the house of the LORD; the brass of all these vessels was without weight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 17, E'The height of the one pillar was eighteen cubits, and the chapiter upon it was brass: and the height of the chapiter three cubits; and the wreathen work, and pomegranates upon the chapiter round about, all of brass: and like unto these had the second pillar with wreathen work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 18, E'And the captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the door:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 19, E'And out of the city he took an officer that was set over the men of war, and five men of them that were in the kingâ€™s presence, which were found in the city, and the principal scribe of the host, which mustered the people of the land, and threescore men of the people of the land that were found in the city:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 20, E'And Nebuzaradan captain of the guard took these, and brought them to the king of Babylon to Riblah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 21, E'And the king of Babylon smote them, and slew them at Riblah in the land of Hamath. So Judah was carried away out of their land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 22, E'And as for the people that remained in the land of Judah, whom Nebuchadnezzar king of Babylon had left, even over them he made Gedaliah the son of Ahikam, the son of Shaphan, ruler.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 23, E'And when all the captains of the armies, they and their men, heard that the king of Babylon had made Gedaliah governor, there came to Gedaliah to Mizpah, even Ishmael the son of Nethaniah, and Johanan the son of Careah, and Seraiah the son of Tanhumeth the Netophathite, and Jaazaniah the son of a Maachathite, they and their men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 24, E'And Gedaliah sware to them, and to their men, and said unto them, Fear not to be the servants of the Chaldees: dwell in the land, and serve the king of Babylon; and it shall be well with you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 25, E'But it came to pass in the seventh month, that Ishmael the son of Nethaniah, the son of Elishama, of the seed royal, came, and ten men with him, and smote Gedaliah, that he died, and the Jews and the Chaldees that were with him at Mizpah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 26, E'And all the people, both small and great, and the captains of the armies, arose, and came to Egypt: for they were afraid of the Chaldees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 27, E'And it came to pass in the seven and thirtieth year of the captivity of Jehoiachin king of Judah, in the twelfth month, on the seven and twentieth day of the month, that Evilmerodach king of Babylon in the year that he began to reign did lift up the head of Jehoiachin king of Judah out of prison;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 28, E'And he spake kindly to him, and set his throne above the throne of the kings that were with him in Babylon;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 29, E'And changed his prison garments: and he did eat bread continually before him all the days of his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4ede9fca-3e1a-496a-bfb7-d914f35ed231', 25, 30, E'And his allowance was a continual allowance given him of the king, a daily rate for every day, all the days of his life.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '2 Kings') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 1, E'Adam, Sheth, Enosh,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 2, E'Kenan, Mahalaleel, Jered,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 3, E'Henoch, Methuselah, Lamech,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 4, E'Noah, Shem, Ham, and Japheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 5, E'The sons of Japheth; Gomer, and Magog, and Madai, and Javan, and Tubal, and Meshech, and Tiras.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 6, E'And the sons of Gomer; Ashchenaz, and Riphath, and Togarmah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 7, E'And the sons of Javan; Elishah, and Tarshish, Kittim, and Dodanim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 8, E'The sons of Ham; Cush, and Mizraim, Put, and Canaan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 9, E'And the sons of Cush; Seba, and Havilah, and Sabta, and Raamah, and Sabtecha. And the sons of Raamah; Sheba, and Dedan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 10, E'And Cush begat Nimrod: he began to be mighty upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 11, E'And Mizraim begat Ludim, and Anamim, and Lehabim, and Naphtuhim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 12, E'And Pathrusim, and Casluhim, (of whom came the Philistines,) and Caphthorim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 13, E'And Canaan begat Zidon his firstborn, and Heth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 14, E'The Jebusite also, and the Amorite, and the Girgashite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 15, E'And the Hivite, and the Arkite, and the Sinite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 16, E'And the Arvadite, and the Zemarite, and the Hamathite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 17, E'The sons of Shem; Elam, and Asshur, and Arphaxad, and Lud, and Aram, and Uz, and Hul, and Gether, and Meshech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 18, E'And Arphaxad begat Shelah, and Shelah begat Eber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 19, E'And unto Eber were born two sons: the name of the one was Peleg; because in his days the earth was divided: and his brotherâ€™s name was Joktan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 20, E'And Joktan begat Almodad, and Sheleph, and Hazarmaveth, and Jerah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 21, E'Hadoram also, and Uzal, and Diklah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 22, E'And Ebal, and Abimael, and Sheba,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 23, E'And Ophir, and Havilah, and Jobab. All these were the sons of Joktan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 24, E'Shem, Arphaxad, Shelah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 25, E'Eber, Peleg, Reu,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 26, E'Serug, Nahor, Terah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 27, E'Abram; the same is Abraham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 28, E'The sons of Abraham; Isaac, and Ishmael.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 29, E'These are their generations: The firstborn of Ishmael, Nebaioth; then Kedar, and Adbeel, and Mibsam,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 30, E'Mishma, and Dumah, Massa, Hadad, and Tema,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 31, E'Jetur, Naphish, and Kedemah. These are the sons of Ishmael.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 32, E'Now the sons of Keturah, Abrahamâ€™s concubine: she bare Zimran, and Jokshan, and Medan, and Midian, and Ishbak, and Shuah. And the sons of Jokshan; Sheba, and Dedan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 33, E'And the sons of Midian; Ephah, and Epher, and Henoch, and Abida, and Eldaah. All these are the sons of Keturah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 34, E'And Abraham begat Isaac. The sons of Isaac; Esau and Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 35, E'The sons of Esau; Eliphaz, Reuel, and Jeush, and Jaalam, and Korah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 36, E'The sons of Eliphaz; Teman, and Omar, Zephi, and Gatam, Kenaz, and Timna, and Amalek.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 37, E'The sons of Reuel; Nahath, Zerah, Shammah, and Mizzah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 38, E'And the sons of Seir; Lotan, and Shobal, and Zibeon, and Anah, and Dishon, and Ezar, and Dishan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 39, E'And the sons of Lotan; Hori, and Homam: and Timna was Lotanâ€™s sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 40, E'The sons of Shobal; Alian, and Manahath, and Ebal, Shephi, and Onam. And the sons of Zibeon; Aiah, and Anah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 41, E'The sons of Anah; Dishon. And the sons of Dishon; Amram, and Eshban, and Ithran, and Cheran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 42, E'The sons of Ezer; Bilhan, and Zavan, and Jakan. The sons of Dishan; Uz, and Aran.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 43, E'Now these are the kings that reigned in the land of Edom before any king reigned over the children of Israel; Bela the son of Beor: and the name of his city was Dinhabah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 44, E'And when Bela was dead, Jobab the son of Zerah of Bozrah reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 45, E'And when Jobab was dead, Husham of the land of the Temanites reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 46, E'And when Husham was dead, Hadad the son of Bedad, which smote Midian in the field of Moab, reigned in his stead: and the name of his city was Avith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 47, E'And when Hadad was dead, Samlah of Masrekah reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 48, E'And when Samlah was dead, Shaul of Rehoboth by the river reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 49, E'And when Shaul was dead, Baalhanan the son of Achbor reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 50, E'And when Baalhanan was dead, Hadad reigned in his stead: and the name of his city was Pai; and his wifeâ€™s name was Mehetabel, the daughter of Matred, the daughter of Mezahab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 51, E'Hadad died also. And the dukes of Edom were; duke Timnah, duke Aliah, duke Jetheth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 52, E'Duke Aholibamah, duke Elah, duke Pinon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 53, E'Duke Kenaz, duke Teman, duke Mibzar,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 1, 54, E'Duke Magdiel, duke Iram. These are the dukes of Edom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 1, E'These are the sons of Israel; Reuben, Simeon, Levi, and Judah, Issachar, and Zebulun,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 2, E'Dan, Joseph, and Benjamin, Naphtali, Gad, and Asher.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 3, E'The sons of Judah; Er, and Onan, and Shelah: which three were born unto him of the daughter of Shua the Canaanitess. And Er, the firstborn of Judah, was evil in the sight of the LORD; and he slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 4, E'And Tamar his daughter in law bore him Pharez and Zerah. All the sons of Judah were five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 5, E'The sons of Pharez; Hezron, and Hamul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 6, E'And the sons of Zerah; Zimri, and Ethan, and Heman, and Calcol, and Dara: five of them in all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 7, E'And the sons of Carmi; Achar, the troubler of Israel, who transgressed in the thing accursed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 8, E'And the sons of Ethan; Azariah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 9, E'The sons also of Hezron, that were born unto him; Jerahmeel, and Ram, and Chelubai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 10, E'And Ram begat Amminadab; and Amminadab begat Nahshon, prince of the children of Judah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 11, E'And Nahshon begat Salma, and Salma begat Boaz,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 12, E'And Boaz begat Obed, and Obed begat Jesse,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 13, E'And Jesse begat his firstborn Eliab, and Abinadab the second, and Shimma the third,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 14, E'Nethaneel the fourth, Raddai the fifth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 15, E'Ozem the sixth, David the seventh:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 16, E'Whose sisters were Zeruiah, and Abigail. And the sons of Zeruiah; Abishai, and Joab, and Asahel, three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 17, E'And Abigail bare Amasa: and the father of Amasa was Jether the Ishmeelite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 18, E'And Caleb the son of Hezron begat children of Azubah his wife, and of Jerioth: her sons are these; Jesher, and Shobab, and Ardon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 19, E'And when Azubah was dead, Caleb took unto him Ephrath, which bare him Hur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 20, E'And Hur begat Uri, and Uri begat Bezaleel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 21, E'And afterward Hezron went in to the daughter of Machir the father of Gilead, whom he married when he was threescore years old; and she bare him Segub.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 22, E'And Segub begat Jair, who had three and twenty cities in the land of Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 23, E'And he took Geshur, and Aram, with the towns of Jair, from them, with Kenath, and the towns thereof, even threescore cities. All these belonged to the sons of Machir the father of Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 24, E'And after that Hezron was dead in Calebephratah, then Abiah Hezronâ€™s wife bare him Ashur the father of Tekoa.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 25, E'And the sons of Jerahmeel the firstborn of Hezron were, Ram the firstborn, and Bunah, and Oren, and Ozem, and Ahijah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 26, E'Jerahmeel had also another wife, whose name was Atarah; she was the mother of Onam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 27, E'And the sons of Ram the firstborn of Jerahmeel were, Maaz, and Jamin, and Eker.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 28, E'And the sons of Onam were, Shammai, and Jada. And the sons of Shammai; Nadab, and Abishur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 29, E'And the name of the wife of Abishur was Abihail, and she bare him Ahban, and Molid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 30, E'And the sons of Nadab; Seled, and Appaim: but Seled died without children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 31, E'And the sons of Appaim; Ishi. And the sons of Ishi; Sheshan. And the children of Sheshan; Ahlai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 32, E'And the sons of Jada the brother of Shammai; Jether, and Jonathan: and Jether died without children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 33, E'And the sons of Jonathan; Peleth, and Zaza. These were the sons of Jerahmeel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 34, E'Now Sheshan had no sons, but daughters. And Sheshan had a servant, an Egyptian, whose name was Jarha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 35, E'And Sheshan gave his daughter to Jarha his servant to wife; and she bare him Attai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 36, E'And Attai begat Nathan, and Nathan begat Zabad,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 37, E'And Zabad begat Ephlal, and Ephlal begat Obed,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 38, E'And Obed begat Jehu, and Jehu begat Azariah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 39, E'And Azariah begat Helez, and Helez begat Eleasah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 40, E'And Eleasah begat Sisamai, and Sisamai begat Shallum,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 41, E'And Shallum begat Jekamiah, and Jekamiah begat Elishama.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 42, E'Now the sons of Caleb the brother of Jerahmeel were, Mesha his firstborn, which was the father of Ziph; and the sons of Mareshah the father of Hebron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 43, E'And the sons of Hebron; Korah, and Tappuah, and Rekem, and Shema.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 44, E'And Shema begat Raham, the father of Jorkoam: and Rekem begat Shammai.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 45, E'And the son of Shammai was Maon: and Maon was the father of Bethzur.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 46, E'And Ephah, Calebâ€™s concubine, bare Haran, and Moza, and Gazez: and Haran begat Gazez.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 47, E'And the sons of Jahdai; Regem, and Jotham, and Gesham, and Pelet, and Ephah, and Shaaph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 48, E'Maachah, Calebâ€™s concubine, bare Sheber, and Tirhanah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 49, E'She bare also Shaaph the father of Madmannah, Sheva the father of Machbenah, and the father of Gibea: and the daughter of Caleb was Achsa.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 50, E'These were the sons of Caleb the son of Hur, the firstborn of Ephratah; Shobal the father of Kirjathjearim,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 51, E'Salma the father of Bethlehem, Hareph the father of Bethgader.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 52, E'And Shobal the father of Kirjathjearim had sons; Haroeh, and half of the Manahethites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 53, E'And the families of Kirjathjearim; the Ithrites, and the Puhites, and the Shumathites, and the Mishraites; of them came the Zareathites, and the Eshtaulites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 54, E'The sons of Salma; Bethlehem, and the Netophathites, Ataroth, the house of Joab, and half of the Manahethites, the Zorites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 2, 55, E'And the families of the scribes which dwelt at Jabez; the Tirathites, the Shimeathites, and Suchathites. These are the Kenites that came of Hemath, the father of the house of Rechab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 1, E'Now these were the sons of David, which were born unto him in Hebron; the firstborn Amnon, of Ahinoam the Jezreelitess; the second Daniel, of Abigail the Carmelitess:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 2, E'The third, Absalom the son of Maachah the daughter of Talmai king of Geshur: the fourth, Adonijah the son of Haggith:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 3, E'The fifth, Shephatiah of Abital: the sixth, Ithream by Eglah his wife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 4, E'These six were born unto him in Hebron; and there he reigned seven years and six months: and in Jerusalem he reigned thirty and three years.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 5, E'And these were born unto him in Jerusalem; Shimea, and Shobab, and Nathan, and Solomon, four, of Bathshua the daughter of Ammiel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 6, E'Ibhar also, and Elishama, and Eliphelet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 7, E'And Nogah, and Nepheg, and Japhia,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 8, E'And Elishama, and Eliada, and Eliphelet, nine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 9, E'These were all the sons of David, beside the sons of the concubines, and Tamar their sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 10, E'And Solomonâ€™s son was Rehoboam, Abia his son, Asa his son, Jehoshaphat his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 11, E'Joram his son, Ahaziah his son, Joash his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 12, E'Amaziah his son, Azariah his son, Jotham his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 13, E'Ahaz his son, Hezekiah his son, Manasseh his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 14, E'Amon his son, Josiah his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 15, E'And the sons of Josiah were, the firstborn Johanan, the second Jehoiakim, the third Zedekiah, the fourth Shallum.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 16, E'And the sons of Jehoiakim: Jeconiah his son, Zedekiah his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 17, E'And the sons of Jeconiah; Assir, Salathiel his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 18, E'Malchiram also, and Pedaiah, and Shenazar, Jecamiah, Hoshama, and Nedabiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 19, E'And the sons of Pedaiah were, Zerubbabel, and Shimei: and the sons of Zerubbabel; Meshullam, and Hananiah, and Shelomith their sister:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 20, E'And Hashubah, and Ohel, and Berechiah, and Hasadiah, Jushabhesed, five.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 21, E'And the sons of Hananiah; Pelatiah, and Jesaiah: the sons of Rephaiah, the sons of Arnan, the sons of Obadiah, the sons of Shechaniah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 22, E'And the sons of Shechaniah; Shemaiah: and the sons of Shemaiah; Hattush, and Igeal, and Bariah, and Neariah, and Shaphat, six.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 23, E'And the sons of Neariah; Elioenai, and Hezekiah, and Azrikam, three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 3, 24, E'And the sons of Elioenai were, Hodaiah, and Eliashib, and Pelaiah, and Akkub, and Johanan, and Dalaiah, and Anani, seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 1, E'The sons of Judah; Pharez, Hezron, and Carmi, and Hur, and Shobal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 2, E'And Reaiah the son of Shobal begat Jahath; and Jahath begat Ahumai, and Lahad. These are the families of the Zorathites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 3, E'And these were of the father of Etam; Jezreel, and Ishma, and Idbash: and the name of their sister was Hazelelponi:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 4, E'And Penuel the father of Gedor, and Ezer the father of Hushah. These are the sons of Hur, the firstborn of Ephratah, the father of Bethlehem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 5, E'And Ashur the father of Tekoa had two wives, Helah and Naarah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 6, E'And Naarah bare him Ahuzam, and Hepher, and Temeni, and Haahashtari. These were the sons of Naarah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 7, E'And the sons of Helah were, Zereth, and Jezoar, and Ethnan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 8, E'And Coz begat Anub, and Zobebah, and the families of Aharhel the son of Harum.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 9, E'And Jabez was more honourable than his brethren: and his mother called his name Jabez, saying, Because I bare him with sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 10, E'And Jabez called on the God of Israel, saying, Oh that thou wouldest bless me indeed, and enlarge my coast, and that thine hand might be with me, and that thou wouldest keep me from evil, that it may not grieve me! And God granted him that which he requested.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 11, E'And Chelub the brother of Shuah begat Mehir, which was the father of Eshton.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 12, E'And Eshton begat Bethrapha, and Paseah, and Tehinnah the father of Irnahash. These are the men of Rechah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 13, E'And the sons of Kenaz; Othniel, and Seraiah: and the sons of Othniel; Hathath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 14, E'And Meonothai begat Ophrah: and Seraiah begat Joab, the father of the valley of Charashim; for they were craftsmen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 15, E'And the sons of Caleb the son of Jephunneh; Iru, Elah, and Naam: and the sons of Elah, even Kenaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 16, E'And the sons of Jehaleleel; Ziph, and Ziphah, Tiria, and Asareel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 17, E'And the sons of Ezra were, Jether, and Mered, and Epher, and Jalon: and she bare Miriam, and Shammai, and Ishbah the father of Eshtemoa.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 18, E'And his wife Jehudijah bare Jered the father of Gedor, and Heber the father of Socho, and Jekuthiel the father of Zanoah. And these are the sons of Bithiah the daughter of Pharaoh, which Mered took.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 19, E'And the sons of his wife Hodiah the sister of Naham, the father of Keilah the Garmite, and Eshtemoa the Maachathite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 20, E'And the sons of Shimon were, Amnon, and Rinnah, Benhanan, and Tilon. And the sons of Ishi were, Zoheth, and Benzoheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 21, E'The sons of Shelah the son of Judah were, Er the father of Lecah, and Laadah the father of Mareshah, and the families of the house of them that wrought fine linen, of the house of Ashbea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 22, E'And Jokim, and the men of Chozeba, and Joash, and Saraph, who had the dominion in Moab, and Jashubilehem. And these are ancient things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 23, E'These were the potters, and those that dwelt among plants and hedges: there they dwelt with the king for his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 24, E'The sons of Simeon were, Nemuel, and Jamin, Jarib, Zerah, and Shaul:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 25, E'Shallum his son, Mibsam his son, Mishma his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 26, E'And the sons of Mishma; Hamuel his son, Zacchur his son, Shimei his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 27, E'And Shimei had sixteen sons and six daughters; but his brethren had not many children, neither did all their family multiply, like to the children of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 28, E'And they dwelt at Beersheba, and Moladah, and Hazarshual,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 29, E'And at Bilhah, and at Ezem, and at Tolad,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 30, E'And at Bethuel, and at Hormah, and at Ziklag,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 31, E'And at Bethmarcaboth, and Hazarsusim, and at Bethbirei, and at Shaaraim. These were their cities unto the reign of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 32, E'And their villages were, Etam, and Ain, Rimmon, and Tochen, and Ashan, five cities:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 33, E'And all their villages that were round about the same cities, unto Baal. These were their habitations, and their genealogy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 34, E'And Meshobab, and Jamlech, and Joshah, the son of Amaziah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 35, E'And Joel, and Jehu the son of Josibiah, the son of Seraiah, the son of Asiel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 36, E'And Elioenai, and Jaakobah, and Jeshohaiah, and Asaiah, and Adiel, and Jesimiel, and Benaiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 37, E'And Ziza the son of Shiphi, the son of Allon, the son of Jedaiah, the son of Shimri, the son of Shemaiah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 38, E'These mentioned by their names were princes in their families: and the house of their fathers increased greatly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 39, E'And they went to the entrance of Gedor, even unto the east side of the valley, to seek pasture for their flocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 40, E'And they found fat pasture and good, and the land was wide, and quiet, and peaceable; for they of Ham had dwelt there of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 41, E'And these written by name came in the days of Hezekiah king of Judah, and smote their tents, and the habitations that were found there, and destroyed them utterly unto this day, and dwelt in their rooms: because there was pasture there for their flocks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 42, E'And some of them, even of the sons of Simeon, five hundred men, went to mount Seir, having for their captains Pelatiah, and Neariah, and Rephaiah, and Uzziel, the sons of Ishi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 4, 43, E'And they smote the rest of the Amalekites that were escaped, and dwelt there unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 1, E'Now the sons of Reuben the firstborn of Israel, (for he was the firstborn; but, forasmuch as he defiled his fatherâ€™s bed, his birthright was given unto the sons of Joseph the son of Israel: and the genealogy is not to be reckoned after the birthright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 2, E'For Judah prevailed above his brethren, and of him came the chief ruler; but the birthright was Josephâ€™s:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 3, E'The sons, I say, of Reuben the firstborn of Israel were, Hanoch, and Pallu, Hezron, and Carmi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 4, E'The sons of Joel; Shemaiah his son, Gog his son, Shimei his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 5, E'Micah his son, Reaia his son, Baal his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 6, E'Beerah his son, whom Tilgathpilneser king of Assyria carried away captive: he was prince of the Reubenites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 7, E'And his brethren by their families, when the genealogy of their generations was reckoned, were the chief, Jeiel, and Zechariah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 8, E'And Bela the son of Azaz, the son of Shema, the son of Joel, who dwelt in Aroer, even unto Nebo and Baalmeon:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 9, E'And eastward he inhabited unto the entering in of the wilderness from the river Euphrates: because their cattle were multiplied in the land of Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 10, E'And in the days of Saul they made war with the Hagarites, who fell by their hand: and they dwelt in their tents throughout all the east land of Gilead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 11, E'And the children of Gad dwelt over against them, in the land of Bashan unto Salcah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 12, E'Joel the chief, and Shapham the next, and Jaanai, and Shaphat in Bashan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 13, E'And their brethren of the house of their fathers were, Michael, and Meshullam, and Sheba, and Jorai, and Jachan, and Zia, and Heber, seven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 14, E'These are the children of Abihail the son of Huri, the son of Jaroah, the son of Gilead, the son of Michael, the son of Jeshishai, the son of Jahdo, the son of Buz;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 15, E'Ahi the son of Abdiel, the son of Guni, chief of the house of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 16, E'And they dwelt in Gilead in Bashan, and in her towns, and in all the suburbs of Sharon, upon their borders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 17, E'All these were reckoned by genealogies in the days of Jotham king of Judah, and in the days of Jeroboam king of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 18, E'The sons of Reuben, and the Gadites, and half the tribe of Manasseh, of valiant men, men able to bear buckler and sword, and to shoot with bow, and skilful in war, were four and forty thousand seven hundred and threescore, that went out to the war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 19, E'And they made war with the Hagarites, with Jetur, and Nephish, and Nodab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 20, E'And they were helped against them, and the Hagarites were delivered into their hand, and all that were with them: for they cried to God in the battle, and he was intreated of them; because they put their trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 21, E'And they took away their cattle; of their camels fifty thousand, and of sheep two hundred and fifty thousand, and of asses two thousand, and of men an hundred thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 22, E'For there fell down many slain, because the war was of God. And they dwelt in their steads until the captivity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 23, E'And the children of the half tribe of Manasseh dwelt in the land: they increased from Bashan unto Baalhermon and Senir, and unto mount Hermon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 24, E'And these were the heads of the house of their fathers, even Epher, and Ishi, and Eliel, and Azriel, and Jeremiah, and Hodaviah, and Jahdiel, mighty men of valour, famous men, and heads of the house of their fathers.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 25, E'And they transgressed against the God of their fathers, and went a whoring after the gods of the people of the land, whom God destroyed before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 5, 26, E'And the God of Israel stirred up the spirit of Pul king of Assyria, and the spirit of Tilgathpilneser king of Assyria, and he carried them away, even the Reubenites, and the Gadites, and the half tribe of Manasseh, and brought them unto Halah, and Habor, and Hara, and to the river Gozan, unto this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 1, E'The sons of Levi; Gershon, Kohath, and Merari.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 2, E'And the sons of Kohath; Amram, Izhar, and Hebron, and Uzziel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 3, E'And the children of Amram; Aaron, and Moses, and Miriam. The sons also of Aaron; Nadab, and Abihu, Eleazar, and Ithamar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 4, E'Eleazar begat Phinehas, Phinehas begat Abishua,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 5, E'And Abishua begat Bukki, and Bukki begat Uzzi,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 6, E'And Uzzi begat Zerahiah, and Zerahiah begat Meraioth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 7, E'Meraioth begat Amariah, and Amariah begat Ahitub,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 8, E'And Ahitub begat Zadok, and Zadok begat Ahimaaz,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 9, E'And Ahimaaz begat Azariah, and Azariah begat Johanan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 10, E'And Johanan begat Azariah, (he it is that executed the priestâ€™s office in the temple that Solomon built in Jerusalem:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 11, E'And Azariah begat Amariah, and Amariah begat Ahitub,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 12, E'And Ahitub begat Zadok, and Zadok begat Shallum,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 13, E'And Shallum begat Hilkiah, and Hilkiah begat Azariah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 14, E'And Azariah begat Seraiah, and Seraiah begat Jehozadak,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 15, E'And Jehozadak went into captivity, when the LORD carried away Judah and Jerusalem by the hand of Nebuchadnezzar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 16, E'The sons of Levi; Gershom, Kohath, and Merari.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 17, E'And these be the names of the sons of Gershom; Libni, and Shimei.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 18, E'And the sons of Kohath were, Amram, and Izhar, and Hebron, and Uzziel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 19, E'The sons of Merari; Mahli, and Mushi. And these are the families of the Levites according to their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 20, E'Of Gershom; Libni his son, Jahath his son, Zimmah his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 21, E'Joah his son, Iddo his son, Zerah his son, Jeaterai his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 22, E'The sons of Kohath; Amminadab his son, Korah his son, Assir his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 23, E'Elkanah his son, and Ebiasaph his son, and Assir his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 24, E'Tahath his son, Uriel his son, Uzziah his son, and Shaul his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 25, E'And the sons of Elkanah; Amasai, and Ahimoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 26, E'As for Elkanah: the sons of Elkanah; Zophai his son, and Nahath his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 27, E'Eliab his son, Jeroham his son, Elkanah his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 28, E'And the sons of Samuel; the firstborn Vashni, and Abiah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 29, E'The sons of Merari; Mahli, Libni his son, Shimei his son, Uzza his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 30, E'Shimea his son, Haggiah his son, Asaiah his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 31, E'And these are they whom David set over the service of song in the house of the LORD, after that the ark had rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 32, E'And they ministered before the dwelling place of the tabernacle of the congregation with singing, until Solomon had built the house of the LORD in Jerusalem: and then they waited on their office according to their order.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 33, E'And these are they that waited with their children. Of the sons of the Kohathites: Heman a singer, the son of Joel, the son of Shemuel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 34, E'The son of Elkanah, the son of Jeroham, the son of Eliel, the son of Toah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 35, E'The son of Zuph, the son of Elkanah, the son of Mahath, the son of Amasai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 36, E'The son of Elkanah, the son of Joel, the son of Azariah, the son of Zephaniah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 37, E'The son of Tahath, the son of Assir, the son of Ebiasaph, the son of Korah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 38, E'The son of Izhar, the son of Kohath, the son of Levi, the son of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 39, E'And his brother Asaph, who stood on his right hand, even Asaph the son of Berachiah, the son of Shimea,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 40, E'The son of Michael, the son of Baaseiah, the son of Malchiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 41, E'The son of Ethni, the son of Zerah, the son of Adaiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 42, E'The son of Ethan, the son of Zimmah, the son of Shimei,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 43, E'The son of Jahath, the son of Gershom, the son of Levi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 44, E'And their brethren the sons of Merari stood on the left hand: Ethan the son of Kishi, the son of Abdi, the son of Malluch,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 45, E'The son of Hashabiah, the son of Amaziah, the son of Hilkiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 46, E'The son of Amzi, the son of Bani, the son of Shamer,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 47, E'The son of Mahli, the son of Mushi, the son of Merari, the son of Levi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 48, E'Their brethren also the Levites were appointed unto all manner of service of the tabernacle of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 49, E'But Aaron and his sons offered upon the altar of the burnt offering, and on the altar of incense, and were appointed for all the work of the place most holy, and to make an atonement for Israel, according to all that Moses the servant of God had commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 50, E'And these are the sons of Aaron; Eleazar his son, Phinehas his son, Abishua his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 51, E'Bukki his son, Uzzi his son, Zerahiah his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 52, E'Meraioth his son, Amariah his son, Ahitub his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 53, E'Zadok his son, Ahimaaz his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 54, E'Now these are their dwelling places throughout their castles in their coasts, of the sons of Aaron, of the families of the Kohathites: for theirs was the lot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 55, E'And they gave them Hebron in the land of Judah, and the suburbs thereof round about it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 56, E'But the fields of the city, and the villages thereof, they gave to Caleb the son of Jephunneh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 57, E'And to the sons of Aaron they gave the cities of Judah, namely, Hebron, the city of refuge, and Libnah with her suburbs, and Jattir, and Eshtemoa, with their suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 58, E'And Hilen with her suburbs, Debir with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 59, E'And Ashan with her suburbs, and Bethshemesh with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 60, E'And out of the tribe of Benjamin; Geba with her suburbs, and Alemeth with her suburbs, and Anathoth with her suburbs. All their cities throughout their families were thirteen cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 61, E'And unto the sons of Kohath, which were left of the family of that tribe, were cities given out of the half tribe, namely, out of the half tribe of Manasseh, by lot, ten cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 62, E'And to the sons of Gershom throughout their families out of the tribe of Issachar, and out of the tribe of Asher, and out of the tribe of Naphtali, and out of the tribe of Manasseh in Bashan, thirteen cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 63, E'Unto the sons of Merari were given by lot, throughout their families, out of the tribe of Reuben, and out of the tribe of Gad, and out of the tribe of Zebulun, twelve cities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 64, E'And the children of Israel gave to the Levites these cities with their suburbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 65, E'And they gave by lot out of the tribe of the children of Judah, and out of the tribe of the children of Simeon, and out of the tribe of the children of Benjamin, these cities, which are called by their names.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 66, E'And the residue of the families of the sons of Kohath had cities of their coasts out of the tribe of Ephraim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 67, E'And they gave unto them, of the cities of refuge, Shechem in mount Ephraim with her suburbs; they gave also Gezer with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 68, E'And Jokmeam with her suburbs, and Bethhoron with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 69, E'And Aijalon with her suburbs, and Gathrimmon with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 70, E'And out of the half tribe of Manasseh; Aner with her suburbs, and Bileam with her suburbs, for the family of the remnant of the sons of Kohath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 71, E'Unto the sons of Gershom were given out of the family of the half tribe of Manasseh, Golan in Bashan with her suburbs, and Ashtaroth with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 72, E'And out of the tribe of Issachar; Kedesh with her suburbs, Daberath with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 73, E'And Ramoth with her suburbs, and Anem with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 74, E'And out of the tribe of Asher; Mashal with her suburbs, and Abdon with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 75, E'And Hukok with her suburbs, and Rehob with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 76, E'And out of the tribe of Naphtali; Kedesh in Galilee with her suburbs, and Hammon with her suburbs, and Kirjathaim with her suburbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 77, E'Unto the rest of the children of Merari were given out of the tribe of Zebulun, Rimmon with her suburbs, Tabor with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 78, E'And on the other side Jordan by Jericho, on the east side of Jordan, were given them out of the tribe of Reuben, Bezer in the wilderness with her suburbs, and Jahzah with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 79, E'Kedemoth also with her suburbs, and Mephaath with her suburbs:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 80, E'And out of the tribe of Gad; Ramoth in Gilead with her suburbs, and Mahanaim with her suburbs,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 6, 81, E'And Heshbon with her suburbs, and Jazer with her suburbs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 1, E'Now the sons of Issachar were, Tola, and Puah, Jashub, and Shimrom, four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 2, E'And the sons of Tola; Uzzi, and Rephaiah, and Jeriel, and Jahmai, and Jibsam, and Shemuel, heads of their fatherâ€™s house, to wit, of Tola: they were valiant men of might in their generations; whose number was in the days of David two and twenty thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 3, E'And the sons of Uzzi; Izrahiah: and the sons of Izrahiah; Michael, and Obadiah, and Joel, Ishiah, five: all of them chief men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 4, E'And with them, by their generations, after the house of their fathers, were bands of soldiers for war, six and thirty thousand men: for they had many wives and sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 5, E'And their brethren among all the families of Issachar were valiant men of might, reckoned in all by their genealogies fourscore and seven thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 6, E'The sons of Benjamin; Bela, and Becher, and Jediael, three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 7, E'And the sons of Bela; Ezbon, and Uzzi, and Uzziel, and Jerimoth, and Iri, five; heads of the house of their fathers, mighty men of valour; and were reckoned by their genealogies twenty and two thousand and thirty and four.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 8, E'And the sons of Becher; Zemira, and Joash, and Eliezer, and Elioenai, and Omri, and Jerimoth, and Abiah, and Anathoth, and Alameth. All these are the sons of Becher.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 9, E'And the number of them, after their genealogy by their generations, heads of the house of their fathers, mighty men of valour, was twenty thousand and two hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 10, E'The sons also of Jediael; Bilhan: and the sons of Bilhan; Jeush, and Benjamin, and Ehud, and Chenaanah, and Zethan, and Tharshish, and Ahishahar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 11, E'All these the sons of Jediael, by the heads of their fathers, mighty men of valour, were seventeen thousand and two hundred soldiers, fit to go out for war and battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 12, E'Shuppim also, and Huppim, the children of Ir, and Hushim, the sons of Aher.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 13, E'The sons of Naphtali; Jahziel, and Guni, and Jezer, and Shallum, the sons of Bilhah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 14, E'The sons of Manasseh; Ashriel, whom she bare: (but his concubine the Aramitess bare Machir the father of Gilead:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 15, E'And Machir took to wife the sister of Huppim and Shuppim, whose sisterâ€™s name was Maachah;) and the name of the second was Zelophehad: and Zelophehad had daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 16, E'And Maachah the wife of Machir bare a son, and she called his name Peresh; and the name of his brother was Sheresh; and his sons were Ulam and Rakem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 17, E'And the sons of Ulam; Bedan. These were the sons of Gilead, the son of Machir, the son of Manasseh.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 18, E'And his sister Hammoleketh bare Ishod, and Abiezer, and Mahalah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 19, E'And the sons of Shemidah were, Ahian, and Shechem, and Likhi, and Aniam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 20, E'And the sons of Ephraim; Shuthelah, and Bered his son, and Tahath his son, and Eladah his son, and Tahath his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 21, E'And Zabad his son, and Shuthelah his son, and Ezer, and Elead, whom the men of Gath that were born in that land slew, because they came down to take away their cattle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 22, E'And Ephraim their father mourned many days, and his brethren came to comfort him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 23, E'And when he went in to his wife, she conceived, and bare a son, and he called his name Beriah, because it went evil with his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 24, E'(And his daughter was Sherah, who built Bethhoron the nether, and the upper, and Uzzensherah.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 25, E'And Rephah was his son, also Resheph, and Telah his son, and Tahan his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 26, E'Laadan his son, Ammihud his son, Elishama his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 27, E'Non his son, Jehoshuah his son,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 28, E'And their possessions and habitations were, Bethel and the towns thereof, and eastward Naaran, and westward Gezer, with the towns thereof; Shechem also and the towns thereof, unto Gaza and the towns thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 29, E'And by the borders of the children of Manasseh, Bethshean and her towns, Taanach and her towns, Megiddo and her towns, Dor and her towns. In these dwelt the children of Joseph the son of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 30, E'The sons of Asher; Imnah, and Isuah, and Ishuai, and Beriah, and Serah their sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 31, E'And the sons of Beriah; Heber, and Malchiel, who is the father of Birzavith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 32, E'And Heber begat Japhlet, and Shomer, and Hotham, and Shua their sister.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 33, E'And the sons of Japhlet; Pasach, and Bimhal, and Ashvath. These are the children of Japhlet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 34, E'And the sons of Shamer; Ahi, and Rohgah, Jehubbah, and Aram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 35, E'And the sons of his brother Helem; Zophah, and Imna, and Shelesh, and Amal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 36, E'The sons of Zophah; Suah, and Harnepher, and Shual, and Beri, and Imrah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 37, E'Bezer, and Hod, and Shamma, and Shilshah, and Ithran, and Beera.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 38, E'And the sons of Jether; Jephunneh, and Pispah, and Ara.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 39, E'And the sons of Ulla; Arah, and Haniel, and Rezia.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 7, 40, E'All these were the children of Asher, heads of their fatherâ€™s house, choice and mighty men of valour, chief of the princes. And the number throughout the genealogy of them that were apt to the war and to battle was twenty and six thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 1, E'Now Benjamin begat Bela his firstborn, Ashbel the second, and Aharah the third,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 2, E'Nohah the fourth, and Rapha the fifth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 3, E'And the sons of Bela were, Addar, and Gera, and Abihud,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 4, E'And Abishua, and Naaman, and Ahoah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 5, E'And Gera, and Shephuphan, and Huram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 6, E'And these are the sons of Ehud: these are the heads of the fathers of the inhabitants of Geba, and they removed them to Manahath:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 7, E'And Naaman, and Ahiah, and Gera, he removed them, and begat Uzza, and Ahihud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 8, E'And Shaharaim begat children in the country of Moab, after he had sent them away; Hushim and Baara were his wives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 9, E'And he begat of Hodesh his wife, Jobab, and Zibia, and Mesha, and Malcham,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 10, E'And Jeuz, and Shachia, and Mirma. These were his sons, heads of the fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 11, E'And of Hushim he begat Abitub, and Elpaal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 12, E'The sons of Elpaal; Eber, and Misham, and Shamed, who built Ono, and Lod, with the towns thereof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 13, E'Beriah also, and Shema, who were heads of the fathers of the inhabitants of Aijalon, who drove away the inhabitants of Gath:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 14, E'And Ahio, Shashak, and Jeremoth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 15, E'And Zebadiah, and Arad, and Ader,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 16, E'And Michael, and Ispah, and Joha, the sons of Beriah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 17, E'And Zebadiah, and Meshullam, and Hezeki, and Heber,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 18, E'Ishmerai also, and Jezliah, and Jobab, the sons of Elpaal;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 19, E'And Jakim, and Zichri, and Zabdi,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 20, E'And Elienai, and Zilthai, and Eliel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 21, E'And Adaiah, and Beraiah, and Shimrath, the sons of Shimhi;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 22, E'And Ishpan, and Heber, and Eliel,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 23, E'And Abdon, and Zichri, and Hanan,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 24, E'And Hananiah, and Elam, and Antothijah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 25, E'And Iphedeiah, and Penuel, the sons of Shashak;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 26, E'And Shamsherai, and Shehariah, and Athaliah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 27, E'And Jaresiah, and Eliah, and Zichri, the sons of Jeroham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 28, E'These were heads of the fathers, by their generations, chief men. These dwelt in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 29, E'And at Gibeon dwelt the father of Gibeon; whose wifeâ€™s name was Maachah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 30, E'And his firstborn son Abdon, and Zur, and Kish, and Baal, and Nadab,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 31, E'And Gedor, and Ahio, and Zacher.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 32, E'And Mikloth begat Shimeah. And these also dwelt with their brethren in Jerusalem, over against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 33, E'And Ner begat Kish, and Kish begat Saul, and Saul begat Jonathan, and Malchishua, and Abinadab, and Eshbaal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 34, E'And the son of Jonathan was Meribbaal; and Meribbaal begat Micah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 35, E'And the sons of Micah were, Pithon, and Melech, and Tarea, and Ahaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 36, E'And Ahaz begat Jehoadah; and Jehoadah begat Alemeth, and Azmaveth, and Zimri; and Zimri begat Moza,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 37, E'And Moza begat Binea: Rapha was his son, Eleasah his son, Azel his son:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 38, E'And Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan. All these were the sons of Azel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 39, E'And the sons of Eshek his brother were, Ulam his firstborn, Jehush the second, and Eliphelet the third.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 8, 40, E'And the sons of Ulam were mighty men of valour, archers, and had many sons, and sonsâ€™ sons, an hundred and fifty. All these are of the sons of Benjamin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 1, E'So all Israel were reckoned by genealogies; and, behold, they were written in the book of the kings of Israel and Judah, who were carried away to Babylon for their transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 2, E'Now the first inhabitants that dwelt in their possessions in their cities were, the Israelites, the priests, Levites, and the Nethinims.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 3, E'And in Jerusalem dwelt of the children of Judah, and of the children of Benjamin, and of the children of Ephraim, and Manasseh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 4, E'Uthai the son of Ammihud, the son of Omri, the son of Imri, the son of Bani, of the children of Pharez the son of Judah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 5, E'And of the Shilonites; Asaiah the firstborn, and his sons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 6, E'And of the sons of Zerah; Jeuel, and their brethren, six hundred and ninety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 7, E'And of the sons of Benjamin; Sallu the son of Meshullam, the son of Hodaviah, the son of Hasenuah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 8, E'And Ibneiah the son of Jeroham, and Elah the son of Uzzi, the son of Michri, and Meshullam the son of Shephathiah, the son of Reuel, the son of Ibnijah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 9, E'And their brethren, according to their generations, nine hundred and fifty and six. All these men were chief of the fathers in the house of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 10, E'And of the priests; Jedaiah, and Jehoiarib, and Jachin,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 11, E'And Azariah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, the ruler of the house of God;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 12, E'And Adaiah the son of Jeroham, the son of Pashur, the son of Malchijah, and Maasiai the son of Adiel, the son of Jahzerah, the son of Meshullam, the son of Meshillemith, the son of Immer;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 13, E'And their brethren, heads of the house of their fathers, a thousand and seven hundred and threescore; very able men for the work of the service of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 14, E'And of the Levites; Shemaiah the son of Hasshub, the son of Azrikam, the son of Hashabiah, of the sons of Merari;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 15, E'And Bakbakkar, Heresh, and Galal, and Mattaniah the son of Micah, the son of Zichri, the son of Asaph;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 16, E'And Obadiah the son of Shemaiah, the son of Galal, the son of Jeduthun, and Berechiah the son of Asa, the son of Elkanah, that dwelt in the villages of the Netophathites.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 17, E'And the porters were, Shallum, and Akkub, and Talmon, and Ahiman, and their brethren: Shallum was the chief;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 18, E'Who hitherto waited in the kingâ€™s gate eastward: they were porters in the companies of the children of Levi.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 19, E'And Shallum the son of Kore, the son of Ebiasaph, the son of Korah, and his brethren, of the house of his father, the Korahites, were over the work of the service, keepers of the gates of the tabernacle: and their fathers, being over the host of the LORD, were keepers of the entry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 20, E'And Phinehas the son of Eleazar was the ruler over them in time past, and the LORD was with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 21, E'And Zechariah the son of Meshelemiah was porter of the door of the tabernacle of the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 22, E'All these which were chosen to be porters in the gates were two hundred and twelve. These were reckoned by their genealogy in their villages, whom David and Samuel the seer did ordain in their set office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 23, E'So they and their children had the oversight of the gates of the house of the LORD, namely, the house of the tabernacle, by wards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 24, E'In four quarters were the porters, toward the east, west, north, and south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 25, E'And their brethren, which were in their villages, were to come after seven days from time to time with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 26, E'For these Levites, the four chief porters, were in their set office, and were over the chambers and treasuries of the house of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 27, E'And they lodged round about the house of God, because the charge was upon them, and the opening thereof every morning pertained to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 28, E'And certain of them had the charge of the ministering vessels, that they should bring them in and out by tale.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 29, E'Some of them also were appointed to oversee the vessels, and all the instruments of the sanctuary, and the fine flour, and the wine, and the oil, and the frankincense, and the spices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 30, E'And some of the sons of the priests made the ointment of the spices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 31, E'And Mattithiah, one of the Levites, who was the firstborn of Shallum the Korahite, had the set office over the things that were made in the pans.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 32, E'And other of their brethren, of the sons of the Kohathites, were over the shewbread, to prepare it every sabbath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 33, E'And these are the singers, chief of the fathers of the Levites, who remaining in the chambers were free: for they were employed in that work day and night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 34, E'These chief fathers of the Levites were chief throughout their generations; these dwelt at Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 35, E'And in Gibeon dwelt the father of Gibeon, Jehiel, whose wifeâ€™s name was Maachah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 36, E'And his firstborn son Abdon, then Zur, and Kish, and Baal, and Ner, and Nadab,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 37, E'And Gedor, and Ahio, and Zechariah, and Mikloth.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 38, E'And Mikloth begat Shimeam. And they also dwelt with their brethren at Jerusalem, over against their brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 39, E'And Ner begat Kish; and Kish begat Saul; and Saul begat Jonathan, and Malchishua, and Abinadab, and Eshbaal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 40, E'And the son of Jonathan was Meribbaal: and Meribbaal begat Micah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 41, E'And the sons of Micah were, Pithon, and Melech, and Tahrea, and Ahaz.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 42, E'And Ahaz begat Jarah; and Jarah begat Alemeth, and Azmaveth, and Zimri; and Zimri begat Moza;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 43, E'And Moza begat Binea; and Rephaiah his son, Eleasah his son, Azel his son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 9, 44, E'And Azel had six sons, whose names are these, Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan: these were the sons of Azel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 1, E'Now the Philistines fought against Israel; and the men of Israel fled from before the Philistines, and fell down slain in mount Gilboa.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 2, E'And the Philistines followed hard after Saul, and after his sons; and the Philistines slew Jonathan, and Abinadab, and Malchishua, the sons of Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 3, E'And the battle went sore against Saul, and the archers hit him, and he was wounded of the archers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 4, E'Then said Saul to his armourbearer, Draw thy sword, and thrust me through therewith; lest these uncircumcised come and abuse me. But his armourbearer would not; for he was sore afraid. So Saul took a sword, and fell upon it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 5, E'And when his armourbearer saw that Saul was dead, he fell likewise on the sword, and died.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 6, E'So Saul died, and his three sons, and all his house died together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 7, E'And when all the men of Israel that were in the valley saw that they fled, and that Saul and his sons were dead, then they forsook their cities, and fled: and the Philistines came and dwelt in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 8, E'And it came to pass on the morrow, when the Philistines came to strip the slain, that they found Saul and his sons fallen in mount Gilboa.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 9, E'And when they had stripped him, they took his head, and his armour, and sent into the land of the Philistines round about, to carry tidings unto their idols, and to the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 10, E'And they put his armour in the house of their gods, and fastened his head in the temple of Dagon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 11, E'And when all Jabeshgilead heard all that the Philistines had done to Saul,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 12, E'They arose, all the valiant men, and took away the body of Saul, and the bodies of his sons, and brought them to Jabesh, and buried their bones under the oak in Jabesh, and fasted seven days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 13, E'So Saul died for his transgression which he committed against the LORD, even against the word of the LORD, which he kept not, and also for asking counsel of one that had a familiar spirit, to enquire of it;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 10, 14, E'And enquired not of the LORD: therefore he slew him, and turned the kingdom unto David the son of Jesse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 1, E'Then all Israel gathered themselves to David unto Hebron, saying, Behold, we are thy bone and thy flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 2, E'And moreover in time past, even when Saul was king, thou wast he that leddest out and broughtest in Israel: and the LORD thy God said unto thee, Thou shalt feed my people Israel, and thou shalt be ruler over my people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 3, E'Therefore came all the elders of Israel to the king to Hebron; and David made a covenant with them in Hebron before the LORD; and they anointed David king over Israel, according to the word of the LORD by Samuel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 4, E'And David and all Israel went to Jerusalem, which is Jebus; where the Jebusites were, the inhabitants of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 5, E'And the inhabitants of Jebus said to David, Thou shalt not come hither. Nevertheless David took the castle of Zion, which is the city of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 6, E'And David said, Whosoever smiteth the Jebusites first shall be chief and captain. So Joab the son of Zeruiah went first up, and was chief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 7, E'And David dwelt in the castle; therefore they called it the city of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 8, E'And he built the city round about, even from Millo round about: and Joab repaired the rest of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 9, E'So David waxed greater and greater: for the LORD of hosts was with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 10, E'These also are the chief of the mighty men whom David had, who strengthened themselves with him in his kingdom, and with all Israel, to make him king, according to the word of the LORD concerning Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 11, E'And this is the number of the mighty men whom David had; Jashobeam, an Hachmonite, the chief of the captains: he lifted up his spear against three hundred slain by him at one time.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 12, E'And after him was Eleazar the son of Dodo, the Ahohite, who was one of the three mighties.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 13, E'He was with David at Pasdammim, and there the Philistines were gathered together to battle, where was a parcel of ground full of barley; and the people fled from before the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 14, E'And they set themselves in the midst of that parcel, and delivered it, and slew the Philistines; and the LORD saved them by a great deliverance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 15, E'Now three of the thirty captains went down to the rock to David, into the cave of Adullam; and the host of the Philistines encamped in the valley of Rephaim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 16, E'And David was then in the hold, and the Philistinesâ€™ garrison was then at Bethlehem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 17, E'And David longed, and said, Oh that one would give me drink of the water of the well of Bethlehem, that is at the gate!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 18, E'And the three brake through the host of the Philistines, and drew water out of the well of Bethlehem, that was by the gate, and took it, and brought it to David: but David would not drink of it, but poured it out to the LORD,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 19, E'And said, My God forbid it me, that I should do this thing: shall I drink the blood of these men that have put their lives in jeopardy? for with the jeopardy of their lives they brought it. Therefore he would not drink it. These things did these three mightiest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 20, E'And Abishai the brother of Joab, he was chief of the three: for lifting up his spear against three hundred, he slew them, and had a name among the three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 21, E'Of the three, he was more honourable than the two; for he was their captain: howbeit he attained not to the first three.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 22, E'Benaiah the son of Jehoiada, the son of a valiant man of Kabzeel, who had done many acts; he slew two lionlike men of Moab: also he went down and slew a lion in a pit in a snowy day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 23, E'And he slew an Egyptian, a man of great stature, five cubits high; and in the Egyptianâ€™s hand was a spear like a weaverâ€™s beam; and he went down to him with a staff, and plucked the spear out of the Egyptianâ€™s hand, and slew him with his own spear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 24, E'These things did Benaiah the son of Jehoiada, and had the name among the three mighties.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 25, E'Behold, he was honourable among the thirty, but attained not to the first three: and David set him over his guard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 26, E'Also the valiant men of the armies were, Asahel the brother of Joab, Elhanan the son of Dodo of Bethlehem,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 27, E'Shammoth the Harorite, Helez the Pelonite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 28, E'Ira the son of Ikkesh the Tekoite, Abiezer the Antothite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 29, E'Sibbecai the Hushathite, Ilai the Ahohite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 30, E'Maharai the Netophathite, Heled the son of Baanah the Netophathite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 31, E'Ithai the son of Ribai of Gibeah, that pertained to the children of Benjamin, Benaiah the Pirathonite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 32, E'Hurai of the brooks of Gaash, Abiel the Arbathite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 33, E'Azmaveth the Baharumite, Eliahba the Shaalbonite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 34, E'The sons of Hashem the Gizonite, Jonathan the son of Shage the Hararite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 35, E'Ahiam the son of Sacar the Hararite, Eliphal the son of Ur,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 36, E'Hepher the Mecherathite, Ahijah the Pelonite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 37, E'Hezro the Carmelite, Naarai the son of Ezbai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 38, E'Joel the brother of Nathan, Mibhar the son of Haggeri,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 39, E'Zelek the Ammonite, Naharai the Berothite, the armourbearer of Joab the son of Zeruiah,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 40, E'Ira the Ithrite, Gareb the Ithrite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 41, E'Uriah the Hittite, Zabad the son of Ahlai,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 42, E'Adina the son of Shiza the Reubenite, a captain of the Reubenites, and thirty with him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 43, E'Hanan the son of Maachah, and Joshaphat the Mithnite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 44, E'Uzzia the Ashterathite, Shama and Jehiel the sons of Hothan the Aroerite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 45, E'Jediael the son of Shimri, and Joha his brother, the Tizite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 46, E'Eliel the Mahavite, and Jeribai, and Joshaviah, the sons of Elnaam, and Ithmah the Moabite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 11, 47, E'Eliel, and Obed, and Jasiel the Mesobaite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 1, E'Now these are they that came to David to Ziklag, while he yet kept himself close because of Saul the son of Kish: and they were among the mighty men, helpers of the war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 2, E'They were armed with bows, and could use both the right hand and the left in hurling stones and shooting arrows out of a bow, even of Saulâ€™s brethren of Benjamin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 3, E'The chief was Ahiezer, then Joash, the sons of Shemaah the Gibeathite; and Jeziel, and Pelet, the sons of Azmaveth; and Berachah, and Jehu the Antothite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 4, E'And Ismaiah the Gibeonite, a mighty man among the thirty, and over the thirty; and Jeremiah, and Jahaziel, and Johanan, and Josabad the Gederathite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 5, E'Eluzai, and Jerimoth, and Bealiah, and Shemariah, and Shephatiah the Haruphite,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 6, E'Elkanah, and Jesiah, and Azareel, and Joezer, and Jashobeam, the Korhites,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 7, E'And Joelah, and Zebadiah, the sons of Jeroham of Gedor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 8, E'And of the Gadites there separated themselves unto David into the hold to the wilderness men of might, and men of war fit for the battle, that could handle shield and buckler, whose faces were like the faces of lions, and were as swift as the roes upon the mountains;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 9, E'Ezer the first, Obadiah the second, Eliab the third,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 10, E'Mishmannah the fourth, Jeremiah the fifth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 11, E'Attai the sixth, Eliel the seventh,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 12, E'Johanan the eighth, Elzabad the ninth,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 13, E'Jeremiah the tenth, Machbanai the eleventh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 14, E'These were of the sons of Gad, captains of the host: one of the least was over an hundred, and the greatest over a thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 15, E'These are they that went over Jordan in the first month, when it had overflown all his banks; and they put to flight all them of the valleys, both toward the east, and toward the west.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 16, E'And there came of the children of Benjamin and Judah to the hold unto David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 17, E'And David went out to meet them, and answered and said unto them, If ye be come peaceably unto me to help me, mine heart shall be knit unto you: but if ye be come to betray me to mine enemies, seeing there is no wrong in mine hands, the God of our fathers look thereon, and rebuke it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 18, E'Then the spirit came upon Amasai, who was chief of the captains, and he said, Thine are we, David, and on thy side, thou son of Jesse: peace, peace be unto thee, and peace be to thine helpers; for thy God helpeth thee. Then David received them, and made them captains of the band.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 19, E'And there fell some of Manasseh to David, when he came with the Philistines against Saul to battle: but they helped them not: for the lords of the Philistines upon advisement sent him away, saying, He will fall to his master Saul to the jeopardy of our heads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 20, E'As he went to Ziklag, there fell to him of Manasseh, Adnah, and Jozabad, and Jediael, and Michael, and Jozabad, and Elihu, and Zilthai, captains of the thousands that were of Manasseh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 21, E'And they helped David against the band of the rovers: for they were all mighty men of valour, and were captains in the host.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 22, E'For at that time day by day there came to David to help him, until it was a great host, like the host of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 23, E'And these are the numbers of the bands that were ready armed to the war, and came to David to Hebron, to turn the kingdom of Saul to him, according to the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 24, E'The children of Judah that bare shield and spear were six thousand and eight hundred, ready armed to the war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 25, E'Of the children of Simeon, mighty men of valour for the war, seven thousand and one hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 26, E'Of the children of Levi four thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 27, E'And Jehoiada was the leader of the Aaronites, and with him were three thousand and seven hundred;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 28, E'And Zadok, a young man mighty of valour, and of his fatherâ€™s house twenty and two captains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 29, E'And of the children of Benjamin, the kindred of Saul, three thousand: for hitherto the greatest part of them had kept the ward of the house of Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 30, E'And of the children of Ephraim twenty thousand and eight hundred, mighty men of valour, famous throughout the house of their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 31, E'And of the half tribe of Manasseh eighteen thousand, which were expressed by name, to come and make David king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 32, E'And of the children of Issachar, which were men that had understanding of the times, to know what Israel ought to do; the heads of them were two hundred; and all their brethren were at their commandment.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 33, E'Of Zebulun, such as went forth to battle, expert in war, with all instruments of war, fifty thousand, which could keep rank: they were not of double heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 34, E'And of Naphtali a thousand captains, and with them with shield and spear thirty and seven thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 35, E'And of the Danites expert in war twenty and eight thousand and six hundred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 36, E'And of Asher, such as went forth to battle, expert in war, forty thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 37, E'And on the other side of Jordan, of the Reubenites, and the Gadites, and of the half tribe of Manasseh, with all manner of instruments of war for the battle, an hundred and twenty thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 38, E'All these men of war, that could keep rank, came with a perfect heart to Hebron, to make David king over all Israel: and all the rest also of Israel were of one heart to make David king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 39, E'And there they were with David three days, eating and drinking: for their brethren had prepared for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 12, 40, E'Moreover they that were nigh them, even unto Issachar and Zebulun and Naphtali, brought bread on asses, and on camels, and on mules, and on oxen, and meat, meal, cakes of figs, and bunches of raisins, and wine, and oil, and oxen, and sheep abundantly: for there was joy in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 1, E'And David consulted with the captains of thousands and hundreds, and with every leader.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 2, E'And David said unto all the congregation of Israel, If it seem good unto you, and that it be of the LORD our God, let us send abroad unto our brethren every where, that are left in all the land of Israel, and with them also to the priests and Levites which are in their cities and suburbs, that they may gather themselves unto us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 3, E'And let us bring again the ark of our God to us: for we enquired not at it in the days of Saul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 4, E'And all the congregation said that they would do so: for the thing was right in the eyes of all the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 5, E'So David gathered all Israel together, from Shihor of Egypt even unto the entering of Hemath, to bring the ark of God from Kirjathjearim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 6, E'And David went up, and all Israel, to Baalah, that is, to Kirjathjearim, which belonged to Judah, to bring up thence the ark of God the LORD, that dwelleth between the cherubims, whose name is called on it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 7, E'And they carried the ark of God in a new cart out of the house of Abinadab: and Uzza and Ahio drave the cart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 8, E'And David and all Israel played before God with all their might, and with singing, and with harps, and with psalteries, and with timbrels, and with cymbals, and with trumpets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 9, E'And when they came unto the threshingfloor of Chidon, Uzza put forth his hand to hold the ark; for the oxen stumbled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 10, E'And the anger of the LORD was kindled against Uzza, and he smote him, because he put his hand to the ark: and there he died before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 11, E'And David was displeased, because the LORD had made a breach upon Uzza: wherefore that place is called Perezuzza to this day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 12, E'And David was afraid of God that day, saying, How shall I bring the ark of God home to me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 13, E'So David brought not the ark home to himself to the city of David, but carried it aside into the house of Obededom the Gittite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 13, 14, E'And the ark of God remained with the family of Obededom in his house three months. And the LORD blessed the house of Obededom, and all that he had.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 1, E'Now Hiram king of Tyre sent messengers to David, and timber of cedars, with masons and carpenters, to build him an house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 2, E'And David perceived that the LORD had confirmed him king over Israel, for his kingdom was lifted up on high, because of his people Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 3, E'And David took more wives at Jerusalem: and David begat more sons and daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 4, E'Now these are the names of his children which he had in Jerusalem; Shammua, and Shobab, Nathan, and Solomon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 5, E'And Ibhar, and Elishua, and Elpalet,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 6, E'And Nogah, and Nepheg, and Japhia,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 7, E'And Elishama, and Beeliada, and Eliphalet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 8, E'And when the Philistines heard that David was anointed king over all Israel, all the Philistines went up to seek David. And David heard of it, and went out against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 9, E'And the Philistines came and spread themselves in the valley of Rephaim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 10, E'And David enquired of God, saying, Shall I go up against the Philistines? And wilt thou deliver them into mine hand? And the LORD said unto him, Go up; for I will deliver them into thine hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 11, E'So they came up to Baalperazim; and David smote them there. Then David said, God hath broken in upon mine enemies by mine hand like the breaking forth of waters: therefore they called the name of that place Baalperazim.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 12, E'And when they had left their gods there, David gave a commandment, and they were burned with fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 13, E'And the Philistines yet again spread themselves abroad in the valley.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 14, E'Therefore David enquired again of God; and God said unto him, Go not up after them; turn away from them, and come upon them over against the mulberry trees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 15, E'And it shall be, when thou shalt hear a sound of going in the tops of the mulberry trees, that then thou shalt go out to battle: for God is gone forth before thee to smite the host of the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 16, E'David therefore did as God commanded him: and they smote the host of the Philistines from Gibeon even to Gazer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 14, 17, E'And the fame of David went out into all lands; and the LORD brought the fear of him upon all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 1, E'And David made him houses in the city of David, and prepared a place for the ark of God, and pitched for it a tent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 2, E'Then David said, None ought to carry the ark of God but the Levites: for them hath the LORD chosen to carry the ark of God, and to minister unto him for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 3, E'And David gathered all Israel together to Jerusalem, to bring up the ark of the LORD unto his place, which he had prepared for it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 4, E'And David assembled the children of Aaron, and the Levites:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 5, E'Of the sons of Kohath; Uriel the chief, and his brethren an hundred and twenty:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 6, E'Of the sons of Merari; Asaiah the chief, and his brethren two hundred and twenty:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 7, E'Of the sons of Gershom; Joel the chief, and his brethren an hundred and thirty:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 8, E'Of the sons of Elizaphan; Shemaiah the chief, and his brethren two hundred:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 9, E'Of the sons of Hebron; Eliel the chief, and his brethren fourscore:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 10, E'Of the sons of Uzziel; Amminadab the chief, and his brethren an hundred and twelve.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 11, E'And David called for Zadok and Abiathar the priests, and for the Levites, for Uriel, Asaiah, and Joel, Shemaiah, and Eliel, and Amminadab,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 12, E'And said unto them, Ye are the chief of the fathers of the Levites: sanctify yourselves, both ye and your brethren, that ye may bring up the ark of the LORD God of Israel unto the place that I have prepared for it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 13, E'For because ye did it not at the first, the LORD our God made a breach upon us, for that we sought him not after the due order.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 14, E'So the priests and the Levites sanctified themselves to bring up the ark of the LORD God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 15, E'And the children of the Levites bare the ark of God upon their shoulders with the staves thereon, as Moses commanded according to the word of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 16, E'And David spake to the chief of the Levites to appoint their brethren to be the singers with instruments of musick, psalteries and harps and cymbals, sounding, by lifting up the voice with joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 17, E'So the Levites appointed Heman the son of Joel; and of his brethren, Asaph the son of Berechiah; and of the sons of Merari their brethren, Ethan the son of Kushaiah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 18, E'And with them their brethren of the second degree, Zechariah, Ben, and Jaaziel, and Shemiramoth, and Jehiel, and Unni, Eliab, and Benaiah, and Maaseiah, and Mattithiah, and Elipheleh, and Mikneiah, and Obededom, and Jeiel, the porters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 19, E'So the singers, Heman, Asaph, and Ethan, were appointed to sound with cymbals of brass;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 20, E'And Zechariah, and Aziel, and Shemiramoth, and Jehiel, and Unni, and Eliab, and Maaseiah, and Benaiah, with psalteries on Alamoth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 21, E'And Mattithiah, and Elipheleh, and Mikneiah, and Obededom, and Jeiel, and Azaziah, with harps on the Sheminith to excel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 22, E'And Chenaniah, chief of the Levites, was for song: he instructed about the song, because he was skilful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 23, E'And Berechiah and Elkanah were doorkeepers for the ark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 24, E'And Shebaniah, and Jehoshaphat, and Nethaneel, and Amasai, and Zechariah, and Benaiah, and Eliezer, the priests, did blow with the trumpets before the ark of God: and Obededom and Jehiah were doorkeepers for the ark.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 25, E'So David, and the elders of Israel, and the captains over thousands, went to bring up the ark of the covenant of the LORD out of the house of Obededom with joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 26, E'And it came to pass, when God helped the Levites that bare the ark of the covenant of the LORD, that they offered seven bullocks and seven rams.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 27, E'And David was clothed with a robe of fine linen, and all the Levites that bare the ark, and the singers, and Chenaniah the master of the song with the singers: David also had upon him an ephod of linen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 28, E'Thus all Israel brought up the ark of the covenant of the LORD with shouting, and with sound of the cornet, and with trumpets, and with cymbals, making a noise with psalteries and harps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 15, 29, E'And it came to pass, as the ark of the covenant of the LORD came to the city of David, that Michal, the daughter of Saul looking out at a window saw king David dancing and playing: and she despised him in her heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 1, E'So they brought the ark of God, and set it in the midst of the tent that David had pitched for it: and they offered burnt sacrifices and peace offerings before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 2, E'And when David had made an end of offering the burnt offerings and the peace offerings, he blessed the people in the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 3, E'And he dealt to every one of Israel, both man and woman, to every one a loaf of bread, and a good piece of flesh, and a flagon of wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 4, E'And he appointed certain of the Levites to minister before the ark of the LORD, and to record, and to thank and praise the LORD God of Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 5, E'Asaph the chief, and next to him Zechariah, Jeiel, and Shemiramoth, and Jehiel, and Mattithiah, and Eliab, and Benaiah, and Obededom: and Jeiel with psalteries and with harps; but Asaph made a sound with cymbals;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 6, E'Benaiah also and Jahaziel the priests with trumpets continually before the ark of the covenant of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 7, E'Then on that day David delivered first this psalm to thank the LORD into the hand of Asaph and his brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 8, E'Give thanks unto the LORD, call upon his name, make known his deeds among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 9, E'Sing unto him, sing psalms unto him, talk ye of all his wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 10, E'Glory ye in his holy name: let the heart of them rejoice that seek the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 11, E'Seek the LORD and his strength, seek his face continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 12, E'Remember his marvellous works that he hath done, his wonders, and the judgments of his mouth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 13, E'O ye seed of Israel his servant, ye children of Jacob, his chosen ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 14, E'He is the LORD our God; his judgments are in all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 15, E'Be ye mindful always of his covenant; the word which he commanded to a thousand generations;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 16, E'Even of the covenant which he made with Abraham, and of his oath unto Isaac;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 17, E'And hath confirmed the same to Jacob for a law, and to Israel for an everlasting covenant,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 18, E'Saying, Unto thee will I give the land of Canaan, the lot of your inheritance;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 19, E'When ye were but few, even a few, and strangers in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 20, E'And when they went from nation to nation, and from one kingdom to another people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 21, E'He suffered no man to do them wrong: yea, he reproved kings for their sakes,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 22, E'Saying, Touch not mine anointed, and do my prophets no harm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 23, E'Sing unto the LORD, all the earth; shew forth from day to day his salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 24, E'Declare his glory among the heathen; his marvellous works among all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 25, E'For great is the LORD, and greatly to be praised: he also is to be feared above all gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 26, E'For all the gods of the people are idols: but the LORD made the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 27, E'Glory and honour are in his presence; strength and gladness are in his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 28, E'Give unto the LORD, ye kindreds of the people, give unto the LORD glory and strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 29, E'Give unto the LORD the glory due unto his name: bring an offering, and come before him: worship the LORD in the beauty of holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 30, E'Fear before him, all the earth: the world also shall be stable, that it be not moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 31, E'Let the heavens be glad, and let the earth rejoice: and let men say among the nations, The LORD reigneth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 32, E'Let the sea roar, and the fulness thereof: let the fields rejoice, and all that is therein.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 33, E'Then shall the trees of the wood sing out at the presence of the LORD, because he cometh to judge the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 34, E'O give thanks unto the LORD; for he is good; for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 35, E'And say ye, Save us, O God of our salvation, and gather us together, and deliver us from the heathen, that we may give thanks to thy holy name, and glory in thy praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 36, E'Blessed be the LORD God of Israel for ever and ever. And all the people said, Amen, and praised the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 37, E'So he left there before the ark of the covenant of the LORD Asaph and his brethren, to minister before the ark continually, as every dayâ€™s work required:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 38, E'And Obededom with their brethren, threescore and eight; Obededom also the son of Jeduthun and Hosah to be porters:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 39, E'And Zadok the priest, and his brethren the priests, before the tabernacle of the LORD in the high place that was at Gibeon,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 40, E'To offer burnt offerings unto the LORD upon the altar of the burnt offering continually morning and evening, and to do according to all that is written in the law of the LORD, which he commanded Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 41, E'And with them Heman and Jeduthun, and the rest that were chosen, who were expressed by name, to give thanks to the LORD, because his mercy endureth for ever;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 42, E'And with them Heman and Jeduthun with trumpets and cymbals for those that should make a sound, and with musical instruments of God. And the sons of Jeduthun were porters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 16, 43, E'And all the people departed every man to his house: and David returned to bless his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 1, E'Now it came to pass, as David sat in his house, that David said to Nathan the prophet, Lo, I dwell in an house of cedars, but the ark of the covenant of the LORD remaineth under curtains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 2, E'Then Nathan said unto David, Do all that is in thine heart; for God is with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 3, E'And it came to pass the same night, that the word of God came to Nathan, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 4, E'Go and tell David my servant, Thus saith the LORD, Thou shalt not build me an house to dwell in:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 5, E'For I have not dwelt in an house since the day that I brought up Israel unto this day; but have gone from tent to tent, and from one tabernacle to another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 6, E'Wheresoever I have walked with all Israel, spake I a word to any of the judges of Israel, whom I commanded to feed my people, saying, Why have ye not built me an house of cedars?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 7, E'Now therefore thus shalt thou say unto my servant David, Thus saith the LORD of hosts, I took thee from the sheepcote, even from following the sheep, that thou shouldest be ruler over my people Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 8, E'And I have been with thee whithersoever thou hast walked, and have cut off all thine enemies from before thee, and have made thee a name like the name of the great men that are in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 9, E'Also I will ordain a place for my people Israel, and will plant them, and they shall dwell in their place, and shall be moved no more; neither shall the children of wickedness waste them any more, as at the beginning,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 10, E'And since the time that I commanded judges to be over my people Israel. Moreover I will subdue all thine enemies. Furthermore I tell thee that the LORD will build thee an house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 11, E'And it shall come to pass, when thy days be expired that thou must go to be with thy fathers, that I will raise up thy seed after thee, which shall be of thy sons; and I will establish his kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 12, E'He shall build me an house, and I will stablish his throne for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 13, E'I will be his father, and he shall be my son: and I will not take my mercy away from him, as I took it from him that was before thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 14, E'But I will settle him in mine house and in my kingdom for ever: and his throne shall be established for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 15, E'According to all these words, and according to all this vision, so did Nathan speak unto David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 16, E'And David the king came and sat before the LORD, and said, Who am I, O LORD God, and what is mine house, that thou hast brought me hitherto?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 17, E'And yet this was a small thing in thine eyes, O God; for thou hast also spoken of thy servantâ€™s house for a great while to come, and hast regarded me according to the estate of a man of high degree, O LORD God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 18, E'What can David speak more to thee for the honour of thy servant? for thou knowest thy servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 19, E'O LORD, for thy servantâ€™s sake, and according to thine own heart, hast thou done all this greatness, in making known all these great things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 20, E'O LORD, there is none like thee, neither is there any God beside thee, according to all that we have heard with our ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 21, E'And what one nation in the earth is like thy people Israel, whom God went to redeem to be his own people, to make thee a name of greatness and terribleness, by driving out nations from before thy people, whom thou hast redeemed out of Egypt?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 22, E'For thy people Israel didst thou make thine own people for ever; and thou, LORD, becamest their God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 23, E'Therefore now, LORD, let the thing that thou hast spoken concerning thy servant and concerning his house be established for ever, and do as thou hast said.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 24, E'Let it even be established, that thy name may be magnified for ever, saying, The LORD of hosts is the God of Israel, even a God to Israel: and let the house of David thy servant be established before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 25, E'For thou, O my God, hast told thy servant that thou wilt build him an house: therefore thy servant hath found in his heart to pray before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 26, E'And now, LORD, thou art God, and hast promised this goodness unto thy servant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 17, 27, E'Now therefore let it please thee to bless the house of thy servant, that it may be before thee for ever: for thou blessest, O LORD, and it shall be blessed for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 1, E'Now after this it came to pass, that David smote the Philistines, and subdued them, and took Gath and her towns out of the hand of the Philistines.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 2, E'And he smote Moab; and the Moabites became Davidâ€™s servants, and brought gifts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 3, E'And David smote Hadarezer king of Zobah unto Hamath, as he went to stablish his dominion by the river Euphrates.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 4, E'And David took from him a thousand chariots, and seven thousand horsemen, and twenty thousand footmen: David also houghed all the chariot horses, but reserved of them an hundred chariots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 5, E'And when the Syrians of Damascus came to help Hadarezer king of Zobah, David slew of the Syrians two and twenty thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 6, E'Then David put garrisons in Syriadamascus; and the Syrians became Davidâ€™s servants, and brought gifts. Thus the LORD preserved David whithersoever he went.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 7, E'And David took the shields of gold that were on the servants of Hadarezer, and brought them to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 8, E'Likewise from Tibhath, and from Chun, cities of Hadarezer, brought David very much brass, wherewith Solomon made the brasen sea, and the pillars, and the vessels of brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 9, E'Now when Tou king of Hamath heard how David had smitten all the host of Hadarezer king of Zobah;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 10, E'He sent Hadoram his son to king David, to enquire of his welfare, and to congratulate him, because he had fought against Hadarezer, and smitten him; (for Hadarezer had war with Tou;) and with him all manner of vessels of gold and silver and brass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 11, E'Them also king David dedicated unto the LORD, with the silver and the gold that he brought from all these nations; from Edom, and from Moab, and from the children of Ammon, and from the Philistines, and from Amalek.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 12, E'Moreover Abishai the son of Zeruiah slew of the Edomites in the valley of salt eighteen thousand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 13, E'And he put garrisons in Edom; and all the Edomites became Davidâ€™s servants. Thus the LORD preserved David whithersoever he went.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 14, E'So David reigned over all Israel, and executed judgment and justice among all his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 15, E'And Joab the son of Zeruiah was over the host; and Jehoshaphat the son of Ahilud, recorder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 16, E'And Zadok the son of Ahitub, and Abimelech the son of Abiathar, were the priests; and Shavsha was scribe;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 18, 17, E'And Benaiah the son of Jehoiada was over the Cherethites and the Pelethites; and the sons of David were chief about the king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 1, E'Now it came to pass after this, that Nahash the king of the children of Ammon died, and his son reigned in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 2, E'And David said, I will shew kindness unto Hanun the son of Nahash, because his father shewed kindness to me. And David sent messengers to comfort him concerning his father. So the servants of David came into the land of the children of Ammon to Hanun, to comfort him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 3, E'But the princes of the children of Ammon said to Hanun, Thinkest thou that David doth honour thy father, that he hath sent comforters unto thee? are not his servants come unto thee for to search, and to overthrow, and to spy out the land?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 4, E'Wherefore Hanun took Davidâ€™s servants, and shaved them, and cut off their garments in the midst hard by their buttocks, and sent them away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 5, E'Then there went certain, and told David how the men were served. And he sent to meet them: for the men were greatly ashamed. And the king said, Tarry at Jericho until your beards be grown, and then return.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 6, E'And when the children of Ammon saw that they had made themselves odious to David, Hanun and the children of Ammon sent a thousand talents of silver to hire them chariots and horsemen out of Mesopotamia, and out of Syriamaachah, and out of Zobah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 7, E'So they hired thirty and two thousand chariots, and the king of Maachah and his people; who came and pitched before Medeba. And the children of Ammon gathered themselves together from their cities, and came to battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 8, E'And when David heard of it, he sent Joab, and all the host of the mighty men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 9, E'And the children of Ammon came out, and put the battle in array before the gate of the city: and the kings that were come were by themselves in the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 10, E'Now when Joab saw that the battle was set against him before and behind, he chose out of all the choice of Israel, and put them in array against the Syrians.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 11, E'And the rest of the people he delivered unto the hand of Abishai his brother, and they set themselves in array against the children of Ammon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 12, E'And he said, If the Syrians be too strong for me, then thou shalt help me: but if the children of Ammon be too strong for thee, then I will help thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 13, E'Be of good courage, and let us behave ourselves valiantly for our people, and for the cities of our God: and let the LORD do that which is good in his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 14, E'So Joab and the people that were with him drew nigh before the Syrians unto the battle; and they fled before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 15, E'And when the children of Ammon saw that the Syrians were fled, they likewise fled before Abishai his brother, and entered into the city. Then Joab came to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 16, E'And when the Syrians saw that they were put to the worse before Israel, they sent messengers, and drew forth the Syrians that were beyond the river: and Shophach the captain of the host of Hadarezer went before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 17, E'And it was told David; and he gathered all Israel, and passed over Jordan, and came upon them, and set the battle in array against them. So when David had put the battle in array against the Syrians, they fought with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 18, E'But the Syrians fled before Israel; and David slew of the Syrians seven thousand men which fought in chariots, and forty thousand footmen, and killed Shophach the captain of the host.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 19, 19, E'And when the servants of Hadarezer saw that they were put to the worse before Israel, they made peace with David, and became his servants: neither would the Syrians help the children of Ammon any more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 1, E'And it came to pass, that after the year was expired, at the time that kings go out to battle, Joab led forth the power of the army, and wasted the country of the children of Ammon, and came and besieged Rabbah. But David tarried at Jerusalem. And Joab smote Rabbah, and destroyed it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 2, E'And David took the crown of their king from off his head, and found it to weigh a talent of gold, and there were precious stones in it; and it was set upon Davidâ€™s head: and he brought also exceeding much spoil out of the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 3, E'And he brought out the people that were in it, and cut them with saws, and with harrows of iron, and with axes. Even so dealt David with all the cities of the children of Ammon. And David and all the people returned to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 4, E'And it came to pass after this, that there arose war at Gezer with the Philistines; at which time Sibbechai the Hushathite slew Sippai, that was of the children of the giant: and they were subdued.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 5, E'And there was war again with the Philistines; and Elhanan the son of Jair slew Lahmi the brother of Goliath the Gittite, whose spear staff was like a weaverâ€™s beam.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 6, E'And yet again there was war at Gath, where was a man of great stature, whose fingers and toes were four and twenty, six on each hand, and six on each foot and he also was the son of the giant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 7, E'But when he defied Israel, Jonathan the son of Shimea Davidâ€™s brother slew him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 20, 8, E'These were born unto the giant in Gath; and they fell by the hand of David, and by the hand of his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 1, E'And Satan stood up against Israel, and provoked David to number Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 2, E'And David said to Joab and to the rulers of the people, Go, number Israel from Beersheba even to Dan; and bring the number of them to me, that I may know it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 3, E'And Joab answered, The LORD make his people an hundred times so many more as they be: but, my lord the king, are they not all my lordâ€™s servants? why then doth my lord require this thing? why will he be a cause of trespass to Israel?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 4, E'Nevertheless the kingâ€™s word prevailed against Joab. Wherefore Joab departed, and went throughout all Israel, and came to Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 5, E'And Joab gave the sum of the number of the people unto David. And all they of Israel were a thousand thousand and an hundred thousand men that drew sword: and Judah was four hundred threescore and ten thousand men that drew sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 6, E'But Levi and Benjamin counted he not among them: for the kingâ€™s word was abominable to Joab.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 7, E'And God was displeased with this thing; therefore he smote Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 8, E'And David said unto God, I have sinned greatly, because I have done this thing: but now, I beseech thee, do away the iniquity of thy servant; for I have done very foolishly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 9, E'And the LORD spake unto Gad, Davidâ€™s seer, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 10, E'Go and tell David, saying, Thus saith the LORD, I offer thee three things: choose thee one of them, that I may do it unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 11, E'So Gad came to David, and said unto him, Thus saith the LORD, Choose thee'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 12, E'Either three yearsâ€™ famine; or three months to be destroyed before thy foes, while that the sword of thine enemies overtaketh thee; or else three days the sword of the LORD, even the pestilence, in the land, and the angel of the LORD destroying throughout all the coasts of Israel. Now therefore advise thyself what word I shall bring again to him that sent me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 13, E'And David said unto Gad, I am in a great strait: let me fall now into the hand of the LORD; for very great are his mercies: but let me not fall into the hand of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 14, E'So the LORD sent pestilence upon Israel: and there fell of Israel seventy thousand men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 15, E'And God sent an angel unto Jerusalem to destroy it: and as he was destroying, the LORD beheld, and he repented him of the evil, and said to the angel that destroyed, It is enough, stay now thine hand. And the angel of the LORD stood by the threshingfloor of Ornan the Jebusite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 16, E'And David lifted up his eyes, and saw the angel of the LORD stand between the earth and the heaven, having a drawn sword in his hand stretched out over Jerusalem. Then David and the elders of Israel, who were clothed in sackcloth, fell upon their faces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 17, E'And David said unto God, Is it not I that commanded the people to be numbered? even I it is that have sinned and done evil indeed; but as for these sheep, what have they done? let thine hand, I pray thee, O LORD my God, be on me, and on my fatherâ€™s house; but not on thy people, that they should be plagued.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e2289140-dfa0-42f3-87a1-12c541b570c9', 21, 18, E'Then the angel of the LORD commanded Gad to say to David, that David should go up, and set up an altar unto the LORD in the threshingfloor of Ornan the Jebusite.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = '1 Chronicles') b
ON CONFLICT DO NOTHING;

